window.__D("text/ner-mitzva/c000",{"p":[[2800530019,"<h2>שער האמונה</h2>\n(א) <b>הנה</b> ארז\"ל<sup data-n=\"178\">1</sup> בא חבקוק<sup data-n=\"179\">2</sup> והעמידן על אחת שנא' צדיק באמונתו יחיה<sup data-n=\"180\">3</sup> כו' פי' שהאמונה היא שרש כל המצות: ולהבין זה הנה יש להקדים לזה בעיקר ענין מצות מצה בפסח. דמבואר בזהר הטעם לפי שהיא מיכלא דמהימנות'<sup data-n=\"181\">4</sup> שע\"י אכילת מצה לחם עני<sup data-n=\"182\">5</sup> נמשך כח האמונ' האלקי' בכאו\"א מישראל ואפי' כמו משה הי' חייב במצות אכילת מצה בליל הא' כדי להמשיך תוס' כח האמונה האלקי' בנפשו. וזה כפלא איך ע\"י לחם גשמי יתוסף רוחניות האמונה האלקי' ולמה דוקא בלחם מצה שאין בה טעם כלל ולא נתחמץ כו' דהנה ידוע ההפרש שבין לחם חמץ למצה<sup data-n=\"183\">6</sup> הוא שבלחם חמץ יש בה טעם לחם הנרגש ויש בו ההתנשאות וההגבהה כטבע שאור שבעיסה שמחמיץ ועושה נפוח והתפשטות העיסה כו' ולחם מצה הוא בהיפך שאין בו טעם נרגש כלל וגם אינו מתנשא ומתפשט כלל וכלל אלא כמו שהוא וע\"כ נק' לחם עני כו' וע\"כ נאסר החמץ בפסח לפי שמורה ענין ההגבהה והתנשאות ובטעם מורגש ובמצרים היו בשפלות והכנעה עצומה כלחם עני כו' והוא המצה שנשמר מחימוץ ואין בה טעם כלל וזהו עיקר טעם מצותה ע\"ד הפשוט וצ\"ל למה דוקא ע\"י לחם מצה שאין בה טעם כלל יהי' נמשך האמונה כו'. והנה בכתבי האריז\"ל נז' בעיקר טעם ענין מצה שהיא בבחי' קטנות דמוחין דאבא<sup data-n=\"184\">7</sup> וזהו לחמא עניא די אכלו כו' ד' יו\"ד<sup data-n=\"185\">8</sup> נקודה תח\"י כו' כידוע ולכאורה זה סותר לגמרי למ\"ש בזוהר בענין מצה שנק' מיכלא דמהימנותא שהרי האמונה היא למעלה מן הדעת דוקא ואם שרש המצה היא בקטנות דאבא עכ\"פ הרי זה בבחי' החכמ' שנק' אבא<sup data-n=\"186\">9</sup> אלא שהוא בבחי' הקטנות שבה וכידוע דשרש הלחם בחכמה<sup data-n=\"187\">10</sup> דוקא רק שהמצה בקטנות כו' וראי' ממאמ' דאין התינוק יודע לקרות אבא עד שיטעום טעם דגן<sup data-n=\"188\">11</sup> מזה מובן שהמצה עכ\"פ בידיעה שבדעת ואיך נק' מיכלא דמהימנותא אחר שעיקר ענין האמונה היא דוקא למעל' מן הדעת כידוע. אך הנה ארז\"ל לחד מ\"ד דאילן דעה\"ד שאכל אדה\"ר חטה<sup data-n=\"189\">12</sup> היתה כו' הרי החטה בבחי' הדעת דוקא וכמו שהתינוק יודע ומכיר אביו בטעמו טעם חטה דדגן דוקא שאז יש בו הדעת דטו\"ר וטרם שטועם טעם דגן אינו יודע להבחין כ\"כ בין טו\"ר כמ\"ש בטרם ידע<sup data-n=\"190\">13</sup> כו' אך טעם דגן דוקא. ויש להקדים לזה שיש ב' מדריגות בחכמה הא' בחי' חכמה שבאה מאין ליש בטוב טעם ודעת והוא הגדל באדם לפי שניו שכלי מוחו מוכנים לקבל צורת השכל בבחי' טעם וסברא בהתחכמות ממש הגלוי' בכל א' לפי ערכו בכל דבר וענין מה אם בפרנסת טרף נפשו שימציא לו שכל טוב לפרנס א\"ע עד שאמ' והחכמה תחי' בעלי'<sup data-n=\"191\">14</sup> וכה\"ג בדבר חכמה הלימודי' משכיל בטוב טעם כמו שאמ' טוב טעם ודעת למדני<sup data-n=\"192\">15</sup> כו' וכן הוא גם בתינוק קטן יש בו טעם ודעת לקרות אבא כאשר יטעום טעם שבדגן דוקא ולא בימי יניקתו חלב ולא טעם טעם לחם דגן לפי שהטעם שבלחם שרשו בטעם שבחכמ' ע\"כ יש בטעם",[["178","1","<b>הנה ארז\"ל</b>: לדרוש זה הכולל ס\"ט פרקים ראה המאמרים שנסמנו בסמוך.\nלפרקים א-טז ראה ד\"ה להבין שרש ענין חמץ ומצה שנדפס במאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תקנ ואילך. ביאור לד\"ה קול דודי שנדפס בסה\"מ תקס\"ט ע' נד ואילך.\nלפרקים טו-טז ראה מאמרי אדה\"א נ\"ך ע' קנג ואילך.\nלפרקים יז-כא ראה סידור שער חג המצות רפה, ג ואילך.\nלפרקים כב-כח ראה סידור שם רפז, ב ואילך.\nלפרקים כד-כח ראה סה\"מ תקס\"ד ע' רו-ז.\nלפרקים כט-מא ראה ד\"ה המגיד מראשית וביאורו בספר המאמרים תקס\"ה ח\"א ע' רכב ואילך (הנחת הר\"מ בן כ\"ק אדה\"ז).\nלפרקים מב-נא ראה ד\"ה אז ישיר (הנחת כ\"ק אדה\"א) במאמרי אדה\"ז על פרשיות התורה ח\"א ע' רפב (והנחת הר\"מ בן כ\"ק אדה\"ז ב)סה\"מ תקס\"ה ח\"א ע' רלו.\nלפרקים נב-סא ראה ד\"ה ענין קי\"ס (הנחת כ\"ק אדה\"א) במאמרי אדה\"ז על פרשיות התורה ח\"א ע' רנד ו(מגוכי\"ק הצ\"צ) שם ע' רסו. לקו\"ת צו טז, ד.\nלפס\"ב ואילך ראה ד\"ה ההרים רקדו במאמרי אדה\"א ויקרא ח\"א ע' שפז ואילך."],["179","2","<b>בא חבקוק</b>: מכות כד, א. ראה גם לעיל ד, א."],["180","3","<b>צדיק באמונתו יחי'</b>: חבקוק ב, ד [ושם: וצדיק (וכ\"ה לעיל שם) ? ראה לקמן ט, א. שע\"ת ח\"ב פ, ד]."],["181","4","<b>מצה. . מיכלא דמהימנות'</b>: ראה זהר (רע\"מ) בא מא, א. מאמרי אדה\"א ויקרא ח\"ב ע' תרלו. וש\"נ. ראה גם סה\"מ תקס\"ט ע' מה."],["182","5","<b>מצה לחם עני</b>: פ' ראה טז, ג. פסחים קטו, סע\"ב."],["183","6","<b>ההפרש. . חמץ למצה</b>: ראה גם סה\"מ תקס\"ג ח\"א ע' רפג."],["184","7","<b>מצה. . דמוחין דאבא</b>: להלן יב, א מציין בפע\"ח. ראה דרך מצותיך מצות חו\"מ ע' 46. הנסמן במאמרי אדה\"א ויקרא ח\"א ע' רמז."],["185","8","<b>לחמא. . ד' יו\"ד</b>: נוסח ההגדה. ראה פע\"ח (ש' חה\"מ) שכ\"א, פ\"ז בפיסקא הא לחמא."],["186","9","<b>החכמ' שנק' אבא</b>: ראה ע\"ח (שער עתיק) שי\"ב, פ\"א. תניא פ\"ג. הנסמן במאמרי אדה\"א בראשית ע' א."],["187","10","<b>דשרש הלחם בחכמה</b>: בסידור (שער בהמ\"ז קז, ד): כמ\"ש בע\"ח דלחם בגי' מזלא [נסמן לקמן ט, א]."],["188","11","<b>דאין התינוק. . דגן</b>: ראה ברכות מ, סע\"א. הנסמן במאמרי אדה\"א דברים ח\"א ע' רמה? שמות ח\"א ע' קמג. לקמן טו, א ואילך."],["189","12","<b>דאילן דעה\"ד. . חטה</b>: ברכות שם. ראה גם מאמרי אדה\"א במדבר ח\"ב ע' תתמח ואילך. ע' תטו ואילך."],["190","13","<b>בטרם ידע</b>: ישעי' ז, טז."],["191","14","<b>והחכמה תחי' בעלי'</b>: קהלת ז, יב [ושם: החכמה ? ראה מאמרי אדה\"א דברים ח\"א ע' ש. וש\"נ. שע\"ת סח, א ובהנסמן במ\"מ לשם]."],["192","15","<b>טוב טעם ודעת למדני</b>: תהלים קיט, סו."]]],[2800530020,"הלחם להמשיך בחי' הטעם שבחכמ' להיות יודע היטב לאביו שלא הי' בו זה טרם טעמו טעם לחם כלל ודוקא ע\"י טעם הלחם כמ\"ש וחיך יטעום אוכל<sup data-n=\"193\">1</sup> שממשיך טעימת השכל בחיך רוחני בטעמים שבחכמה כמו טעמו וראו<sup data-n=\"194\">2</sup> כו' (דלחם גי' מזלא<sup data-n=\"195\">3</sup> הוא מזל ונוצר) שהחכמ' מאין תמצא<sup data-n=\"196\">4</sup> ליש בטעם דוקא כחיך יטעום אוכל שמרגיש החיות כו' כך החכמה תמצא מאין ליש דבינה בהסבר וטוב טעם כו' והוא אשר גדל באדם ברוב ימים וע\"י מאכלו בטעם חטה כנ\"ל וד\"ל והמדרגה הב' בחכמה היינו בחי' כח מ\"ה דחכמה<sup data-n=\"197\">5</sup> שנק' בחי' אין דיש דחכמה כמ\"ש והחכמה מאין ממש טרם שבאה בבחי' טעם וסברא נגלית והוא הנק' כח המשכיל כל שכל וטעם שנק' מקור השכל שגידולו בהעלם כח השכל דוקא וזהו אך בצלם יתהלך איש<sup data-n=\"198\">6</sup> במקיפי' דחו\"ב בלמ\"ד מ\"ם דצלם (והוא הנק' מזלא ממש טרם שבא לגלוי בכלי המוח בטעם ודעת) שבלתי נגלה עדיין אך הוא גדל והולך בכח השכל ברוב ימים ושנים כמ\"ש ימים ידברו<sup data-n=\"199\">7</sup> ורוב שנים יודיעו חכמה כו' וע\"י הלחם דוקא שהלחם עצמו מגדיל כח השכל שלמעלה מן הטעם והיינו כמו בלחם מצה דלא מליח שאין בו טעם כלל ששרשו בכח מ\"ה ואין דחכמ' שלמעלה מן הטעם דהיינו כמו שהחכמה בבחי' אין ממש. וזהו שרש ענין המצה שנק' מיכלא דמהימנותא והיא בבחי' קטנות דאבא כנ\"ל ואין זה תרתי דסתרי כלל דמה שהמצה בלא טעם הגם שזהו בבחי' קטנות דאבא כשכל שבלא טעם אבל שרשו בכח השכל עצמו שלמעלה מן הטעם והיינו ענין האמונה שעיקרה למעלה מן הטעם כנ\"ל וע\"כ נק' מיכלא דמהימנותא דוקא שזהו ביטול דכח מ\"ה דחכמה שלמעלה מן הטעם כידוע והיינו הך וד\"ל:\n(ב) <b>ולהבין</b> זה בתוס' ביאור הנה כתיב וארשתיך לי באמונה<sup data-n=\"200\">8</sup> כו' וקאי על יצ\"מ דהנה ביצ\"מ הי' בחי' אירוסין שהו' באמונ' וז\"ש וארשתיך לי באמונה ובמ\"ת הי' בחי' נשואין כמ\"ש ביום חתונתו<sup data-n=\"201\">9</sup> כו' כידוע וז\"ש זכרתי לך חסד נעורייך<sup data-n=\"202\">10</sup> דוקא שהוא האמונה ולהבין ענין האמונה שזהו עיקר מצות מצה שנק' מיכלא דמהימנות' שהוא מאכל המחזק כח האמונה כנ\"ל אע\"פ שירושה היא מכבר מן האבות<sup data-n=\"203\">11</sup> מ\"מ ע\"י מצה ניתוסף אורה שתאיר ממקורה יותר עד שכל היחודי' עליונים דתו\"מ תלויי' בה וכמ\"ש בא חבקוק והעמיד כל התרי\"ג מצות על אחת שהיא האמונה וכמ\"ש צדיק באמונתו יחי' כנ\"ל והאמונ' עצמה לא נמנית<sup data-n=\"204\">12</sup> ברמ\"ח מ\"ע כי ירושה היא וכמו טבע בנפשותינו שלא שייך לשון צווי ע\"ז כידוע ואמנם עיקר מקור חיות הנשמה הוא באמונה כמ\"ש באמונתו יחיה בעצם וכל אשר יחי' נשמת האדם ממצו' כמ\"ש אלה המצות כו' וחי בהם<sup data-n=\"205\">13</sup> הן רק בחי' הסתעפות ענפי' מן המקור כו' ולהבין זה הנה עיקר מהות האמונה הוא למעלה מן הדעת שבראיית השכל וכ\"ש במה שרואה בעיניו ממש לא שייך לשון אמונה אלא במה שלא נתפס בראיי' השכל ולא בעין כלל ולפ\"ז לא יגיע כל תוקף האמונה רק לבחי' הראי'",[["193","1","<b>וחיך יטעום אוכל</b>: איוב יב, יא [ושם: אוכל יטעם]. לד, ג [ושם: יטעם לאכל]. ראה מאמרי אדה\"א הנחות תקע\"ז ע' רצז. שמות ח\"א ע' קמה. וש\"נ. דברים ח\"ב ע' תרפב. וש\"נ."],["194","2","<b>טעמו וראו</b>: תהלים לד, ט."],["195","3","<b>דלחם גי' מזלא</b>: להלן (טו, ב) מציין וכידוע בענין ברכת המוציא לחם ? ראה סידור הרש\"ר ח\"ב סדר סעודת ת\"ח כוונת המוציא (א, ב). הנסמן במאמרי אדה\"א ויקרא ח\"א ע' קכב? דברים ח\"ד ע' א'שסה? קונטרסים ע' קמו."],["196","4","<b>שהחכ' מאין תמצא</b>: איוב כח, יב."],["197","5","<b>כח מ\"ה דחכמה</b>: זהר (רע\"מ) צו כח, א. לד, א."],["198","6","<b>אך בצלם יתהלך איש</b>: תהלים לט, ז."],["199","7","<b>ימים ידברו</b>: איוב לב, ז."],["200","8","<b>וארשתיך לי באמונה</b>: הושע ב, כב. וראה גם רד\"ק שם פסוק כא. של\"ה תושב\"כ ויק\"פ שלה, ריש ע\"ב. מאמרי אדה\"א ויקרא ח\"א ע' דש. במדבר ח\"ב ע' תיט."],["201","9","<b>ביום חתונתו</b>: שה\"ש ג, יא. ראה תענית כו, ב. מאמרי אדה\"א דברים ח\"ג ע' תתמז בהערה."],["202","10","<b>זכרתי לך חסד נעורייך</b>: ירמי' ב, ב."],["203","11","<b>האמונה. . שירושה. . מן האבות</b>: נסמן לעיל ו, א."],["204","12","<b>והאמונ'. . לא נמנית</b>: ראה לעיל ז, ב. וש\"נ."],["205","13","<b>אלה המצות כו' וחי בהם</b>: נסמן לקמן סח, ב."]]],[2800530021,"לבד דודאי אין לך גדול במעלות השגות דבר האמת לאמיתתו רק בראי' כשרואה מהו' הדבר ממש כמו שהוא לאמיתתו ולא בשמיע' מרחוק וכמאמ' אינו דומה שמיעה לראי'<sup data-n=\"206\">14</sup> ועיקר הראי' הוא במהות הדבר ודוקא בעין הרואה ולא בראי' השכל כחכם שרואה בשכלו את הנולד וכה\"ג וז\"ש הביטו אליו<sup data-n=\"207\">15</sup> הביטו ממש לאסתכלא ביקרא דמלכא<sup data-n=\"208\">16</sup> בראי' המהות כמו עין בעין יראו<sup data-n=\"209\">17</sup> כו' וכן הוא או' לע\"ל ואמ' ביום ההוא<sup data-n=\"210\">18</sup> הנה אלקינו זה לנוכח כו' וכל תוקפה של כח האמונה שלמעלה מן השגות השכל לא יגיע רק שיהיה כמו הראי' בעין שא\"צ להאמין מאחר שרואה בעיניו ממש וא\"כ אין האמונה למעלה מן הראי' אלא למעלה מן השגת שכל מרחוק שנק' שמיעה שבבינה ואפשר גם למעלה מראיי' השכל שלא ישיג החכם לראות הנולד רק מה שיש ביכולתו לראו' בעין השכל ולא במופלא הימנו שעין שכלו לא ישיג וירא' כלל אבל האמונה מגיע בדבר שלא ישיגו עין השכל כלל וכמ\"ש לית מח' תפיס'<sup data-n=\"211\">19</sup> בך כלל פי' בך במהותו ועצמותו ממש לית מחשב' דראיי' החכמ' תפיסא כלל רק כח האמונה שיאמין במהו\"ע ממש אע\"פ שאינו רואה בעין השכל ולא בראי' העין תוקף האמונה חזקה כ\"כ כאלו רואה בעיניו ממש למהו\"ע דלית מח' ת\"ב כו' וכמו במ\"ת שכל העם רואים<sup data-n=\"212\">20</sup> כו' ועל כל דבור פרחה נשמתן<sup data-n=\"213\">21</sup> כו' או בקי\"ס שאמרו זה אלי ואנוהו<sup data-n=\"214\">22</sup> זה ממש וכן לע\"ל הנה אלקינו זה קוינו לו ממש באמונתינו החזקה מאד שהיא כמו ראי' עד שאין כל חדש בראי' מהו\"ע שהרי האמינו בו כאלו ראוהו ואעפ\"כ אינו דומה האמונה לראי' ממש שהאמונה אם היא בתוקף גדול וראי' ממס\"נ על קדה\"ש מ\"מ אינו רואה מהו\"ע בנפשו מאומה ואמנם הראי' בעין ה\"ז במהו\"ע ממש עד שאמונ' שקדמה כטפל יחשב ובאמת הרי אמ' זכרתי לך חסד נעורייך דוק' שהיא האמונ' וכתי' למען תזכור<sup data-n=\"215\">23</sup> יום צאתך מא\"מ כל ימי חייך להביא לימוה\"מ ולעוה\"ב שיגלה מהו\"ע ממש כידוע בפי' כימי צאתך מא\"מ<sup data-n=\"216\">24</sup> אראנו נפלאות סדכ\"ס דלמת\"ב כלל כו' דלכאורה אין לך גדול יותר מן הראי' בעין באמיתית מהו\"ע לימוהמ\"ש ועוה\"ב ולמה יזכרו אז האמונה שביצ\"מ כו' אך מזה מוכרח לומר שיש מעלה יתירה באמונה יותר גם מן הראי' בעין ממש וזה פלא גדול לכאורה:\n<b>והנה</b> גם במצות מעשיות שהן היחודי' העליונים דאו\"א זו\"נ כו' האמונה שרש עצמי להם כמ\"ש באמונתו יחיה כנ\"ל מזה גם כן מובן שיש יתרון מעלה לאמונה מכל המצות שהן בבחי' אדם דנרנח\"י<sup data-n=\"217\">25</sup> דאצי' שכולל כל רמ\"ח אברים כו' ויש להקדי' לזה בענין תוקף הנפש שיש באמונ' שהיא למעלה הרבה מגופה של האמונה כי גופה של האמונה אע\"פ שהיא למעלה מן הדעת מ\"מ חסרה מכל פנימי' התפעלות השכל ומדות ורצון ותענוג כי הרי אין באמונה שום התפעלות תענוג ורצון ושכל ומדות בלב כלל רק אמונה פשוטה שמאמין בכל לבו ונפשו באמיתית אלקות במהותו ועצמותו ושברא והאציל הכל וכלא קמי' כלא כו' וכה\"ג שזהו כמו טבע ממש גם בקל ופשוט שבפשוטים כו' עד שיוכל למסו\"נ<sup data-n=\"218\">26</sup> בפו\"מ על קדה\"ש וזה פלא גדול מאין",[["206","14","<b>אינו דומה שמיעה לראי'</b>: ראה מכילתא יתרו יט, ט. לק\"ט שלח יג. יח. לקמן מג, ב ואילך. צב, ב ואילך. מאמרי אדה\"א דברים ח\"א ע' קמו ואילך. הנחות תקע\"ז ע' כז. וש\"נ."],["207","15","<b>הביטו אליו</b>: תהלים לד, ו."],["208","16","<b>לאסתכלא ביקרא דמלכא</b>: נסמן לקמן קיא, א."],["209","17","<b>עין בעין יראו</b>: ישעי' נב, ח."],["210","18","<b>ואמ' ביום ההוא</b>: ישעי' כה, ט."],["211","19","<b>לית מח' תפיס'</b>: ת\"ז בהקדמה (יז, א)."],["212","20","<b>במ\"ת שכל העם רואים</b>: יתרו כ, טו."],["213","21","<b>ועל כל דבור פרחה נשמתן</b>: ראה שבת פח, ב. הנסמן במאמרי אדה\"א ויקרא ח\"א ע' ג. נ\"ך ע' שפא. להלן מה, סע\"ב ואילך."],["214","22","<b>זה אלי ואנוהו</b>: בשלח טו, ב."],["215","23","<b>למען תזכור</b>: פ' ראה טז, ג [ושם: את יום]. נסמן לעיל ב, ב."],["216","24","<b>כימי צאתך מא\"מ</b>: מיכה ז, טו. ראה סידור שחה\"מ רצב, א ואילך. לקמן יא, ב. צה, א."],["217","25","<b>דנרנח\"י</b>: ראה ב\"ר פי\"ד, ט. מאמרי אדה\"א דברים ח\"ב ע' תכח. וש\"נ."],["218","26","<b>בקל ופשוט. . למסו\"נ</b>: ראה גם לקמן מב, ב. מאמרי אדה\"א הנחות תקע\"ז ע' קלד. וש\"נ."]]],[2800530022,"יש לו כח גדול ותוקף הנפש כ\"כ אם לא שיש טבע זו בנפש מהולדה בבטן כטבעיות ממש והוא הנק' נשמה כידוע והנה ידוע שזה הכח ועוז הוא נמצא בבחי' כח מ\"ה שבנפש (כמ\"ש בל\"א<sup data-n=\"219\">1</sup> ) ופי' כח מ\"ה<sup data-n=\"220\">2</sup> סובל ב' ענינים הפכיים א' מה לשון מהות כמו מהו כו' והב' לשון העדר השגת מהות כמו מה פשפשת<sup data-n=\"221\">3</sup> כו' מה זה מה ראו על ככה<sup data-n=\"222\">4</sup> כו' והוא לשון ביטול כמו ונחנו מה כי תלינו<sup data-n=\"223\">5</sup> כו' וכך אמר ע\"ס בלי מ\"ה בלי מהות<sup data-n=\"224\">6</sup> וכמו מה שמו<sup data-n=\"225\">7</sup> כו' והענין הוא דשניהם אמת דמה ל' מהות דוקא וזהו הנק' כח מה שבנפש האלקי' והיינו מצד מה שנמצא הכח בעצם הנשמה האלקית ליכלל במהות ועצמות א\"ס ממש דלמת\"ב כלל כנ\"ל אע\"פ שאינו נתפס בראית השכל דחכמה שבנה\"א כלל לפי שזהו כניצוץ הנמשך אחר מהות השלהבת כמ\"ש משכני אחריך נרוצה<sup data-n=\"226\">8</sup> שמרוצה זו אל המהו\"ע דא\"ס דוקא כמו הרואה את המלך שנמשך אחריו נמשך אחר מהו\"ע שלו וכן הוא עיקר ענין הדביקות לדבקה בו יתברך בו דוקא כי זהו מטבעיות עצם הנשמה לידבק במהו\"ע דוקא ולא בשום דבר מה זולתו כמ\"ש מי לי בשמים<sup data-n=\"227\">9</sup> ועמך לא חפצתי כו' וכמו שאנו רואים בכל מס\"נ על קדה\"ש בפשוטים וגדולים שוה ממש שמוסר גופו להריגה או באש רק למען שמו ית' שזהו בהתכללות במהו\"ע ממש ואע\"פ שלא נודע לו בשכל במהו\"ע כלל דלית מחשבה ת\"ב כלל אדרבה היא עיקר ענין האמונה והדביקות האמיתי רק במהו\"ע שאינו נתפס בשום שכל כו' ואמנם מובן מזה עכ\"פ שיש תוקף גדול כזה בעצם הנשמה ליכלל במהו\"ע ה\"ז בחינת מה ל' מהות שמהות ועצמות הנפש נמשכת כולה שלמעלה מראי' השכל והרצון והתענוג שבנפש כו' רק מהותה העצמי ודביקותה והתכללות' במהו\"ע דא\"ס ממש דוקא וזהו הנק' כח מ\"ה שבנפש שבכאו\"א מישראל למס\"נ על קדה\"ש והיא כח האמונה בכל איש מישראל כמו טבעיות במהו\"ע האלקות כנ\"ל (ומזה יבא להם הראי' במהותו ועצמותו לע\"ל כי היינו הך כמ\"ש קוינו לו וכמשי\"ת) והפי' הב' מ\"ה מה פשפשת כו' הוא בחי' הביטול העצמי שבנפש האלקית כמו ונחנו מה כנ\"ל שהוא היפך המהות אדרבה בלא מהות כלל וכלל ובאמת היינו הך שהוא עצם כח המהות של הנשמה ליכלל במהו\"ע כנ\"ל שהרי בחי' הביטול עצמי הזה הוא לתכלית האמת בהפשטת כל עצמו ומהותו לגמרי מכל וכל עד שאינו מרגיש עצמו כלל וכלל וכאילו אינו במציאות כלל וכמו ונחנו מה דמשה שהי' משה בתכלית הביטול בעצם שלזה הי' אא\"ס ממש נגלה בנשמתו כאשר ידבר איש אל רעהו<sup data-n=\"228\">10</sup> כו' כידוע שאא\"ס עצמו אינו שורה כ\"א בבחי' תכלית הביטול לאין משום דעמ\"ר אינו נמשך רק בעמ\"ת<sup data-n=\"229\">11</sup> כמו כי רם ה'<sup data-n=\"230\">12</sup> ושפל יראה שפל דוקא שלפי ערך עצם הרוממות לא ישכון כ\"א בעצם תכלית השפלות כו' כמו מרום וקדוש אשכון<sup data-n=\"231\">13</sup> ואת דכא ושפל רוח כו' וכל שאינו בביטול עצמי כ\"כ לא יקרב למהו\"ע כלל וכלל כידוע ולפ\"ז מובן דבחי' מ\"ה בהעדר כל המהות הוא עצמו ענין מ\"ה דכל המהות כו' דכל עיקר המהות דנשמה האלקית הרי הוא רק לדבקה במהו\"ע כנ\"ל וזהו עצמו",[["219","1","<b>כמ\"ש בל\"א</b>: תניא פי\"ח. פי\"ט."],["220","2","<b>ופי' כח מ\"ה</b>: ראה לקמן טו, א. מאמרי אדה\"א ויקרא ח\"ב ע' תעא. וש\"נ. בראשית ע' ח. וש\"נ. הנחות תקע\"ז ריש ע' כח. תו\"ח בראשית א, ג ובהערה 39."],["221","3","<b>מה פשפשת</b>: זהר בהקדמה א, ב."],["222","4","<b>מה זה מה ראו על ככה</b>: תולדות כז, כ. אסתר ט, כו [ושם: ומה]."],["223","5","<b>ונחנו מה כי תלינו</b>: בשלח טז, ז-ח."],["224","6","<b>ע\"ס. . בלי מהות</b>: ס\"י פ\"א, מ\"ב ובמפרשים שם."],["225","7","<b>מה שמו</b>: שמות ג, יג."],["226","8","<b>משכני אחריך נרוצה</b>: שה\"ש א, ד."],["227","9","<b>מי לי בשמים</b>: תהלים עג, כה."],["228","10","<b>כאשר ידבר איש אל רעהו</b>: תשא לג, יא."],["229","11","<b>דעמ\"ר. . בעמ\"ת</b>: ראה ס\"י פ\"א, מ\"ה. מאמרי אדה\"א דברים ח\"א ע' מג. וש\"נ. שע\"ת כג, א ובהנסמן במ\"מ לשם. לקמן יח, א. קט, א."],["230","12","<b>כי רם ה'</b>: תהלים קלח, ו."],["231","13","<b>מרום וקדוש אשכון</b>: ישעי' נז, טו."]]],[2800530023,"ענין כח הביטול בעצם לתכליתו והיינו עיקר מהות כח האמונה כנ\"ל שהרי עיקר ענין האמונה הוא כח יציאת והמשכת המהות והעצם שלמעלה מעין הראי' דשכל ורצון ועונג ע\"כ התוקף של האמונה מגיע בכל עצמות ומהות דנפש למס\"נ כו' כנ\"ל והוא תכלית הביטול העצמי דבחי' מ\"ה שהוא כח מ\"ה העצמי ליכלל במהו\"ע כנ\"ל וזהו שאמר הנה אלקינו זה בראי' המהות מפני שקוינו לו בזמן הגלות באמונה חזקה דהיינו הך ממש בלי חילוק ביניהם כלל ואדרבה יש תוקף וכח יותר באמונה זו שאינו רואה יותר מכח התכללות בראי' ממש וז\"ש למען תזכור כו' לימוהמ\"ש ועוה\"ב כנ\"ל שהרי כח הראי' בעין הגם שזהו העושה התכללות העצם אינו רק בחי' חצוניות דמה שממשיך את הנפש בהיותו קרוב מאד אל המקור כניצוץ הנמשך אחר אור השלהב' יש בזה מכח המאו' שהוא המושך את הניצוץ וכענין משכני כו' וגם זה אמת דמצד שהניצוץ נלקח משם נמשך לשם בהיותו קרוב אבל בהיותו רחוק לא יומשך כי לא ישיגנו כח המושך מרחו' ביותר משא\"כ ניצוץ האלקי שגם מרחוק יומשך כמו בגלות מצרים שכל גלות הוא עוצם הריחוק כידוע ויצאו משם באמונה פשוטה הרי כח אמונה זאת היא המושכת את הנפש בבחי' התכללות גם מרחוק ה' נראה להם<sup data-n=\"232\">14</sup> כמ\"ש לכתך אחרי<sup data-n=\"233\">15</sup> ממש כו' זהו הוראה גמורה על תוקף התקשרות העצמית הפנימית דנשמה שאין כח גדול כזה גם בכח ראית העין במהות שהרי אין זה חידוש כלל בהיות הניצוץ קרוב ורואה בעין שיומשך שגם זה לא בא מכח עצמיות פנימיות שלו כמו באמונ' וד\"ל אך הנה ביצ\"מ היה גם בחי' ראיית המהות ועצמות א\"ס שהרי אמר ובמורא גדול זו גלוי שכינה<sup data-n=\"234\">16</sup> שנגלה עליהם מלך מה\"מ בכבודו ובעצמו דוקא וזהו ענין קירוב המאור לגבי הניצוצות אמנם זה היה אחר חצות לילה דוקא שזכו לראות במהו\"ע אחר תוקף האמונה שהיה בהם והוכנו כולם לצאת במס\"נ ממש אז זכו באמונה זו לראיית המהו\"ע שנגלה עליהם בכבודו ובעצמו כו' כי הא בהא תליא והיינו הך ממש כנ\"ל וזהו ענין מצה שלפני חצות שנק' מיכלא דמהימנותא ונק' גם כן לחמא עניא כו' דהנה לחם עני הוא בתכלית השפלות שאין בלחם זה שום התפשטות חיות אור ושפע יתירה כלל רק לחיות עצם נפשו שיחיה בה (כמו הבע\"ת שנק' אביוני אדם<sup data-n=\"235\">17</sup> שאין לו רק חיות נפשו לבד שיחיה ולא ימות כו' כמ\"ש במ\"א) ורם ה' ושפל יראה שפל דוקא שהוא עמ\"ת שבו יומשך מבחי' עמ\"ר דוקא כנ\"ל וע\"כ נגלה עליהם מהו\"ע אחר חצות לילה והיינו מצה הב' שאחר חצות<sup data-n=\"236\">18</sup> שלא הספיק בצק' שלהם להחמיץ<sup data-n=\"237\">19</sup> ויאפו את הבצק<sup data-n=\"238\">20</sup> בדרך כידוע שזהו מה שאנו אומרים מצה זו שאנו אוכלים ע\"ש מה בחי' מ\"ה<sup data-n=\"239\">21</sup> העצמי שזהו מחמת הארת מהו\"ע שנגלה כו' והיינו עיקר ענין מצה זו שאנו אוכלים לפי שלא הספיק בצקת של אבותינו להחמיץ הגם שזה היה מחמת שנגלה עליהם כו' והיה בהם בחי' הביטול בעצם בתכלית שלא היה באפשר להחמיץ להיות בבחי' יש כו' מ\"מ הרי הוא ממש ענין כח מ\"ה דנשמה אלקית שבכל איש מישראל במצה זו שאנו אוכלים גם עתה קודם",[["232","14","<b>מרחוק ה' נראה להם</b>: ע\"פ ירמי' לא, ב."],["233","15","<b>לכתך אחרי</b>: ירמי' ב, ב."],["234","16","<b>ובמורא גדול. . שכינה</b>: תבוא כו, ח ובספרי שם. הגש\"פ."],["235","17","<b>הבע\"ת שנק' אביוני אדם</b>: ישעי' כט, יט. ראה מאמרי אדה\"א נ\"ך ע' נא ואילך (ובהנסמן שם ע' כז). בראשית ע' קכב. וש\"נ."],["236","18","<b>מצה הב' שאחר חצות</b>: ראה מאמרי אדה\"ז תקס\"ט ע' מא וע' נח ואילך. תק\"ע ע' סו וע' סח ואילך. ע' עג ואילך. לקו\"ת צו יג, ד ואילך. שה\"ש יד, ד."],["237","19","<b>שלא הספיק. . להחמיץ</b>: ראה הגש\"פ פיסקא מצה."],["238","20","<b>ויאפו את הבצק</b>: בא יב, לט."],["239","21","<b>מצה זו. . בחי' מ\"ה</b>: נוסח ההגדה. ראה גם סידור סדר הגדה חצר, ד."]]],[2800530024,"חצות שהוא בחי' האמונה שתוקף שלה היינו ממש בחי' ביטול העצמי שהיה במורא גדול בגלוי שכינה וע\"כ נקרא מיכלא דמהימנותא עד שגם משה הוצרך לקיים מצות אכילת מצה בלילה ראשונה כדי להוסיף כח האמונה בנשמתו שלמעלה מכח עין השכל והראיה שלו במהו\"ע שלפי ערכו ג\"כ וראיה ממ\"ש למען תזכור אפי' לעוה\"ב כנ\"ל וד\"ל:\n(ג) <b>ובזה</b> יובן ג\"כ ענין האמונה איך שהוא שרש עצמי לכל המצות ואינה נמנית עמהן כלל כנ\"ל דבא חבקוק והעמידן על אחת פי' העמידן כמו הכל הולך אחר המעמיד<sup data-n=\"240\">1</sup> שהמעמיד ומקיים הוא העיקר והיסוד ע\"כ אינו נמנה עם הדבר המתקיים על ידו כך כל המצות הולכין אחר המעמיד והוא האמונה הפשוטה שבפשטות ועצמות מהות הנפש וזהו שהעמיד לכל תרי\"ג מצות על אחת שהיא האמונה וכענין אמת ואמונה כל זאת<sup data-n=\"241\">2</sup> דאמונה בה\"א לשון נוק' שמקבלת מעצמות ומהות א\"ס כמו שהוא ממש לאמיתת עצמותו שנק' אמת וכמ\"ש וה' אלקים אמת<sup data-n=\"242\">3</sup> ואמת ה' לעולם<sup data-n=\"243\">4</sup> וכמאמר דאיהו אמת ואיהי אמונה<sup data-n=\"244\">5</sup> כו' וכמ\"ש דוד אמתך אלקי<sup data-n=\"245\">6</sup> כו' דהאמונה הוא כל בחי' עצמיות ופנימיות כל תוקף וחוזק היותר גדול במהו\"ע הנשמות דישראל שכולל כל מה שיסתעף מזה בקיום התו\"מ ובמס\"נ על קדה\"ש שכולל רמ\"ח מ\"ע ושס\"ה ל\"ת וזהו שהכל הולך אחר המעמיד ומקיים שהאמונה נק' מעמיד ומקיים כל בחי' הסתעפות פרטיות דקיום תו\"מ ותשובה מעומקא דליבא ומס\"נ כו' וזהו וצדיק באמונתו יחיה יחיה חיות העצמי ומקורי כמו שהוא ממש שכולל כל הסתעפות צדקותיו בתו\"מ ותשובה ותפלה ומס\"נ כו' והרי אנו רואים בחוש שגם כל מצות מעשיות מושרשי' כמו טבע בנש\"י בגדול וקטן נשים וטף אין זאת רק חוזק ותוקף האמונה הפשוטה שבעצמיות נפשם מגדול עד קטן בשוה ממש והיא שעמדה לאבותינו ולנו<sup data-n=\"246\">7</sup> כו' שכבר היה כלה כל כח שארית אור הקדושה האלקי' שבנש\"י באור ושפע רצון ותענוג מוחין ומדות אוי\"ר שלהם כו' אלא שהאמונה היא המעמדת הכל והכל הולך אחר המעמיד וזהו שהעמידן על אחת שהיא האמונה ובה יוכלל הכל ויצא לגלוי מן ההעלם בכל דור ודור גם דלא אכשר דרי בתו\"מ ותפלה וצדקה ותשובה כלל וכלל באמונתם יחיו חיי עולם בל תמוט לעמוד נגד כל צר ומסטין לא יעזבם לכלותם ולהפר בריתו אתם כמ\"ש לא מאסתים<sup data-n=\"247\">8</sup> כו' וזהו פי' הפשוט דהיא שעמדה לאבותינו וגם לנו בכל דור שלא אחד בלבד עמד עלינו לכלותינו מצד עונינו שתייסרך רעתך<sup data-n=\"248\">9</sup> לקטרג ולהשחית הכל אלא שהקב\"ה בכבודו ובעצמו דוקא מצילנו מיד המקטרגים ורק מצד האמונה שנק' מעמיד וזהו והיא שעמדה לאבותינו כו' שהאמונה נצחית בל תמוט כמו שהוא ית' אמת לאמיתתו חי לעד וקיים לנצח<sup data-n=\"249\">10</sup> וזהו אמת ואמונה כל זאת כו' דאיהו אמת ואיהי אמונה וכמו דאיהו אמת נצחי חי וקיים לעד כך איהי אמונה שמקבלת אמיתת עצמותו קיימת כענין דוד מ\"י חי וקיים<sup data-n=\"250\">11</sup> כידוע וד\"ל. ולזה אין מהתימה מה שלא נמנית",[["240","1","<b>הכל הולך אחר המעמיד</b>: לשון הגמ' שבת טו, ב."],["241","2","<b>אמת ואמונה כל זאת</b>: תפלת ערבית (ברכת ק\"ש)."],["242","3","<b>וה' אלקים אמת</b>: ירמי' י, י."],["243","4","<b>ואמת ה' לעולם</b>: תהלים קיז, ב."],["244","5","<b>דאיהו אמת ואיהי אמונה</b>: נסמן לעיל ז, א."],["245","6","<b>אמתך אלקי</b>: תהלים עא, כב."],["246","7","<b>והיא שעמדה לאבותינו ולנו</b>: נוסח ההגדה. ראה גם לעיל ז, ב."],["247","8","<b>לא מאסתים</b>: בחוקותי כו, מד."],["248","9","<b>שתייסרך רעתך</b>: נסמן לעיל ה, ב."],["249","10","<b>חי לעד וקיים לנצח</b>: נוסח ברוך שאמר."],["250","11","<b>דוד מ\"י חי וקיים</b>: ראה ר\"ה כה, א (נוסח קידוש לבנה). סה\"מ תקס\"ט ע' קנט. עט\"ר שער ר\"ה ע' ח. מאמרי אדה\"א דברים ח\"ג ע' תתכב."]]],[2800530025,"האמונה בכלל רמ\"ח מ\"ע כי א\"צ לציווי ולבד זה היא יסוד הכל והיסוד אינו נמנה בכלל בנין כי הרי עליו הבנין וקיומו ומעמדו ובנין הוא בא בציור קומה והוא רמ\"ח מ\"ע ושס\"ה ל\"ת דאנכי ולא יהיה לך<sup data-n=\"251\">12</sup> וזהו שאמר אנכי אשר הוצאתיך מא\"מ ולא אמר אשר בראתי שמים וארץ<sup data-n=\"252\">13</sup> מאין ליש ויצ\"מ היו הנסים יש מיש ממים לדם וכה\"ג אך באמת ענין יצ\"מ גדול מכל שרש הראשון דאבי\"ע שהרי ידוע בעיקר ענין חג הפסח שנבדל במעלה מכל המועדים במה שנק' פסח לשון דילוג<sup data-n=\"253\">14</sup> והענין הוא שכל המועדים זולתו היה בהן טעם בהעלאת מ\"ן<sup data-n=\"254\">15</sup> מלמטה שיעורר אתדל\"ע בהמשכות מ\"ד דוגמתו ממש כשבועות במ\"ת שאמרו כל אשר דיבר ה' נעשה<sup data-n=\"255\">16</sup> והיה הכנה לזה בז' שבועות הספי' דוקא וכן יו\"ט דסכות בענני כבוד שבמדבר היו ראוים לזה מצד ההכנה דרבה שקדמ' לזה אך בפסח לא היה שום הכנה כלל מתחלה רק מעצמו ומאליו דילג בערך המדריגה כמ\"ש קול דודי<sup data-n=\"256\">17</sup> הנה זה בא מדלג על ההרים כו' וכן ענין ופסח ה' על הפתח<sup data-n=\"257\">18</sup> כידוע שזהו הכל ענין א' שמה שנק' דילוג בשיר השירים נק' פסח בל' החומש כו' ופסח ודלוג זה היה מעצמו לבד ולכאורה גם במקור התעוררות חפץ חסד להשתלשלות דאבי\"ע היה ג\"כ מעצמו כי חפץ חסד הוא<sup data-n=\"258\">19</sup> כידוע אך זה היה בחי' חיצוניות שלו להיות לו דירה בתחתונים כי סוף מעשה עבמ\"ת<sup data-n=\"259\">20</sup> כידוע אבל ביצ\"מ היה הדילוג מבחי' פנימי' מהו\"ע שלו ממש וע\"כ לא היה שום העלאת מ\"ן מגיע לזה כלל וכלל רק שנגלה עליהם במהו\"ע בלי שום העלאת מ\"ן כלל לפי שהיה הדילוג הזה מבחי' פנימית מהו\"ע ממש שלא יגיע לשם מצוה כלל כמ\"ש אם צדקת מה תתן לו<sup data-n=\"260\">21</sup> כו' אך מ\"מ היה לזה העלאת מ\"ן והוא האמונה החזקה שהאמינו במשה למעלה מן הטעם כלל למס\"נ כו' שזה בא ג\"כ מבחי' פנימית מהות ועצמות דנש\"י כנ\"ל ע\"כ נתעורר בעצמותו כב\"י ג\"כ מבחי' פנימית מהו\"ע ממש רק שלא בא הגלוי הזה באור כלי השגתם כמו במ\"ת ולע\"ל וזהו כימי צאתך מא\"מ אראנו נפלאות סדכ\"ס דלית מח' ת\"ב כלל ולכאורה זהו פלא גדול דכבר נגלה עליהם בכבודו ובעצמו כו' שנק' נפלאות סדכ\"ס כו' אלא שבא הגלוי דסדכ\"ס למטה מטה בהתלבשות שונות לפי ערך מהות נש\"י כמו שהן למטה בגופי' חומריי' אבל לע\"ל אראנו נפלאות האלה ממש כמו שהוא למעלה באמיתת עצמותו ממש וכמ\"ש הנה אלקינו זה ממש וכן מ\"ש יקימנו ונחיה לפניו<sup data-n=\"261\">22</sup> ממש וד\"ל וזהו שבא חבקוק והעמידן על אחת כו' דמאחר שמה שהיה חפץ חסד מעצמו להיות לו דירה בתחתונים ע\"י תו\"מ אינו רק בבחי' חיצוניות לגבי גלוי פנימית מהו\"ע ע\"י העלאת מ\"ן דאמונה פשוטה דוקא כנ\"ל א\"כ ממילא יובן דכל המצות הגם שהם בחי' יח\"ע למעלה הכל הוא בשרש דאבי\"ע שאינו רק מבחי' חפץ חסד חיצוני ואין זה מגיע במהו\"ע ממש רק ע\"י האמונה שהיא דוקא במהו\"ע ממש כנ\"ל בענין הדביקות כו' וזהו שבמ\"ת שקיימו וקבלו כל התורה בי' הדברות אמר אנכי אשר הוצאתיך מא\"מ שזה עולה על כולנה לפי שהכל הולך אחר המעמיד שהוא היסוד",[["251","12","<b>רמ\"ח. . ושס\"ה. . ודאנכי ולא יהי' לך</b>: ראה תניא פ\"כ."],["252","13","<b>אנכי. . שמים וארץ</b>: יתרו כ, ב [בדילוג השמות]. מובא לקמן (יב, ב) בשם פלוסופי'. ראה גם מאמרי אדה\"א ויקרא ח\"א ע' תא ואילך. וש\"נ. במדבר ח\"ב ע' שצז וע' תיט."],["253","14","<b>פסח לשון דילוג</b>: ראה רש\"י בא יב, יא. יג. הנסמן במאמרי אדה\"ז על פרשיות התורה ח\"ב לע' תקלד."],["254","15","<b>המועדים זולתו. . בהעלאת מ\"ן</b>: ראה גם סה\"מ תקס\"ט ע' נד."],["255","16","<b>כל אשר דיבר ה' נעשה</b>: יתרו יט, ח. משפטים כד, ז."],["256","17","<b>קול דודי</b>: שה\"ש ב, ח."],["257","18","<b>ופסח ה' על הפתח</b>: בא יב, כג. ראה סה\"מ תקס\"ט ע' נד ואילך."],["258","19","<b>כי חפץ חסד הוא</b>: מיכה ז, יח. ראה מאמרי אדה\"א הנחות תקע\"ז ע' כד. וש\"נ."],["259","20","<b>סוף מעשה עבמ\"ת</b>: ע\"פ פיוט לכה דודי."],["260","21","<b>אם צדקת מה תתן לו</b>: איוב לה, ז."],["261","22","<b>יקימנו ונחי' לפניו</b>: הושע ו, ב. ראה גם לקמן מה, ב."]]],[2800530026,"לקיים התו\"מ די' הדברות שממילא יש בכלל מאתים מנה<sup data-n=\"262\">1</sup> כו' ונמצא שהאמונה שביצ\"מ היה מקור ויסוד לבחי' הראיה בעין דמ\"ת והא בהא תליא וכך הוא לע\"ל דכתיב להנחיל אוהבי יש<sup data-n=\"263\">2</sup> בעה\"ב מחמת קיום המצות דוקא כידוע ה\"ז בא מיסוד ושרש הראשון דאמונ' שביצ\"מ וזהו זכרתי לך חסד נעורייך דוקא גם לעה\"ב כנ\"ל וזהו וארשתיך לי באמונה דוקא דהגם שהאמונה נק' אירוסין ומ\"ת הי' בבחי' נשואין אבל זכרתי לך חסד נעורייך דבחי' אירוסין יותר מנישואין דמ\"ת לפי שהאירוסין הגם שהוא בבחי' מקיף<sup data-n=\"264\">3</sup> לבד כטבעת קדושין אבל הוא בא מכל כח העצמות כמו שהוא שהיא בבחי' עיגול מקיף מכל צד שכלול בתוכו כל פרטי היחודי' והתולדות שיהיו אחר החופה והוא עיקר המעמיד ומקיים כל הסתעפות תולדות ויחודים שאח\"כ שלא יופר הברית כו' כנ\"ל בפי' והיא שעמדה כו' וכמ\"ש בד\"ח ע\"פ גפן ממצרים תסיע<sup data-n=\"265\">4</sup> בכח אמונה ואח\"כ כסו הרים צילה<sup data-n=\"266\">5</sup> כו' וד\"ל:\n(ד) <b>ומעתה</b> יש להבין בענין הנ\"ל במ\"ש בפע\"ח דמצה הוא בחי' קטנות דאבא<sup data-n=\"267\">6</sup> שזהו על כל פנים בבחי' החכמה והאמונה היא למעלה מן החכמה כנ\"ל אך הנה תחלה יש להבין בפי' קטנות דאבא מהו דהנה ידוע שיש ב' מיני התבוננות א' בממכ\"ע בבחי' השתלשלות דאבי\"ע והב' בבחי' סובב כ\"ע בכלל שהוא הארה מעצמותו ית' ממש כענין יחיד חי העולמים<sup data-n=\"268\">7</sup> שתחלה הוא יחיד לבדו וכן המלך המרומם לבדו<sup data-n=\"269\">8</sup> ואח\"כ מתנשא מימ\"ע בבחי' סוכ\"ע כידוע. והנה בבחי' ממלא כ\"ע אמר שאו מרום כו' וראו מי ברא אלה<sup data-n=\"270\">9</sup> שיתכן בזה בחי' ראיה על כ\"פ והוא ראית השכל שעין השכל יראה איך שברא אלה מאין ליש כמו בדבר ה' שמים נעשו<sup data-n=\"271\">10</sup> ובעשרה מאמרות שנתחלקו לרבבות צירופי' הרי כמו שרואה בעין ממש התהוות העולמות בכל רגע מחדש בטובו מע\"ב מדיבור העליון והדיבור נמשך ממדות דאצי' והמדות מחו\"ב עד מל' דא\"ס שנק' ממכ\"ע בכללות דאבי\"ע וידוע דאע\"פ שאין כל זה רק בחי' הגלוי והתפשטות אור ממהו\"ע ממש כמדת המלוכה שאינו רק התפשטות כו' מ\"מ גם בזה יש בחי' א\"ס כי א\"ס להתפשטותו וכידוע דאא\"ס למטה מטה עד אין תכלית<sup data-n=\"272\">11</sup> גם במל' דאצי' עד מל' דעשי' שנק' כח הפועל אלקי בנפעל ממש מאחר שכח הפועל בעצם בבחי' א\"ס גם פעולותיו מתפשטי' באין שיעור וכמ\"ש בס\"י מכאן ואילך<sup data-n=\"273\">12</sup> צא וחשוב עד אין כו' וכמ\"ש אני ראשון<sup data-n=\"274\">13</sup> שהוא מל' דא\"ס כך אני אחרון במל' דאצי' כמ\"ש ראו עתה<sup data-n=\"275\">14</sup> כי אני אני הוא כו' אך הרי יש בזה בחי' ראיה עכ\"פ ראו מי ברא אלה משא\"כ במהו\"ע דא\"ס כמו שהוא למעלה עד אין שיעור הרי אמר לית מת\"ב כלל<sup data-n=\"276\">15</sup> ונק' סדכ\"ס<sup data-n=\"277\">16</sup> דלא ידע ליה בר איהו<sup data-n=\"278\">17</sup> ונק' נורא תהלות<sup data-n=\"279\">18</sup> כו' והיינו בחי' סובב בכלל שהוא נמשך מיחיד לבדו וכמ\"ש אתה ה' לבדך<sup data-n=\"280\">19</sup> ממש וכמא' דקודם שנבה\"ע הי' הוא ושמו בלבד<sup data-n=\"281\">20</sup> ואנו אומרי' אתה הוא<sup data-n=\"282\">21</sup> כו' באין שינוי כלל והרי אמר בזוהר דאיהו תפיס בכ\"ע<sup data-n=\"283\">22</sup> ולמדת\"ב כי אין העולם מקומו<sup data-n=\"284\">23</sup> אף",[["262","1","<b>יש בכלל מאתים מנה</b>: ב\"ק עד, א."],["263","2","<b>להנחיל אוהבי יש</b>: משלי ח, כא."],["264","3","<b>שהאירוסין. . מקיף</b>: ראה גם מאמרי אדה\"א בראשית ע' ריט. וש\"נ."],["265","4","<b>בד\"ח ע\"פ גפן ממצרים תסיע</b>: ראה שם שער התפלה פ\"צ ואילך. תהלים פ, ט."],["266","5","<b>כסו הרים צילה</b>: תהלים שם, יא."],["267","6","<b>דמצה. . קטנות דאבא</b>: נסמן לעיל ח, ב."],["268","7","<b>יחיד חי העולמים</b>: נוסח ברכת ברוך שאמר וישתבח. ראה גם לקמן נו, ב."],["269","8","<b>המלך המרומם לבדו</b>: ברכת יוצר."],["270","9","<b>שאו מרום. . אלה</b>: ישעי' מ, כו."],["271","10","<b>בדבר ה' שמים נעשו</b>: תהלים לג, ו."],["272","11","<b>דאא\"ס למטה. . תכלית</b>: נסמן לקמן ל, א."],["273","12","<b>בס\"י מכאן ואילך</b>: ראה שם פ\"ד, מי\"ב."],["274","13","<b>אני ראשון</b>: ישעי' מד, ו. ראה גם לקמן קמב, ב. ובהנסמן במ\"מ לשם."],["275","14","<b>ראו עתה</b>: האזינו לב, לט."],["276","15","<b>לית מת\"ב כלל</b>: ת\"ז בהקדמה (יז, א)."],["277","16","<b>סדכ\"ס</b>: ראה זהר בהקדמה ב, א. ועוד."],["278","17","<b>דלא ידע ליה בר איהו</b>: ראה זהר ויקהל רי, ב. (אד\"ר) נשא קכט, ב. קמ, ב. (אד\"ז) האזינו רפח, א."],["279","18","<b>נורא תהלות</b>: בשלח טו, יא."],["280","19","<b>אתה ה' לבדך</b>: נחמי' ט, ו [בדילוג]."],["281","20","<b>דקודם שנבה\"ע. . בלבד</b>: ראה פדר\"א פ\"ג. הנסמן במאמרי אדה\"ז על פרשיות התורה ח\"א לע' שיג? מאמרי אדה\"א דברים ח\"ד ע' א'רעא."],["282","21","<b>אתה הוא</b>: נסמן לקמן קטז, א."],["283","22","<b>דאיהו תפיס בכ\"ע</b>: נסמן לקמן קטו, ב."],["284","23","<b>אין העולם מקומו</b>: נסמן לעיל ב, א."]]],[2800530027,"על פי שהוא מקומו ש\"ע מזה מוכרח לומר דגם בחי' ממכ\"ע בכלל ובפרט דתפיס בכ\"ע מ\"מ אינו נתפס בראי' והשגה דלמחת\"ב ומ\"ש ראו מי ברא אלה היינו בחי' השגות המציאות שאנו רואים כח התפשטות אלקות בנבראים ואיך שהוא אדון על כולא<sup data-n=\"285\">24</sup> כו' אבל לא השגת מהות אור האלקי שמלובש בתוך כ\"ע כמו דלמת\"ב במהו\"ע ממש דהיינו הך וז\"ש כי ה' הוא האלקי' כולא חד<sup data-n=\"286\">25</sup> וע\"ז נצטווינו באמרו אתה הראית לדעת<sup data-n=\"287\">26</sup> כי ה' הוא האלקים ופי' דעת זה הוא בהשגה ובהכרה איך דה' אלקים כולא חד בלי הפרש כלל וזה פלא גדול דהרי למת\"ב לא בסובב דהוי' ולא בממלא כ\"ע אלא צריך לומר דדעת זה היינו להכיר ביטול היש לאין בממלא וסובב שכולא חד דכמו שאין ערוך הנברא לגבי הבורא בשם אלקים כך הוא מתנשא מימ\"ע שאין ערוך כל גלוי אור דממלא בקו\"ח לגבי מהו\"ע ממש וז\"ש כי ה' הוא האלקי' הכל א' דקמי' כולא כלא כו' ולזה יקרא דעת והוא שמכיר את בוראו ואיך יכירנו במהות דלמת\"ב כלל אלא יכירנו בדעת זה שהוא קדוש ומובדל בערך מהכל וממנו הכל שזה עצמו בא ע\"י הדעת והכרה שיכיר ויבחין בזה וכן וידעת היום<sup data-n=\"288\">27</sup> והשבות כו' כי ה' כו' וכן דע את אלקי אביך<sup data-n=\"289\">28</sup> כו' ואין זה כידיעה בשכל לבריאת שמים שאומר בזה לשון ראי' והכרה שזהו היפוך גמור שהרי רואה מהות הבריאה אלא שמשיג ויודע שזהו מציאות התפשטות אור האלקי שנמצא יש מאין אבל הכרה ודעת לבורא היינו שיודע במהותו איך שהוא נבדל בערך אע\"פ שאינו רוא' המהות נתאמת האמת כמו שהוא באמיתת מהו\"ע שהוא יחיד לבדו כו' ומתנשא בבחי' סובב כו' עד דגם בחי' ממלא דתפיס בכ\"ע למת\"ב כלל וכולא חד כנ\"ל ונמצא ידיעה זאת קרובה לבחי' השגת המהות מאחר שמכוין לאמיתת ענינו כמו שהוא באמת וז\"ש אמתך אלקי<sup data-n=\"290\">29</sup> ע\"י בחי' הדעת וכמו לע\"ל דכתיב כולם ידעו אותי<sup data-n=\"291\">30</sup> אותי ממש ואיך ידעו במהו\"ע דלמת\"ב אלא שיכירו וידעו באמתתו איך שהוא מלך מרומם לבדו והוא תפיס בכ\"ע כו' זה יבא בדעת והכרה משא\"כ עכשיו ידיעה זו מרחוק מאד והוא רק באמונה לבד שמאמין באחד ויחיד שהוא סוכ\"ע וממכ\"ע וגם באמרו שמע ישראל כו' אינו נתפס בידיעה והכרה גמורה רק באמונה פשוטה וחזקה מאד כנ\"ל שמגיע למעלה גם מכח הראיה בעין מפני שהוא בא מתוקף הנפש בעצם וז\"ש וארשתיך לי באמונה וידעת<sup data-n=\"292\">31</sup> כו' שתחלה היא תוקף האמונה והיא שמביאה לבחי' הדעת והכרה אמיתית באמיתת מהו\"ע כמו לע\"ל דכתיב כולם ידעו אותי ממש כמים לים מכסים כך ומלאה הארץ<sup data-n=\"293\">32</sup> דעה את הוי' ממש מה שעכשיו אינו נתפס בדעת רק באמונה ואמנם הא בהא תליא וזה גורם לזה דגם עתה האמונה גורמת הדעת שהוא עכ\"פ בבחי' הודאה כענין מודים אנחנו לך<sup data-n=\"294\">33</sup> וכה\"ג וד\"ל (ובזה יובן יותר לתרץ הקושיא דפלוסופי' למה לא אמר אנכי אשר בראתי שמים וארץ שהוא מאין ליש כו' כי זהו רק בחינת התפשטות אורו באבי\"ע שאין ערוך למהות ועצמו' וגם בזה הגלוי למדת\"ב כלל וזה לא נתייחד לאוה\"ע רק לישראל לבד בהיותם במצרים דגם דקרו לי'<sup data-n=\"295\">34</sup> אלקא",[["285","24","<b>אדון על כולא</b>: השמטות לזח\"א רנב, ריש ע\"ב. זהר (רע\"מ) פינחס רלט, א. ת\"ז בהקדמה (ד, א. ו, ב. יז, ב)."],["286","25","<b>כי ה'. . כולא חד</b>: ואתחנן ד, לה. ראה זהר בהקדמה יב, א. תרומה קסא, ב. מאמרי אדה\"א דברים ח\"א ע' קעה (ובהנסמן בריש המאמר שם). הנחות תקע\"ז ע' של ואילך (ובהנסמן בריש המאמר שם). תו\"ח בראשית לה, ד ובהערה 64."],["287","26","<b>את הראית לדעת</b>: ואתחנן שם."],["288","27","<b>וידעת היום</b>: ואתחנן ד, לט."],["289","28","<b>דע את אלקי אביך</b>: דהי\"א כח, ט."],["290","29","<b>אמתך אלקי</b>: תהלים עא, כב."],["291","30","<b>כולם ידעו אותי</b>: ירמי' לא, לג."],["292","31","<b>וארשתיך לי באמונה וידעת</b>: הושע ב, כב."],["293","32","<b>כמים. . ומלאה הארץ</b>: נסמן לעיל ב, א."],["294","33","<b>מודים אנחנו לך</b>: תפלת שמו\"ע."],["295","34","<b>דקרו לי אלקא דאלקייא</b>: מנחות בסופה."]]],[2800530028,"דאלקייא וכתי' מי לא יראך<sup data-n=\"296\">1</sup> מלך הגוים וכמו חסידי אוה\"ע כו' אעפ\"כ במהו\"ע דסובב וממלא אין בהם בחי' הדעת הנ\"ל ולא האמונה רק ישראל לבד שהוטבע זה כטבע בנפשם וכמ\"ש אתה הראית אתה דוקא הראית בדעת זה להכיר לבוראם ביח\"ע ויח\"ת כנ\"ל וכן שמע ישראל דוקא רק שנחלק לב' מדריגות בפסד\"ז מדבר בשבחו<sup data-n=\"297\">2</sup> של מקום בהתפשטו' כח הפועל בנפעל דנבדל ומרומם לבדו גם בהמשכה זאת דכל פסד\"ז וברכת יוצר עיקר הכונה רק בזה כמו הללו את ה'<sup data-n=\"298\">3</sup> מן השמים כו' שזהו ביטול היש לאין עד רום המעלות ואיך שבטל אליו הכל כמו לך ה' הגדולה<sup data-n=\"299\">4</sup> כו' והוא מלך מרומם לבדו ונורא תהלות כו' ובק\"ש הוא מדבר בהשגות מהו\"ע ביחו\"ע<sup data-n=\"300\">5</sup> דאיהו וחיוהי חד<sup data-n=\"301\">6</sup> ממש וביח\"ת דבשכמל\"ו<sup data-n=\"302\">7</sup> שזהו יותר עליון מביטול היש לאין שאינו רק בהשגו' מציאותו והתפשטותו אבל יחו\"ע דמהו\"ע שזהו כמו שהוא לבדו גם אחר שנאצל ונברא באין שינוי כלל וד\"ל וז\"ש אשר הוצאתיך מא\"מ ע\"י האמונה שהיא רק בדביקות במהו\"ע שלמעלה הרבה מבחי' גלוי אור דסובב וממלא דמע\"ב בכלל ובפרט שלא יפול בזה ענין השג' כלל רק האמונ' שנתייחד' לכנ\"י לבד ביצ\"מ כנ\"ל (אך באמ' יש יתרון מעל' ביחו\"ת דבשכמל\"ו אע\"פ שאינו רק ביטול היש לאין כמו בפסד\"ז במ' שהו' בבחי' ראי' מקרוב עכ\"פ ולא בשמיעה מרחוק כשמע ישראל ביח\"ע דאע\"ג דלמדת\"ב גם בממכ\"ע מ\"מ הרי כהפ\"ב<sup data-n=\"303\">8</sup> ממש והרי בא בגלוי השגה ממש רק שמוסתר שם מאד ובהגלות נגלות אור זה לע\"ל הרי יראו במהות אור האלקי זה שבתוך כ\"ע וכמו שאנו אומרי' וידע כל פעול<sup data-n=\"304\">9</sup> כי אתה פעלתו ויבין כל יצור כו' משא\"כ ביח\"ע דלמת\"ב כלל רק לע\"ל דכתיב הנה אלקינו זה<sup data-n=\"305\">10</sup> כו' ולפ\"ז ביחו\"ת דבשכמל\"ו יש בחי' ראי' במהות כמו לע\"ל והיינו ידעו אותי ובאמונ' דעכשיו ביחו\"ע במהו\"ע יבאו לראי' המהות דזה בעצמותו ממש וזהו שמע שמיע' מרחוק ולא ראי' מקרוב וזהו לע\"ל א\"ח עט\"ב<sup data-n=\"306\">11</sup> כידוע וד\"ל) וזהו פי' אנכי ה' אלקיך אנכי מי שאנכי<sup data-n=\"307\">12</sup> דלמת\"ב כלל הוא נעשה ה' אלקיך דוק' בבחי' דעת והכרה שה' הוא האלקי' כמ\"ש אתה הראי' לדעת כו' כנ\"ל אתה דוקא וע\"י מה זכו להיות ה' אלקיך בדעת הוא ע\"י האמונה שהיה בהם ביצ\"מ שז\"ש וארשתיך לי באמונה ואח\"כ במ\"ת וידעת כו' ופי' ידיעה זאת היינו דוקא בידיעת המהות דהוי' שהוא האלקי' כולא חד וכנ\"ל שזה קרוב לראי' המהות כו' שז\"ש אנכי דוקא שאין אנכי זה מתלבש בבריאת שמי' וארץ כלל רק בראשית בחכמה<sup data-n=\"308\">13</sup> כו' וד\"ל:\n<b>(ונמצא</b> מובן מכ\"ז עכ\"פ שהדעת והאמונה אע\"פ שהן כמו ב' הפכים שהאמונ' עיקר מהותה למעלה מן הדעת דוקא מ\"מ הדעת הנ\"ל קרוב לבחי' האמונה מאחר שהידיעה היא בהשג' המהות כראי'<sup data-n=\"309\">14</sup> במהות וכה\"ג שזה תכלית מעלת האמונה שיחשב כאילו רואה בעיניו כנ\"ל) ויובן זה ע\"פ הנ\"ל בב' מדרגות דמ\"ה א' לשון מהות והב' העדר המהות ושניהם א' משום דביטול המציאות בעצם ה\"ז בא במדרגה דראי' המהות והיינו הך כנ\"ל",[["296","1","<b>מי לא יראך</b>: ירמי' י, ז."],["297","2","<b>בפסד\"ז מדבר בשבחו</b>: ראה שו\"ע אדה\"ז הל' ברכות השחר סנ\"א ס\"א."],["298","3","<b>הללו את ה'</b>: תהלים קמח, א."],["299","4","<b>לך ה' הגדולה</b>: דהי\"א כט, יא."],["300","5","<b>ובק\"ש. . ביחו\"ע</b>: זהר בראשית יח, ב."],["301","6","<b>דאיהו וחיוהי חד</b>: ת\"ז בהקדמה (ג, ב)."],["302","7","<b>וביח\"ת דבשכמל\"ו</b>: זהר בראשית יח, ב. פסחים נו, א."],["303","8","<b>כהפ\"ב</b>: כח הפועל בנפעל."],["304","9","<b>וידע כל פעול</b>: תפלת העמידה לר\"ה."],["305","10","<b>הנה אלקינו זה</b>: ישעי' כה, ט."],["306","11","<b>א\"ח עט\"ב</b>: משלי יב, ד."],["307","12","<b>אנכי מי שאנכי</b>: ראה תניא מהדו\"ק ספמ\"ט. אב\"ע תולדות כז, יט. מאמרי אדה\"ז תקס\"ב ח\"א ע' יד. פרשיות התורה ח\"א ע' רט ובהנסמן במ\"מ לשם."],["308","13","<b>בראשית בחכמה</b>: בראשית א, א. ראה מאמרי אדה\"א בראשית ע' א. וש\"נ."],["309","14","<b>כראי'</b>: תוקן ע\"פ דפו\"ר. ובמהדורת לעמבערג: נרא'."]]],[2800530029,"וכך יובן כאן ויובן ג\"כ ענין ב' מצות הנ\"ל בפי' מצה זו שאנו אוכלי' ע\"ש מ\"ה כו' ויש להקדים לזה ענין א' המבואר במ\"א בענין מילוי דה\"א דמצה<sup data-n=\"310\">15</sup> ה\"ה<sup data-n=\"311\">16</sup> שהוא מל' דא\"ס שבהעלם במל' דאצי' וביאור זה יובן ע\"פ הקדמה בענין יראה עילאה ויראה תתאה<sup data-n=\"312\">17</sup> שזהו שאמ' בר\"מ דו\"ר רחימו ודחילו<sup data-n=\"313\">18</sup> והענין הוא דיראה עילאה הוא במל' דא\"ס<sup data-n=\"314\">19</sup> שז\"ש ובמורא גדול זו גלוי שכינה דפי' מורא גדול לשון זכר להיות שהוא שפע אימה ופחד מצד גלוי אור העצמו' כמו שהוא ממש שנק' שמו הגדול שקודם הצמצום דקו\"ח כו' שהמקבל הגלוי זה נק' יראה לשון נוק'<sup data-n=\"315\">20</sup> אבל העושה וממשיך ליראה זו נק' מורא לשון זכר והוא גדול בבחי' גדלות העצמות ונק' יראה זו ירא' עילאה ויראה אותיות ראיה<sup data-n=\"316\">21</sup> שהוא עד\"מ כרואה את המלך במהו\"ע שתפול עליו אימתו בביטול עצמי בלתי הכנה כלל שמצד עצמו' רוממות המלך באה לו אימה זו אבל טרם שנכנס להיכל המלך פנימה הוא מתבונן בדעתו רוממות המלך שמתבטל מכח הכנת עצמו שנק' בטול היש לבד כידוע זהו יראה תתאה שום תשים עליך מלך<sup data-n=\"317\">22</sup> שזהו הכנה לירא' עילאה בראי' המהות כו' שזהו מורא גדול שכולל כל מיני יראה שבמקבלים שכאשר אפס קצה גדולתו מתגלה אין היראה באה רק לפי המדה וזהו בבחי' ממכ\"ע בכלל דצמצום דקו\"ח אבל התגלות כל מהו\"ע כמו שהוא קודם הצמצום בעצמו' גדולתו שאין חקר שנק' מל' דא\"ס נק' מורא גדול וזו גלוי שכינה כמו שהוא בעצמותו כו' וזהו שנגלה עליהם מלך מלכי כו' בחי' מל' דא\"ס עצמו שהאיר בכנ\"י גם בהיותם משוקעים בנש\"ט דמצרים<sup data-n=\"318\">23</sup> משום דקמי' ממש כחשיכה כאורה<sup data-n=\"319\">24</sup> וגם חשך הקליפות דנש\"ט לא יחשיך כו' כמשל העיגול שאין בו מעלה ומטה<sup data-n=\"320\">25</sup> ומתחת לארץ הוא כמו בשמים ממעל ממש בשוה כידוע וזהו ופסח ה' על הפתח<sup data-n=\"321\">26</sup> בבחי' דילוג גדול כמ\"ש במ\"א וד\"ל אבל יראה תתאה הוא במל' דאצי' בבי\"ע שנברא העולם מאין ליש גמור רק שהיש בטל לאין בקבל' מ\"ש שזהו כמו טרם שנכנס להיכל המלך כנ\"ל שעושה בנפשו בחי' ביטול היש לבד שאין זה ביטול עצמי כעומד ורואה במהות המלך ומ\"מ זה גורם לזה והא בהא תליא משום דנעוץ תחלתן בסופן<sup data-n=\"322\">27</sup> כו' וכידוע דסוף מעשה בביטול היש עבמ\"ת במל' דא\"ס שז\"ש אני ראשון כו' אני אני הוא כנ\"ל והיינו ענין מילוי דה' דמצה שיש בה' זה ה' בהעלם והוא בחי' מורא גדול דמל' דא\"ס בראי' המהות שיש בהעלם ביראה תתאה דביטול היש דה' אחרונה משום דנעוץ כו' וזהו מצה זו שאנו אוכלים קודם חצות שהיא בבחי' יראה תתאה קבלת מ\"ש לבד היינו ע\"ש שלא הספיק בצקת כו' שהוא בחי' ביטול העצמי דאחר חצות בירא' עילא' שבראי' המהות כשנגלה עליהם מלך מלכי כו' משום דהא בהא תליא ממש וד\"ל ועד\"ז יובן גם כאן בבחי' ומדריג' יותר עליון והיינו הך שהרי ענין האמונ' הוא רק ביטול והמשכת כל המהות שלמעלה מן הטעם (כקבלת מ\"ש ביטול חיצוני שמבטל א\"ע עכ\"פ רק שהוא בחיצוניו'",[["310","15","<b>מילוי דה\"א דמצה</b>: ראה סה\"מ תקס\"ט ע' נח. מאמרי אדה\"א הנחות תקע\"ז ע' כו. ויקרא ח\"א ע' מ. וש\"נ. שם ע' רצג."],["311","16","<b>דה\"א דמצה ה\"ה</b>: אוצ\"ל: דה' דמצה ה'."],["312","17","<b>יראה עילאה. . תתאה</b>: ראה גם סה\"מ תקס\"ט ע' נט."],["313","18","<b>דו\"ר רחימו ודחילו</b>: ראה זהר (רע\"מ) נשא קכג, סע\"א. מאמרי אדה\"א בראשית ע' לד. וש\"נ. תו\"ח בראשית כא, ג ובהערה 22. שע\"ת כו, א ובהנסמן במ\"מ לשם."],["314","19","<b>דיראה עילאה הוא במל' דא\"ס</b>: ראה סה\"מ תקס\"ט ע' נה ואילך."],["315","20","<b>מורא. . זכר. . יראה לשון נוק'</b>: ראה סה\"מ תקס\"ט ע' נט. שע\"ת ח\"א לד, ג ובהנסמן במ\"מ לשם."],["316","21","<b>ויראה אותיות ראי'</b>: ראה סידור שער הל\"ג בעומר שו, א. שע\"ת ח\"א לו, ג. מאמרי אדה\"א הנחות תקע\"ז ע' נא. וש\"נ. לקמן מה, א."],["317","22","<b>שום תשים עליך מלך</b>: פ' שופטים יז, טו."],["318","23","<b>בכנ\"י. . בנש\"ט דמצרים</b>: ראה ז\"ח יתרו לא, א. סידור ערב שבת קסג, ד. מאמרי אדה\"ז תקס\"ג ח\"א ע' רצא. תקס\"ט ע' מז. מאמרי אדה\"א דברים ח\"ד ע' א'רסב. וש\"נ. הנחות תקע\"ז ע' לב. תו\"ח לך צא, ד ובהערה 48."],["319","24","<b>כחשיכה כאורה</b>: תהלים קלט, יב."],["320","25","<b>העיגול שאין בו מעלה ומטה</b>: ראה לקמן לה, א-ב. מאמרי אדה\"א נ\"ך ע' תמז. וש\"נ. שע\"ת כג, א ובהנסמן במ\"מ לשם."],["321","26","<b>ופסח ה' על הפסח</b>: נסמן לעיל יא, ב."],["322","27","<b>דנעוץ תחלתן בסופן</b>: ראה ס\"י פ\"א מ\"ז."]]],[2800530030,"ובאמונ' הוא מגיע בפנימי' ועצמיו') וזהו בחי' מ\"ה העדר המהות מכל וכל כו' וזהו עכ\"פ מצד עצם הנפש גם בהיותה מרחוק כנ\"ל והדעת הוא כמו בחי' ראי' בקירוב בהשג' המהות כמו לע\"ל שכולם ידעו אותי כו' (והיינו כח מ\"ה ל' מהות כו') שזהו כענין מורא גדול דיראה עילאה אותיות ראי' כו' שהוא מצד התגלו' העצמו' שרוא' במהו\"ע ממש שמתבטל מצד זה ביטול עצמי כנ\"ל וזה גורם לזה דהאמונ' גורמת הראי' מקרוב בדעת כמ\"ת שראו כו' שבאו מכח האמונ' ביצ\"מ כנ\"ל):\n(ה) <b>ובכ\"ז</b> יובן מה שהמצה נק' מיכלא דמהימנותא דוקא וגם היא בבחי' קטנות דאבא שהוא בבחי' מ\"ה דחכמ' כידוע דהנה מבואר למעלה שיש שני מדריגות בשכל אחד למעלה מן הטעם והב' שבא בטע' דוקא ומה שהוא למעלה מן הטע' נק' בחי' קטנות דאבא דוקא ויובן זה עפ\"י הנ\"ל בענין הדע' והאמונ' שאע\"פ שהן שני הפכי' זה גורם לזה משום דהיינו הך כנ\"ל כך הוא במצה שנק' קטנות דאבא ושרש' באמונ' דוקא דהנה מה שאמר שאין התינוק יודע לקרות אבא ואימא<sup data-n=\"323\">1</sup> עד שיטעום טעם דגן הנה ידיעה זו אינה ידיעה בהשגת שכל בטעם הענין ואיכותו איך שהולידו ע\"כ הוא אביו ואשר אהבתו אליו טבעית מצד שהוא אביו וכרחם אב על בן כו' שזהו ידיעה בטוב טעם בבן הגדול דוקא אבל בתינוק הקטן כבן ב' וג' שנים אין לו ידיעה זו בכלי מוחו כלל שיכיל זה הדבר באיכותו כמו שהוא ועכ\"ז הרי הוא קורא אבא ואימא כו' כאלו יודע הדבר ידיעה גמורה אלא מ\"ש יודע לקרות אינה ידיעה בהשגה רק שיודע ומכיר את אביו כמו שיודע השור את קונהו שנמשך והולך אחריו ולא לזולתו כך התינוק מכיר הוא אביו ואמו ונמשך ונדבק תמיד אחריה' ולא לזר זולתם וזה בא מצד הטבע תולדה שנולד מפרי בטנם מושרש בו כח המושך שנמשך למקור המולידו מעצמו בלא טעם כלל וא\"כ ה\"ז בלא דעת והשג' כלל רק בחי' טבעי' כעגל לאמו ובאמת הרי יש בתינוק קטן דעת ממש לקרות בפה אבא כו' והוא דוקא משיטעום טעם דגן ולא בימי יניקתו חלב אמו אע\"פ שמכיר או\"א א\"י לקרות כו' אך הענין הוא דזהו ידיע' שבבחי' הקטנו' עכ\"פ דהיינו שאין הידיע' בהרחבת שכל וטע' אלא שהושפל וירד ונתצמ' בבחי' קטנו' המו' והוא בבחי' הכר' והבחנ' זאת שמכיר ויודע לקרות בדבור לומר אבא שבא עכ\"פ בדעת והכרה (נוסף על המשכ' הטבעי' שמצד התולד' כי אב ואם שנתרחקו ממנו אינו נמשך אחריה' כלל) גם בקטנות גמור כידע שור קונהו<sup data-n=\"324\">2</sup> כשזנו ומפרנסו כו' וישראל לא ידע עמי לא התבונן דמשמע מזה שאם יש דעת והכרה בישראל לאביהם שבשמי' כתינוק שקורא אבא בלא טעם והשגה ועכ\"פ מכירים לאביהם בדעת וקורים אבא כמו שכל אחד מישראל אומר בדבור אבינו מלכנו כמ\"ש כי אתה אבינו<sup data-n=\"325\">3</sup> אבינו אב הרחמן<sup data-n=\"326\">4</sup> וכה\"ג אע\"פ שאין זה בהרחב' טעם איך שהו' אבינו שהוא מקור כל תולדות הנשמות כו' מ\"מ אומ' אבינו כתינוק שקורא אבא מפני הכרתו אותו בדעתו כו' הרי זה ידיעה בקטנות על כל פנים שהוא כמו ידיעת השור קונהו שזנו ומפרנסו כך ישראל ידע ומכיר לאביהם שבשמים",[["323","1","<b>שאין התינוק. . אבא ואימא</b>: נסמן לעיל ח, ב. ראה גם סה\"מ תקס\"ט ע' ס."],["324","2","<b>כידע שור קונהו</b>: ישעי' א, ג."],["325","3","<b>כי אתה אבינו</b>: ישעי' סג, טז."],["326","4","<b>אבינו אב הרחמן</b>: ברכת ק\"ש שחרית."]]],[2800530031,"שזנם ומפרנסם ואהבתו עצמי' כו' ונמשכים אחריו לבדו ולא לזולתו כלל כידוע וד\"ל וזהו זכרתי לך חסד נעורייך<sup data-n=\"327\">5</sup> כו' לכתך אחרי כו' כתינוק שהולך ונמשך אחר אביו בלא טעם ודעת בהשגה אבל נכלל בזה כל הרחבת הדעת שישיג את מהות אביו כשיגדיל בשנים ואין כל חדש בזה כלל וכך ביצ\"מ כתיב מתבוססת בדמיך<sup data-n=\"328\">6</sup> כו' כמ\"ש ממצרים קראת לבני<sup data-n=\"329\">7</sup> וכמו נער קטן בלכתו אחר אביו ומבקש לחם ומים אבא האכילני לחם כו' וכה\"ג היה הילוכם במדבר מ' שנה וזהו חסד נעורייך שהיה ביצ\"מ שהוא האמונה שהיא למעלה מן הטעם כנ\"ל בפי' וארשתיך לי באמונה כו' וא\"כ הרי בחי' קטנות דאבא שבלא טעם שהוא בידיעה שיודע לקרות אבא כנ\"ל קרוב לענין האמונה שלמעלה מן הדעת לגמרי ואיך ישתווה למעלה מן הדעת עם הדעת הגם שהוא בבחי' הקטנות עכ\"פ מ\"מ בשם דעת יקרא כמ\"ש יודע לקרות כו' אך הענין הוא שיש בידיעה זו דקטנות שיודע לקרות לבד מלמעלה מן הדעת דוקא אלא שהושפל וירד בקטנות ידיעה זו שהיא ג\"כ בלא טעם ודעת מושג כלל והענין הוא דבאמת יש בידיעה זו שיודע לקרות אבא בהעלם כל אמיתות הענין איך שהוא אביו בעצם שלמעלה מן ההשגה בדעת שמשיגו בגידולו ויובן זה עד\"מ הידוע כאשר ישנה לתלמידו דרך קצרה שכולל בדברים קצרים הללו כל עומק השכל והסברא והפלפול הארוך שיש לדבר בזה שעה ושתים ולא יכילנו שכל הגדול בחכמה והכל מלובש בתוך הדברים הקצרים שמשנה לתלמידו או מלמד הלכה אחת לתינוק קטן שהתינוק משכיל רק פסק ההלכה דשנים אוחזין וכה\"ג וכל מה שיש במשנה זו טעמים וסברות ופלפולים שונים בגמרא שמבאר טעמי הלכה זו הכל יש בכללות דברי ההלכה שמשכיל גם התינוק או תלמידו הקטן והוא לפי שהרב צמצם והעלים והלביש כל דבר החכמה העמוקה ברוחב ההשכלה באותה ההלכה בדברים קצרים הללו שאם היה הרב משפיע ומגלה כל הפלפול העמוק שיש בזה לא היה משיגו שום חכם אך כאשר מעלימו ומלבישו בדברים קצרים כללים מספיקים להכיל הכל עד שאין כל חדש בפלפול הגמרא שהכל נמצא בדברי המשנה למי שבא על עומק הפלפול ונמצא התינוק אינו יודע כלל בהשגת שכלו כל מה שיש בהלכה זו רק הדברים כפשוטן הוא אומר אמנם הרי נתפס ומלובש בדברים אלה כל העומק חכמה שבפלפול כמו שהמים נתפשים בכלי ולוקח הכלי שנלקחו המים ממילא רק שנק' לקיחה ע\"י ד\"א שתופס המים ע\"י הכלי כך נתפס כל העמקי חכמה בתוך לבוש וכלי מצומצם שהן הדברים קצרים הללו שבהלכה רק שהוא בהעלם ולא בגלוי שהרי איננו משיג רק לצמצום הדבר המושג מן דברי ההלכה בלבד ואם היה מדבר עומק החכמה בלי לבוש מצומצם הזה לא היה אדם משיג' לגודל עומקו (ואין זה כהתלבשות השכל וחכמה במשלים וחידות וכה\"ג שהמשל מסתיר לגמרי שהרי המשל הוא ענין זר לגמרי שלא בדברי החכמה כלל אבל ההלכה מדברת בענין החכמה רק שמדבר בקצרה שהדין כך וכך בלא ביאור וטעם",[["327","5","<b>זכרתי לך חסד נעורייך</b>: ירמי' ב, ב."],["328","6","<b>מתבוססת בדמיך</b>: יחזקאל טז, ו."],["329","7","<b>ממצרים קראתי לבני</b>: הושע יא, א [ושם: וממצרים]."]]],[2800530032,"כלל ונק' דרך קצרה עכ\"פ וד\"ל) ולפ\"ז לכאורה בחי' הלבשה זו שמלובש השכל העמוק בהעלם כשבא לידי גלוי כשעומד על טעם ההלכה בפלפול וסברות עמוקות זהו שלימותו של הדבר חכמה שבא לבחי' גדלות המוחין וכקטן שנתגדל כו' כך הלבשה זו בדברים קצרים נק' קטנות המוחין וכשיצא לגלוי באורך ורוחב בהשגה בטוב טעם נק' גדלות המוחין ובאמת יש יתרון מעלה בקטנות הלבשה זו יותר מגדלות ההשגה שאח\"כ והטעם הוא לפי שיש בחכמה עצמה ב' מדריגות הא' מהו\"ע שלה כמו שהיא בתמצית אמיתתה והב' בחי' התפשטותה בהגלות נגלית אורה בטוב טעם ההשכלה בסברות ופלפולים שונים וכידוע בענין והחכמה מאין<sup data-n=\"330\">1</sup> כו' שבחי' עצמות החכמה היינו כמו שהיא בבחי' אין טרם שבאה לכלל יש בטוב טעם ההשכלה כו' וזהו פי' כח מה דחכמה ל' מהות ול' מה פשפשת<sup data-n=\"331\">2</sup> כו' דשניהם א' שהוא בחי' אין דחכמה כמו שהיא במקורה כו' והרי במה ששונה בדרך קצרה לתינוק וכה\"ג מפני שאין בזה גלוי אור שכל וטעם והסבר סברות כלל רק עצם תמצית הדבר כמו שהוא לבד כמו משנה דשנים אוחזין<sup data-n=\"332\">3</sup> כו' יחלוקו וכמו סוכה למעלה מכ' פסולה<sup data-n=\"333\">4</sup> שזהו עצם הענין ה\"ז עולה בעצם תמצית החכמה של הלכה זו כמו שהיא בבחי' אין טרם שבאה לכלל התפשטות אור בפלפול סברות עמוקות שאינו רק גלוי ההעלם העצמי שבה שהחכמה מאין תמצא בבחי' יש כנ\"ל ונמצא בהלבשה והעלם זה הגנוז בדברים הקצרים יש ממהו\"ע החכמה שלמעלה מעומק השכל שיש בפלפול הארוך שהרי לא יוכל לגלות בפלפול וסברות כמו שהיא בעצם ותמצית אמיתת' ממש וד\"ל וע\"פ משל זה יובן שיש מעל' יתיר' בבחי' קטנו' דאב' יות' מבחי' גדלו' דאב' והיינו ענין מצה שנק' מיכל' דמהימנותא שהאמונה הרי היא במהו\"ע א\"ס ב\"ה דוקא והוא בבחי' כח מ\"ה בעצמות הנפש ה\"ז ממש ענין קטנות דאבא כתינוק שיודע לקרות אבא לבד שיש בידיעה זו שבקטנות כל אמיתת העצמות כמו שהוא דהיינו כמו שהוא משיג בעצם ולא כמו שמושג גם בגדלות השכל וטוב טעם כמו במ\"ת שהשיגו וראו בגדלות השכל בתכלית עדיין אין זה מגיע לאמיתת עצמותו רק דוקא בקריאה שקורא אבא אע\"פ שאינו יודע בהשגת השכל כלל דאדרבה היא הנותנת משום שמלובש בזה מאמיתת הענין כמו שהוא בעצם שלא יוכל לבא לגלוי בראית השגת שכל גם בגדלות היותר עליון וז\"ש זכרתי לך חסד נעורייך דוקא שהוא בחי' המצה שנק' קטנות דמוחין דאבא ששרשה למעלה מן הטעם דגדלות אבא שבמ\"ת וד\"ל:\n(ו) <b>ולהבין</b> זה בתוס' ביאור. הנה יש לדקדק תחלה בגוף ענין המאמר דאין התינוק יודע לקרות אבא עד שיטעום טעם דגן דלכאורה משמע פשט המאמר להיפך מכל הנ\"ל שהרי אמר עד שיטעום טעם דגן דוקא וטעם דגן הוא לחם חמץ דוקא שיש בו טעם נרגש לחיך הטועם ולא בלחם מצה דלא מליח שאין בה טעם כלל וא\"כ איך יהיה הדוגמא מזה לענין מצה שנק' לחם עני שהוא בחי' קטנות דאבא כמשל התינוק שיודע לקרות שמשמעו להיפך שיש בו טעם כו' אך הנה יש להקדים בענין מ\"ש",[["330","1","<b>והחכמה מאין</b>: איוב כח, יב. ראה גם לקמן טז, א."],["331","2","<b>מה פשפשת</b>: זהר בהקדמה א, ב."],["332","3","<b>משנה דשנים אוחזין</b>: ריש ב\"מ."],["333","4","<b>סוכה למעלה מכ' פסולה</b>: ראה סוכה בתחלתה."]]],[2800530033,"ורעה אמונה<sup data-n=\"334\">5</sup> דמשמע שהאמונה יש לה רועה שזן ומפרנס אותה ומתגדלת עי\"ז מעט מעט וזהו פלא לכאורה דאיך שייך לשון פרנסה באמונה הלא מבואר למעלה שהאמונה טבעית היא בנפשות ישראל ירושה מאבותיהם וא\"צ לגדלה ולפרנס אותה כלל ואיך אמר ורעה אמונה ועוד האיך המצה דוקא הוא הלחם שבו ניזון כח האמונה ומפרנס אותה כלחם פשוט שזן ומפרנס לחיי הגוף עד שנק' מפני זה בשם מיכלא דמהימנותא<sup data-n=\"335\">6</sup> שהוא המאכל שזן ומפרנס את האמונה שלזה גם משה היה צריך לזה לאכול מצה בליל א' לפרנס כח האמונה שלו כנ\"ל וזה אינו מובן ע\"ד הפשוט. והנה ידוע בפי' ולשון אמונה לשון נוק' שזהו להיותה בחי' מקבל כמ\"ש איהו אמת ואיהי אמונה<sup data-n=\"336\">7</sup> כאומן את היונק<sup data-n=\"337\">8</sup> ממש וכמו ויהי אומן את הדסה<sup data-n=\"338\">9</sup> כו' והענין הוא דאיהו אמת היינו כמו שהוא באמיתת אמיתתו נמשך ונקלט בנש\"י ע\"י מאכל המצה דוקא וזהו ורעה אמונה שזן ומפרנס לכנ\"י שנק' אמונה כאומן את היונק שמגדלו וזנו ומפרנסו כו' והנה תחלה יש להבין בגוף ענין המצה ומהו ההפרש בין מצה לחמץ דהנה שרש הלחם הוא בחכמה<sup data-n=\"339\">10</sup> דוקא וכידוע בענין ברכת המוציא לחם דלחם גי' מזלא<sup data-n=\"340\">11</sup> מזל ונוצר מקור החכמה דהיינו כח מה שבעצם כנ\"ל שלמעלה מן הדעת וההשג' והוא ההכרה במהו\"ע א\"ס דוקא דלמת\"ב כלל כנ\"ל ועכ\"ז בא לכלל דעת והכר' שהוא כמו התינוק שיודע לקרות אבא כנ\"ל כך יקראו כנ\"י אבינו ממש כמו שהוא במהו\"ע למעלה מבחי' אור ושפע דא\"ס באבי\"ע כו' וזה היה ע\"י אכילת מצה בלילה הא' כשטעמו טעם מצה אע\"פ שאין בה טעם נרגש עכ\"ז לחם נק' וטעם מצה לא בעינן שהרי בלע מצה יצא בלע מרור<sup data-n=\"341\">12</sup> לא יצא דבעינן טעם מרור כו' וד\"ל ודוקא בלחם מצה שהיא בלא שאור ומחמצת שאז לא יתוסף בה עביות וגסות יותר מכמו שהיא בעצם קמח ומים לבד קודם האפייה וכשהיא עיסה נילושה כך היא במהותה העצמי אחר האפיה בלתי תוס' נפוח והתפשטות כלל מכמו שהיתה תחלה משא\"כ ע\"י שאור ומחמצת תנפח העיסה ותתפשט ואח\"כ באפיה תעלה יותר ויהיה בה תוס' נראה לעין בריבוי הכמות הרבה בכפליים מכמו שהיתה קמח ומים לבד כו' וגם הנה אופן ההתפשטות בניפוח העיסה ע\"י שאור ומחמצת בלישה ואפי' הנה הוא בא בדרך התנשאות והגבהה למעלה מפני שעולה השאור שמחמיצה בדרך רתיחה לעשות הניפוח מעט מעט בעלי' בגובה ולכל צד כו' אבל בלא שאור הנה תשאר העיסה בלתי התפשטות כלל לכל צד רק תשאר בגולמה כמו שהיא בעצם מהותה בלי שינוי כלל וכלל והנה עוד זאת ההפרש בין מצה לחמץ שבמצה בלתי שאור לא יבא הטעם שבה לגלוי כלל כי נשאר בהעלם שהרי אין במצה שום טעם מורגש כלל וידוע דכל עיקר המעלה שיש בלחם ששרשו בחכמה אינו רק בחי' ומדריגה המעולה שבו שהוא בחי' הפנימית והרוחניות שבו והוא הטעם שטועם כשלועס בשיניו וע\"כ הכוסס את החיט' שאין בה טעם לחם בלתי אפי' מברך בפה\"א<sup data-n=\"342\">13</sup> שאינו נק' לחם רק כשהו' אפוי שמתגלה בו טעמו ואם הוא בלא שאור ומחמצת גם באפי' בלתי נגלה",[["334","5","<b>ורעה אמונה</b>: תהלים לז, ג. ראה גם מאמרי אדה\"א שמות ח\"ב ע' תריט ואילך (ובהנסמן בריש המאמר שם)."],["335","6","<b>המצה. . מיכלא דמהימנותא</b>: נסמן לעיל ח, ב."],["336","7","<b>איהו אמת ואיהי אמונה</b>: נסמן לעיל ז, א."],["337","8","<b>כאומן את היונק</b>: ע\"פ בהעלותך יא, יב."],["338","9","<b>ויהי אומן את הדסה</b>: אסתר ב, ז."],["339","10","<b>שרש הלחם הוא בחכמה</b>: נסמן לעיל ח, ב."],["340","11","<b>דלחם גי' מזלא</b>: נסמן לעיל ט, א."],["341","12","<b>בלע מצה. . מרור</b>: פסחים קטו, ב."],["342","13","<b>הכוסס את החיט'. . בפה\"א</b>: ברכות לז, א."]]],[2800530034,"בו טעמו כלל וכלל רק הוא בהעלם גדול ולא נגלה בו רק מהות הלחם כמו שהוא בגולמתו שהוא הקמח כשנאפה ונעשה עיסת לחם והוא בחי' הקטנות שבו לבד דהיינו הגם שאינו נק' חטה כי יש בו תואר לחם מאכל הזן ומפרנס כלח' ממש אבל כל עיקר חיותו הפנימי שעל הלחם יחי' האדם שהוא הטעם נשאר בו בהעלם גדול ואין בו בגלוי רק מהותו כמו שהוא בבחי' גולם לבד ועכ\"ז לענין ברכה מברך ברכת המוציא לחם וברהמ\"ז כי לחם גמור הוא לכל דבר רק שאין בו טעם נרגש ונק' לחם מצה דלא מליח<sup data-n=\"343\">1</sup> ואין בו טעם כלל ועיקר הענין הוא דע\"י השאור להיות שיש בו כח חזק וחריף הוא פועל בחום רתיחתו להוציא ולעורר כח הטעם שבלחם בלישה ואפי' היטב מן כח ההעלם לגלוי גמור וכמו כל דבר חריף כתבלין ומלח דלטעמא עבידי ובפרט שאור ומחמצת שמחמיץ את העיסה הוא שנותן כח גדול לנפח העיסה ברתיחה בהגבהה שזהו עיקר כח המוציא כל טעמה בכי טוב וזהו כל עיקר ענין השאור כידוע אבל בלא שאור אין כח בלחם גם ע\"י האפי' לעורר כח הטעם שבה שיבא לגלוי במורגש ונשאר בהעלם ועכ\"ז לחם יקרא ואמנם לחם זה הוא נק' גולם הלחם כמו שהוא בלא התפשטו' כלל לא בכמותו ולא בטעם וד\"ל והנמשל מזה יובן בשרש הלחם שהוא בחכמה כנ\"ל דהנה ידוע שיש בחכמה ב' מדריגות הא' בחי' מהותה העצמי כמו שהיא והוא בטרם ההתפשטות שלה להשכיל כל שכל בטוב טעם ודעת ונק' גולם כמו חומר ההיולי והפשוט כו' ונק' כח המשכיל כל שכל שהוא אינו בכלל התחכמות שכל עדיין רק שממנו כח התפשטות ההתחכמות לכל דבר חכמה ועצה בכל דבר מה כו' ובחי' כח המשכיל הזה הוא בהעלם גדול מאד כידוע וסימן הראשון לתחלת גלוי שלו מן ההעלם הוא דוקא בדבור בפה שכאשר התינוק מתחיל לדבר זהו הוראה שכח המשכיל ההיולי שלמעלה מכלי המוח בא לגלוי שיהיה בכח שכלו להבין ולהשכיל על כל דבר מה כפי ערכו וקודם שיוכל לדבר עדיין כח המשכיל בהעלם לגמרי שהרי הדבור זהו בחי' סיום השפע מכח התחלה ומאחר שיוכל לסיים השפעות מחשבת השכל שבכלי המוח בדבור מזה מוכרח לומר שכח התחלה שבכח המשכיל התחיל לבא מן ההעלם שלו קצת כי נעוץ התחלה בסוף והסוף בתחלה והדבור הוא סוף ירידת והשפלת המח' הסתומה שבהעלם מהות כח השכל העצמי וז\"ש לנפש חי' לרוח ממללא<sup data-n=\"344\">2</sup> שנק' נפש המדברת שהוא עיקר בחי' מדבר וכל שאין לו עדיין הדבור הגם שיש לו מחשבה בהבחנה גמורה להכיר הטוב והרע ויבחור בטוב כזהב וכסף ויברח וירחיק הרע כדבר המזיק וכן במאכלים יבחר ויכיר בטוב וישנא וימאס במאכלים רעים וכ\"ש שהוא מכיר אביו ואמו בטוב ולא יומשך אחר זולתם כלל אך שאינו יכול לקרותם בדבור בפה לומר אבא כו' הרי עדיין לא בא העלם כח השכל שלו לגלוי ולזה רמזו באמרם קטן אין לו מחשבה<sup data-n=\"345\">3</sup> דגם שיש לו מחשבה אם לא תוכל לבא בדבור אינה מחשבה של דעת כלל אע\"פ שמבין ומכיר במחשבתו הכל (ולפ\"ע זה גם כשידבר לפי קוטן שניו יקטן מהות המחשבה שלא תשלם",[["343","1","<b>מצה דלא מלוח</b>: ראה שו\"ע אדה\"ז הל' פסח סתנ\"ה, סכ\"ט."],["344","2","<b>לנפש חי' לרוח ממללא</b>: בראשית ב, ז ובתרגום אונקלוס שם."],["345","3","<b>קטן אין לו מחשבה</b>: ראה גם לקמן קלז, ב ובהנסמן במ\"מ לשם."]]],[2800530035,"לשלימות' עד שיבא כח מהות השכל לגלוי ביותר אז מחשבתו מחשבה של קיימא ולא כדמיון שוא). ועיקר הענין הוא לפי שהמחשבה כלולה מב' מדריגות א' מבחי' בינה שבנפש וגם מקצת מאור החכמה אבל אין שם ממהות החכמה כמו שהיא במקורה באין והעלם שנק' מהות כח השכל שזהו בתינוק גם קודם שידבר שמבין ומבחין במחשבתו הכל ממש כמו אחר שידבר אבל משידבר כבר נכנס בו ממהות ועצמות כח החכ'<sup data-n=\"346\">4</sup> שלפי ערכו ע\"כ יכול להביא בדבור אותה המחשבה עצמה לדבר ולקרות אבא אף ע\"פ שבהכרה מצד עצמה הכיר לאו\"א בכי טוב קודם שיכול לדבר אבל אין זו הכרה לשלימותה כ\"כ כי אין זה בא רק מגלוי אור המצומצם במוח הבינה שבמחשבה אבל בדבור כשיודע לקרות אבא זהו ההכרה עצמיות שמעצם ומהות כח השכל רק שירד והושפל בסוף גלוי הדבור משום דאבא יסד ברתא<sup data-n=\"347\">5</sup> בחי' אבא דוקא שהוא בחי' מהות דכח מ\"ה דחכמה שנק' נפש חי' כו' משם יורד להביא בדבור בצרופים שנעשים ממילא<sup data-n=\"348\">6</sup> מבלי שיצטרך לחשוב איך לדבר כמ\"ש במ\"א והיא הנותנת דמשום שיכול להוריד ולהשפיל בדבור דבר מה שעולה במחשבתו היינו משום דממקום גבוה יותר הוא בא והוא בחי' מהות דכח מ\"ה כו' משא\"כ ממדריגת בחי' מוח הבינה שלמטה מן מהות החכמה לא יוכל לירד למטה להשפיל השפע בדבור אלא נשאר במח' ולפי שאין למח' זו שרש עצמי ע\"כ לא נק' מח' בלא דבור (כאלם ששומע ואינו מדבר שיחשוב כשוטה<sup data-n=\"349\">7</sup> וחרש שמדבר ואינו שומע אינו גרוע כ\"כ<sup data-n=\"350\">8</sup> כי השמיעה בבינה והדבור בחכמה ובאמת א' מהם מועיל או שומע או מדבר שיש אלמים וחרשים מחוכמים ביותר) ונמצא מובן דהדבור גם בדבר שאינו חכמה כלל הוא בחי' סיום וסוף השפלת וירידת מהות כח השכל (שלמעלה מהתחכמות שכל במח' כנ\"ל):\n(ז) <b>וזהו</b> שאמ' שאין התינוק יודע לקרות בדבור או\"א עד שיטעום טעם דגן דוקא דהנה מבואר למעלה שיש בלחם ב' אופני' א' גולם הלחם גם כשנאפה עיסת הקמח ומים ולא נגלה בו טעם לחם והב' כאשר ע\"י השאו' ומחמצת נגלה בו הטעם כו' והנה הלחם שרשו בחכמ' כנ\"ל והיינו הטעם הפשוט שעל מאכל הלחם דוקא יחי' האדם וכתי' כי לא על הלחם<sup data-n=\"351\">9</sup> לבדו יחי' האדם כו' דאד' היינו בחי' כח מ\"ה דמהות כח החכמה שנק' נפש חיה רוח ממללא נפש המדברת כנ\"ל ועל הלחם יחיה האדם לפי ששרשו בחכמה במהו\"ע דחכמה ע\"כ יחיה את האדם שהרי מחזק ומחיה להכח השכל העצמי במהו\"ע שלה דוקא שזהו עיקר הנפש אדם כנ\"ל ואע\"פ שהלחם הוא קמח דגן גשמי ובחי' צומח דתבואת הארץ ואיך יחיה למהות נפש אדם בחי' מדבר הענין ידוע שזהו מ\"ש כי לא על הלחם לבדו מצד עצמו יחי' האדם אלא מצד מוצא פי ה' שבלחם ששרשו למעלה יותר גבוה ממאמר דנעשה אדם כמ\"ש במ\"א<sup data-n=\"352\">10</sup> אך מ\"ש יחי' האדם אין חיות זה תלוי בטעם לחם דוקא שהרי יחיה האדם גם ממאכל לחם מצה וכה\"ג שבלא טעם נרגש כלל כמו שיחיה מלחם חמץ בטעם מורגש אלא שבאכלו לחם חמץ הנה כחו של שאור",[["346","4","<b>החכ'</b>: תוקן ע\"פ דפו\"ר. ובמהדורת לעמבערג: החכם."],["347","5","<b>דאבא יסד ברתא</b>: נסמן להלן קי, ב."],["348","6","<b>בצרופים שנעשים ממילא</b>: ראה אגה\"ק ס\"ה. מאמרי אדה\"א ויקרא ח\"ב ע' תתקכב ואילך."],["349","7","<b>כאלם. . שיחשוב לשוטה</b>: ראה שו\"ע אדה\"ז הל' ברכות השחר סנ\"ה סי\"א. הלכות ברהמ\"ז סקצ\"ט ס\"י. סה\"מ תקס\"ה ח\"ב ע' תקצה. סה\"מ תרנ\"ט ע' לח וע' לט."],["350","8","<b>וחרש. . אינו גרוע כ\"כ</b>: ראה בהערה שלפנ\"ז."],["351","9","<b>כי לא על הלחם</b>: עקב ח, ג."],["352","10","<b>מוצא פי' ה'. . במ\"א</b>: ראה לקו\"ת להאריז\"ל עה\"פ. סה\"מ תקס\"ה ח\"ב ע' תרלח. ע' תשסד. ע' תתצד. תו\"א בשלח סה, ד. מאמרי אדה\"א דברים ח\"ב ע' תקעה. וש\"נ. הנחות תקע\"ז ע' קכא. וש\"נ."]]],[2800530036,"ומחמצת שממנו מתעורר טעם הלחם לצאת לגלוי מורגש בטעם ללועס שלועס הרוחניות והטעם שבו הרי מחיה לאדם ג\"כ בבחי' הטעם שבחכמה שהוא בחי' גלוי אור וחיות יותר בהתפשטות אורה במוחין דגדלות במוח הבינ' עד שידבר בהרחבה יותר כי טעימת טעם לחם מעורר לכח המשכיל הנעלם שיגלה בו טעמו שהו' טוב טעם ודעת שיור' למט' גם לסיים השפעתו בדבור ביות' שהוא בחי' עצם מהות דכח מ\"ה כשבא בהתפשטות למטה בתכלית וזהו שאין התינוק יודע לקרות בדבור אבא כנ\"ל עד שיטעום טעם דגן טעם לחם כלחם חמץ שיותר נגלה עצם מקורו הנעלם משא\"כ ע\"י מאכל לחם בלא טעם מורגש אע\"פ שגם על ידו יחי' האדם היינו רק במהות עצם החכמ' כמו שהיא בבחי' גולם שלא תתגלה אורה בטוב טעם עדיין וחיות זה בעצם דוקא ולא בהתפשטות כ\"כ ע\"כ עיקר הסימן ליציא' מן הקטנו' אל הגדלו' בקטן כשיודע לקרות בדיבור אבא היינו כשיטעום טעם לחם אבל לא בגולם הלחם שהטעם שהוא הרוחניות נשאר בו בהעלם ולא נגלה ממנו רק הגולם וחומר העצמי שלו כמו שהוא במהותו העצמי קמח בלי תוס' כלל כנ\"ל שהוא בחי' הקטנות שבו כמו החטה כמו שהיא בגולמה רק שיקרא לחם שמפרנס ויחי' את האדם וחייב לברך עליו המוציא לחם וברהמ\"ז כלחם גמור כנ\"ל אבל כל עיקר המעל' שבו שהוא הטעם הרוחני נשאר בהעלם ואין בו בגלוי רק מהותו כמו שהוא בבחי' גולם בלא התפשטו' כלל ושרשו במהות ועצם כח היולי דכח מ\"ה דחכמה שנק' גולם החכמה כנ\"ל ועכ\"ז ה\"ז סוף מהות ועצם החכמה עכ\"פ שיש בה יתרון מעלה על בחי' התפשטותה בטוב טעם (רק לענין קריאה בדבור אבא הוא עד שיטעום טעם דגן דוקא) וזהו שרש ענין מצה שהוא בבחי' קטנות דאבא להיות שאין בה טעם דחכמה כלל רק בחי' הגולמה כמו שהוא אבל שרשה למעלה מן הטעם דחכמ' וע\"כ נק' מיכלא דמהימנותא עד שזן ומפרנס כח האמונה שהיא למעלה מן הטעם דחכמה כנ\"ל וד\"ל:\n<b>והנה</b> ע\"פ כ\"ז יובן עיקר ההפרש בין חמץ למצה דלא ראי זה כו' שיש מעלה בלחם חמץ מצד הטע' שבו ששרשו בטעמי' שבחכמה ובנשמ' האלקי' היינו בחי' טוב טעם דדעת<sup data-n=\"353\">1</sup> האלקי כמו טעמו וראו כי טוב ה'<sup data-n=\"354\">2</sup> טעמו וראו דוק' דראי' השכל שבחכ' בכח מ\"ה שבה כמו שהיא בבחי' אין לא תשא' כגולם בהעל' לבד אלא יבא בה הטעם הרוחני שהו' עונג העצמי שבחכ' להתענג על ה' בעריבו' מתיקו' כו' ונק' נועם ה' כידוע (וזה היה במ\"ת בשבועות בשתי הלחם דכתי' חמץ תאפינה<sup data-n=\"355\">3</sup> חמץ דוקא כמשי\"ת<sup data-n=\"356\">4</sup> ) וטועמיה חיים זכו כעל טעם הלחם שיחי' האדם והן טנת\"א טעמי' בחכמה<sup data-n=\"357\">5</sup> כו' והדבור בתושבע\"פ שהן שתי הלחם כו' כידוע) ויש מעלה בלחם מצה במה שהיא בלא טעם דוקא שהיא במהו' העצמי דכח מ\"ה כמו שהיא טרם התפשטות' כו' כנ\"ל<sup data-n=\"358\">6</sup> וע\"כ נק' לחם עני כעני זה שלחמו הוא חיותו העצמי בלא התפשטות כלל וזהו ענין ורעה אמונה שנאמר זה במצה שעל ידי המצה נתחזק כח וחיות האמונה דוקא גם במשה רבינו וכה\"ג כנ\"ל ולזה נק' בשם מיכלא דמהימנותא כנ\"ל להיות שלחם מצה שאין בה טעם שרשה בעצם ומהות כח החכמ' כמו שהיא דוקא שלמעלה מהתפשטות אור כלל כדומם וחומר",[["353","1","<b>דדעת</b>: בדפו\"ר: ודעת."],["354","2","<b>טעמו וראו כי טוב ה'</b>: תהלים לד, ט."],["355","3","<b>חמץ תאפינה</b>: אמור כג, יז."],["356","4","<b>כמשי\"ת)</b>: אוצ\"ל: כמשי\"ת."],["357","5","<b>טעמי' בחכ'</b>: ראה ע\"ח (שער דרושי אבי\"ע) שמ\"ב פ\"א. מאמרי אדה\"א ויקרא ח\"ב ריש ע' תתלד. וש\"נ. דברים ח\"ד ע' א'תע בשם הע\"ח. וש\"נ."],["358","6","<b>כנ\"ל</b>: אולי כצ\"ל. כנדפס כ\"ל."]]],[2800530037,"גולמי כו' והיא הנותנת שיש בה מעלה יתירה להכיל ולקבל אור העצמות דלמת\"ב כלל שזהו הנק' אמונה ל' נוק' שמקבלת כל אמיתית העצמו' כמו שהוא דוקא כנ\"ל דאיהו אמת ואיהי אמונה כו' וע\"כ ע\"י אכילת מצה דוקא ניתוסף כח האמונה שבנפש שהיא במהו\"ע דוקא רק שבאה בהתלבשות בבחי' הקטנות מאד והוא בגולם הלחם דוקא שיחיה את האדם בעצם לבד כנ\"ל (וזהו בחי' כח מה העצמי שבכל נשמה מישראל שביכולתה למס\"נ<sup data-n=\"359\">7</sup> על קדה\"ש או בהתעוררות בתשובה שלימה עד שתצא נשמתו בבכי' כתשוב' דראב\"ד<sup data-n=\"360\">8</sup> וכה\"ג והיא שעמ' לאבותינו ולנו כנ\"ל בענין האמונ'):\n<b>אך</b> עדיין לא מתיישב הקושי' דלעיל במאמר זה דאין התינוק כו' שהוא להיפוך מן המצה שאין בה טעם ואיך יבא מזה דוגמא לענין ובחינת קטנות דאבא שבמצה כנ\"ל ואמנם הנה באמת הרי מבואר למעלה בענין ידיעה זאת שיודע לקרות אבא כו' שאינה ידיעה בטוב טעם ודעת גמור רק בחי' הכרה בעלמא והמשכת נפשו בעצם בלתי טעם רק שמלובש בזה בהעלם מן הטעם דגדלות המוחין כו' ולפ\"ז ודאי א\"א לפרש בטעימת טעם דגן שכוונתו בטעם לחם דוקא ולתלות בו סיבת ידיעה זו שיודע לקרות כו' דא\"כ היה לו דעת גמור בטוב טעם בקריאה זו מאחר דבטעמא תליא מילתא בטועם טעם לחם דוקא כו' אלא צריך לומר דאין הכונה בטעם לחם הנרגש בטעמו לחיך כלחם חמץ דוקא שהרי לא אמר טעם לחם אלא טעם דגן קאמר שהדגן הוא עצם התבואה קמח אע\"פ שאין בו שאור ומחמצת כלל מ\"מ לחם דגן נק' ועליו יחיה האדם כמו על לחם חמץ ממש והכונה אינו אלא כשיטעום בטעם דגן שהוא לחם תבואת הארץ ופסק מיניקתו חלב אמו אזי דוק' ידע לקרו' אבא כו' והו' שיש בקרי' זו בהעל' עכ\"פ כל בחי' מהו\"ע דכח מ\"ה דאדם בחי' מדבר ע\"כ יודע לקרות עכ\"פ אבא אע\"פ שאינו יודע זה בטוב טעם כלל ולקרות זה בדבור דוקא שהרי אנו רואים שהדבור יתחיל בתינוק מיד בפסיקתו מן החלב וגם בתוך ימי היניקה אם ירגיל במעט לחם יהיה איך שיהי' גם בלא טעם רק קמח תבואה ולא חלב אמו ונמצא עולה הכל לענין א' והוא מה שכל אחד מישראל יכול לקרות אבא בפה כמו אבינו כו' שזהו מגיע בעצם ומהות דכח מ\"ה הנ\"ל שיכול להכיל מהו\"ע דלמת\"ב כו' והוא שיכול להוריד בדבור לקרות אבא והוא סוף העצם והמהות דוקא (דלא כדלעיל וד\"ל):\n<b>ומעתה</b> יש להבין ענין הפרש השני שבין חמץ למצה שהשאור טבעו להגביה העיסה ולהוציא בה הטע' הנעלם כו' משא\"כ בלא שאור שאין בה הוספות ניפוח והתפשטו' כלל כנ\"ל באורך דהנה בטעם איסור חמץ בפסח ומצות מצה יש ב' דברים הא' מצד שצריכי' בני ישראל לאכול לחמם בפסח לחם עני די אכלו אבהתנא<sup data-n=\"361\">9</sup> כו' עוגות מצות כי לא הספיק להחמיץ כמ\"ש מצה זו שאנו<sup data-n=\"362\">10</sup> כו' שזהו דוקא שלא יהיה בה טעם כלל ולזה נאסר לחם חמץ לפי שיש בו טעם כו' והב' מצד עצם השאור והמחמצת שנאסר דוקא בפסח שנאמ' כל שאור<sup data-n=\"363\">11</sup> וכל מחמצ'<sup data-n=\"364\">12</sup> כו' ולזה נאסר כל לחם חמץ מפני השאור שבו וכן כל דבר חמץ ונצטווינו במצה לפי שאין בה השאור המחמיץ כלל וכלל כידוע והכל עולה לענין א' שהרי השאור הוא העושה טעם בלחם אבל נאסר מצד",[["359","7","<b>כח מה. . למס\"נ</b>: ראה לעיל י, א ובהנסמן לשם."],["360","8","<b>בבכי' כתשוב' דראב\"ד</b>: נסמן לעיל א, ב."],["361","9","<b>די אכלו אבהתנא</b>: נוסח ההגדה."],["362","10","<b>עוגות מצות. . מצה זו שאנו</b>: בא יב, לט. נוסח ההגדה."],["363","11","<b>כל שאור</b>: ראה בא יב, טו. יט. יג, ז. פ' ראה טז, ד. [הלשון כל שאור ? ויקרא ב, יא]."],["364","12","<b>וכל מחמצת</b>: בא יב, כ [ושם: כל]."]]],[2800530038,"עצמו דוקא שאם מפני שעושה טעם בלח' היה כל טעם מאכל אסור בפסח ואינו כן שהרי מצה עשירה שנילושה בשמן ודבש מותר<sup data-n=\"365\">1</sup> וכל תבלין ומלח דלטעמ' עבידי<sup data-n=\"366\">2</sup> וכן בתבשיל בכל מיני מטעמי' הכל מותר אך עיקר טעם האיסור בשאור הוא לפי שיש בו הגבהה והתפשטות והתנשאו' למעל' והוא להיותו מבחי' גבורו'<sup data-n=\"367\">3</sup> כרשפי אש שעול' למעל' כו' ע\"כ מרתיח את העיסה שתתפח בדרך העלאה כנ\"ל ובפסח צריך להיות מבחי' השפלות וההכנעה יתירה כדומם בלי התפשטות כלל וכלל רק בבחי' דומם וגולם שזהו במהות ועצם הדבר כמו שהוא לבד כנ\"ל וד\"ל וגם צ\"ל ההמשכ' בז' ימי הפסח מבחי' החסדים דאבא דוקא ולא מבחי' הגבורות כלל ע\"כ מב' טעמי' אלו נאסר השאור והמחמצת לגמרי עד שכל האוכל שאור<sup data-n=\"368\">4</sup> כו' ונכרתה הנפש ההיא מיום הראשון עד יום הז'<sup data-n=\"369\">5</sup> כו' וד\"ל:\n(ח) <b>ולהבין</b> זה הנה תחלה יש להבין בטעם איסור החמץ והשאור עד שכל האוכל כו' ומהו שאמ' מיום הא' עד יום הז' כו' דהנה שרש ישראל למעלה הוא בבחי' ישראל דלעילא שהו' בחי' ז\"א דאצי'<sup data-n=\"370\">6</sup> שכלול מז' מדות חג\"ת נהי\"מ והיינו מ\"ש מיום הא' עד יום הז' מבחי' חסד דז\"א שהוא יום א' דפסח עד בחי' המל' שהוא יום הזש\"פ<sup data-n=\"371\">7</sup> כידוע לפי שעיקר שרש הראשון דנש\"י בעלמ' דדכור' הוא מבחי' מדות דז\"א שנק' ישראל דלעיל' וכל מספ' בנ\"י לצבאות' על גולגלת' שרשם הוא בז' מדות דאצי' ובהיות שבחג הפס' מאיר למעלה רק מבחי' חסדים דאבא בז\"א והשאור והמחמצת שרשם הוא מבחי' הגבורות שיש אחיזה לגבורות קשות מהם (וע\"כ נאסר כל שאור ומחמצת בהקטרה ע\"ג המזבח כמ\"ש כל שאור ומחמצת לא תקטירו<sup data-n=\"372\">8</sup> וכל המנחות באות מצה דוקא חוץ מתודה שיש בה י' חלות חמץ<sup data-n=\"373\">10</sup> ושתי הלחם דשבועות וכמ\"ש במ\"א באריכות<sup data-n=\"374\">9</sup> וד\"ל) ע\"כ נאסר החמץ לישראל בימי הפסח עד שכל האוכל שאור נכרתה נפשו האלקי' משרשה הראשון ביומין עילאין דז\"א דאצילות מאיזה שרש שיהיה נשמתו הרי נכרת מכל הז' ימים מיום הא' עד יום הז' לפי שכלולים זע\"ז בתכלית וד\"ל:\n<b>וביאור</b> הענין מובן ע\"פ הנ\"ל במשל ודמיון דשאור ומחמצת למטה שהוא העושה ההגבהה והתנשאות והתפשטות יתירה כו' שיש בזה ב' ענינים א' שהגבה' זו היינו בחי' הגסות והיש שהוא היפך האין ומ\"ה העליון שא\"א שישכון בבחי' יש וגסות מעצמות ומהות אא\"ס שהוא בחי' אין האמיתי וכמ\"ש מרום וקדוש אשכון<sup data-n=\"375\">11</sup> ואת דכא ושפל רוח דעמ\"ר אינו נמשך אלא בעמ\"ת<sup data-n=\"376\">12</sup> כמ\"ש כי רם ה'<sup data-n=\"377\">13</sup> ושפל יראה כנ\"ל ובפסח נגל' עליהם מבחי' מהו\"ע דלמת\"ב כלל ואפי' הגסות שיש בדרכי ה' כמו ויגבה לבו<sup data-n=\"378\">14</sup> בדרכי ה' שזה מבחי' היש דקדושה ע\"י שהוא עולה בהתפעלות רשפי אש התלהבות הלב כמו בעבודה שבלב בתפל' ותו\"מ בחשק עד שמתנשא לבו בדרכי ה' ממש הרי מ\"מ זהו מבחי' התנשאות והגבה' ביש ודבר מה ובפסח נמשך שרש החיות בנש\"י תוך כל או\"א מחסדים הראשונים שבמהו\"ע כמו ישראל עלה במחשבה<sup data-n=\"379\">15</sup> תחלה בפנימי' ועצמות ממש כמ\"ש כי אתה אבינו<sup data-n=\"380\">16</sup> בעצמות דמוח האב כו' שאינו שורה ונמשך רק במקום שפלות והכנע' יתיר' עד שהוא רק כמו בחי' דומם וגולם",[["365","1","<b>מצה עשירה. . מותר</b>: ראה פסחים לו, א."],["366","2","<b>תבלין ומלח דלטעמ' עבידי</b>: עד\"ז הובא גם במאמרי אדה\"א ויקרא ח\"א ע' כז. במדבר ח\"ב ע' שפז. וראה חולין ו, א."],["367","3","<b>בשאור. . גבורו'</b>: ערכי הכינויים לבעל סדה\"ד מערכת שאור. המשך תער\"ב ח\"ג ע' א'שלט."],["368","4","<b>שכל האוכל שאור</b>: ראה רש\"י בא יב, יט ד\"ה כי."],["369","5","<b>ונכרתה. . הז'</b>: בא יב, טו [בדילוג]."],["370","6","<b>ישראל. . ז\"א דאצי'</b>: ראה לקמן קלג, א ובהנסמן במ\"מ שם."],["371","7","<b>חסד. . א'. . המל'. . הזש\"פ</b>: ראה גם תו\"ח לך פח, ד ובהערה 19."],["372","8","<b>כל שאור ומחמצת לא תקטירו</b>: ויקרא ב, יא [ושם: כל שאר וכל דבש ? ראה סידור שחרית מה, ג בשינויי נוסחאות [ושם: וכל מחמצת ? וכ\"ה באוה\"ת תהלים ע' תתקפה]. פיה\"מ צו, ד]."],["373","10","<b>מתודה. . חמץ</b>: מנחות עו, סע\"ב ואילך (במשנה)."],["374","9","<b>וכל המנחות. . במ\"א באריכות</b>: מנחות נב, ב (במשנה). ראה סידור שחרית מה, א ואילך. פיה\"מ (פקמ\"ד-קמז) צה, רע\"ג ואילך. אוה\"ת תהלים כרך ב ע' תתקפג ואילך. מאמרי אדה\"ז מארז\"ל ע' שנח ואילך. אוה\"ת שם ע' תתקעד ואילך."],["375","11","<b>מרום וקדוש אשכון</b>: ישעי' נז, טו."],["376","12","<b>דעמ\"ר. . בעמ\"ת</b>: ראה לעיל י, א ובהנסמן במ\"מ לשם."],["377","13","<b>כי רם ה'</b>: תהלים קלח, ו."],["378","14","<b>ויגבה לבו</b>: דהי\"ב יז, ו. ראה גם שע\"ת סד, ג ובהנסמן במ\"מ לשם."],["379","15","<b>ישראל עלה במחשבה</b>: נסמן לקמן לז, ב."],["380","16","<b>כי אתה אבינו</b>: ישעי' סג, טז."]]],[2800530039,"בעלמא והוא במצה זו שאנו אוכלים ע\"ש מ\"ה ע\"ש שלא הספיק כו' בחי' גולמא בלי התפשטות והגבה' כלל רק כמו שהוא בעצם כנ\"ל אז נגלה עליהם במהו\"ע כו' ויכולים לקבל מז' ימים העליונים מקור שפע חיותם האלקי על כל השנה להיות תוס' כח חזק באמונתם שז\"ש ורעה אמונה<sup data-n=\"381\">17</sup> ע\"י המצה דוקא כנ\"ל והיינו רק מבחי' החסדים העליונים שבמהו\"ע ממש שנמשכו לישראל דלעילא בז' הימים וז\"ש מצות יאכל<sup data-n=\"382\">18</sup> את ז' הימים כו' (וכמשי\"ת) ומשם נמשך לכל ענף נשמ' פרטית בכל דור בז' ימי הפסח אבל כל נפש מישראל האוכל שאור וחמץ גם בהיות כדוגמת זה בעבודת הקדש שהוא בהתנשאות הלב מצד בינה לבא<sup data-n=\"383\">19</sup> אע\"פ שיש בו טעם ועונג כטעם לחם חמץ כו' שמגביה הלב וכמו ולחם לבב אנוש יסעד<sup data-n=\"384\">20</sup> כו' מ\"מ ה\"ז בבחי' יש ודבר מה שהוא בחי' המנגד ממש לאור שפע החסדים העליונים דמ\"ה דחכמ' כמו שהוא במהו\"ע ממש עד שהכרת תכרת נפש זו האוכלת חמץ משרש' ביומין עילאין דז\"א דאצי' שאינו מקבל שרש חיותו ממקורו בבחי' ישראל דלעילא להיותו בבחי' גבורות שהוא ההסתלקות למעלה בבחי' התנשאות ליש ודבר מה מורגש בטעם אלא דוקא יאכלו בנ\"י מצות שהוא אפיי' העיס' קמח ומים כמו שהיא בגולמ' בלא טעם לחם ובלא התפשטות כלל שהוא תכלית השפלות והקטנות ונק' לחמא עניא כו' ונעש' ונמשך מזה מקור חיים העליונים לנש\"י היפך השאור וחמץ שבאכילתו יוכרת משרשו גם מכל מדריג' פרטית שבז' ימים אלה מיום הא' עד יום הז' לפי שכלולי' זע\"ז בחי' אור החסד כלול מכולם עד המל' וכן כל אחד כלול מכולם עד המל' וע\"כ גם כנ\"י ערבים זב\"ז<sup data-n=\"385\">21</sup> כו' בציור קומת אדם<sup data-n=\"386\">22</sup> אחד ממש כידוע וד\"ל. אך הנ' באמת יש להבין בענין טעם זה דאיסור חמץ ושאור מצד ההגבה' וגסות וכן מצד הטעם לחם משא\"כ במצ' שאין בה טעם ואין בה תוס' והגבה' כו' שא\"כ הי' ראוי שיצו' על העיקר והוא בגסות הלב והתנשאות ביש ודבר גם במילי דשמיא וכ\"ש במילי דעלמא והיינו שיהי' דרכי העבוד' שבלב ומוח ותו\"מ בפסח הכל בשפלות והכנע' כאיש עני שיחי' בלחמו כו' לבלי ירא' לבחי' יש ודבר כלל ולא תהי' דרך העבודה בלב בהתנשאות דרשפי אש ושמח' בטוב טעם ודעת כו' שלא יגב' לבו בדרכי ה' וכ\"ש בעניני עצמו וזה הי' ראוי להיות עיקר האזהר' בל ירא' התנשאות וגסות בלב וכן הכעס שהוא בוער כאש אלא שפלות וענו' יתיר' כו' וזה לא מצינו שיהי' הפרש כלל בזה בין יו\"ט של פסח לשאר המועדים דכתיב ושמחת בחגיך<sup data-n=\"387\">23</sup> וכך מצוה ביו\"ט של פסח בשמח' דוקא ושמח' זאת באה ודאי ברשפי אש התשוק' בבחי' התנשאות והגבהת הלב קצת ומצו' היא ולא איסור בפסח כמו בשבועות וסכות שהרי אומר הלל<sup data-n=\"388\">24</sup> דכתיב אם הבנים שמח'<sup data-n=\"389\">25</sup> כו' ואפי' עני שבישראל חייב לשתות יין ארבע כוסות<sup data-n=\"390\">26</sup> וכה\"ג ודאי צריך לעבוד את ה' בשמח' ואין הצווי רק על גשמיות האכיל' שלא יאכל חמץ ולא ירא' בכל גבולו<sup data-n=\"391\">27</sup> והמצו' לאכול מצה ומה יש תועלת בביעור החמץ גשמי לענין הרוחני דאש גבו' דשאור וחמץ למעל' עד שהאוכל חמץ וכו' מאין יש חבור זה לגשמיות עם הרוחניות וכן באכילת מצה גשמיות יחזק אור",[["381","17","<b>ורעה אמונה</b>: תהלים לז, ג."],["382","18","<b>מצות יאכל</b>: בא יג, ז."],["383","19","<b>בינה לבא</b>: ת\"ז בהקדמה (יז, א)."],["384","20","<b>ולחם לבב אנוש יסעד</b>: תהלים קד, טו."],["385","21","<b>כנ\"י ערבים זב\"ז</b>: ראה תו\"כ בחוקותי כו, לז. שבועות לט, סע\"א. סה\"מ תרמ\"ד ע' רסד."],["386","22","<b>כנ\"י. . קומת אדם</b>: ראה מאמרי אדה\"א ויקרא ח\"ב ע' תערה. וש\"נ. הנחות תקע\"ז ע' קנה. וש\"נ."],["387","23","<b>ושמחת בחגיך</b>: פ' ראה טז, יד."],["388","24","<b>בפסח. . הלל</b>: בתפלה ובהגדה ? ראה סידור אדה\"ז סדר הלל וסדר הגדה."],["389","25","<b>אם הבנים שמח'</b>: תהלים קיג, ט."],["390","26","<b>עני. . ארבע כוסות</b>: ראה פסחים צט, ב (במשנה)."],["391","27","<b>ולא ירא' בכל גבולו</b>: בא יג, ז."]]],[2800530040,"שרש החיות דנשמ' בחסד עליון דחכמ' כו' ואם יש חבור בהם א\"כ הי' לו לצוות על העיקר שהוא הרוחניות דבחי' גבורות וחסדים והוא במניעת מדת ההתנשאו' ובהשתדלות במדת השפלות להשפיל עצמו שנכלל בזה ענין הגשמי דחמץ ומצ' כי הרוחניות עיקר ולמה עשה מהטפל עיקר ואם כל המצות כולן נתנו בבחי' הגשמיות במעש' בפו\"מ דוקא כתפילין וציצית וסוכה וכה\"ג הרי לא נתבאר טעמם אבל בפסח ומצ' עיקר הטעם הרוחני שבהם מובן ומבואר כנ\"ל אך הנה באמת זהו יתרון מעלת הגשמיות על הרוחניות שהרי אע\"פ שכל עיקר טעם הרוחני בחמץ ומצ' הוא הגסות או השפלות ברוחניות הנפש אמנם ודאי אין עונשין כרת בב\"ד של מעל' על הרוחניות אם תגב' הנה\"א בהתנשאות הלב בעבודת ה' וגם אם יגב' לבו בגסות הרוח במילי דעלמא בימי הפסח לא תכרת הנפש בשרש' בחיים העליונים דז' ימים העליונים כלל רק דוקא כאשר תאכל כל חמץ גשמי אז תכרת הנפש משרשה העליון למעל' ובמצות אכילת מצה דוקא בגשמיות תדבק נפשו במקור' העצמי להוסיף לה חיים העליונים ביותר ולא ע\"י שפלות הנפש ברוחניות כלל כי גם אם ישפיל עצמו בתכלית אם לא יאכל מצה הגשמית לא יקבל כח וחיות הנשמ' משרש' כו' וגם בעניני העבוד' אין מהחיוב כלל שתעבוד הנפש בימי הפסח בשפלות דוקא יותר משאר הימים אלא גם אם תפלתו ועבודתו בתו\"מ בשמח' והגבה' הלב אם יאכל מצה יחי' את נשמתו ממקור עצמות החיים כנ\"ל ואמנם גם זה אמת שבודאי יש הפרש גדול בכללות ענין העבוד' בנש\"י בין ימי הפסח לשאר הזמנים והמועדים בהיות ידוע ומבואר למעל' שכל נקודת ענין החג הזה דפסח היינו מה שהי' בו רק ענין ההתחל' של נקודת יהדותם שהיא האמונ' שבה יצאו מאפיל' לאור גדול מן ההיפוך להיפוך ונק' חסד נעורייך כנ\"ל (וכמ\"ש באריכות בד\"ח בענין גפן ממצרים תסיע<sup data-n=\"392\">1</sup> כו') והוא מה שיצאו מנש\"ט דמצרים<sup data-n=\"393\">2</sup> וחפצו להדבק באלקים חיים בכלל ולא בפרט שזהו כמו הבע\"ת או הגר שמתגייר שנק' התחלת יהדותו שהיא בחי' נקוד' העצמית שממנ' מסתעף כל מה שיקבלו אח\"כ עול תו\"מ ואוי\"ר באה\"ר בתענוגי' כל הימים דור אחר דור כו' וזהו תוקף האמונ' שהאמינו בה' ובמש' עבדו<sup data-n=\"394\">3</sup> באמונ' פשוט' בתכלית באלקים חיים ומלך עולם<sup data-n=\"395\">4</sup> איך שהוא מקורא דכולא<sup data-n=\"396\">5</sup> וכולא קמי'<sup data-n=\"397\">6</sup> כו' ואין עוד מלבדו<sup data-n=\"398\">7</sup> בלי שום טעם ודעת בהשגת שכל כלל רק למעל' לגמרי מן הטעם ודעת ומתוך תוקף אמונ' זאת הלכו כולם אחרי ה' כאיש א' במס\"נ ממש לקבל עליהם עומ\"ש שלימ' בכל אשר יצו' ה' ויגזור אומר במצותיו כו' וזה הי' בלא התפעלות רשפי אש מתוך התענוג והשמח' בהשג' אלקית כלל כי לא השיגו מאומ' כי לא שמעו מקוצר רוחם<sup data-n=\"399\">8</sup> האלקי כו' רק בדרך שפלות עצומ' היינו רק שלא רצו להיות בפירוד מאלקי' חיים להיות מושקעים באפילת נש\"ט ורצו לידבק באור גדול אך לא ע\"י השג' בדעת וטעם כי היו שפלי' בעצמם בתכלית השפלות מכל צד שמררו את חייהם<sup data-n=\"400\">9</sup> בעבוד' קש' בגשמיות וברוחניות נשמתם בשרש חייהם דכנ\"י כו' ולא הי' בהם כח להיות מעובדי ה' ע\"י השג' וטעם אלא כמו מי שהוא",[["392","1","<b>בד\"ח. . תסיע</b>: צו, א ואילך. תהלים פ, ט."],["393","2","<b>שיצאו מנש\"ט דמצרים</b>: נסמן לעיל יג, ב."],["394","3","<b>שהאמינו בה' ובמש' עבדו</b>: בשלח יד, לא."],["395","4","<b>באלקים חיים ומלך עולם</b>: ברכת יוצר."],["396","5","<b>שהוא מקורא דכולא</b>: זהר בראשית לג, א."],["397","6","<b>וכולא קמי'</b>: ראה זהר בהקדמה יא, ב. מאמרי אדה\"א דברים ח\"ב ע' תרנג."],["398","7","<b>ואין עוד מלבדו</b>: ואתחנן ד, לה."],["399","8","<b>לא שמעו מקוצר רוחם</b>: וארא ו, ט."],["400","9","<b>שמררו את חייהם</b>: שמות א, יד."]]],[2800530041,"שפל בעצם בתכלית שלא ימלא לבו לגשת אל העבוד' האלקית באהבת רשפי אש ע\"י טוב טעם ודעת האלקי כו' באמרו לנפשו השפלה מי אנכי שאבא בגדלות להשיג בדעת שלי המוגבל לעצמות אא\"ס שלמעלה מכל ההשתלשלות ולית מת\"ב כלל ומי אנכי המתועב בחומריות וגסות הגוף כ\"כ לעמוד לשרת בעבודה שבלב ברשפי אש התלהבות שמצד פחיתות ערכו בעצמו לא יגבה לבו לילך בדרכי ה' בהגבהה ומעלה כ\"א בדרך שפלות והכנעה עצומה והיינו שיאמר לנפשו השפלה בעצם שאין עבודתו מגיע רק להיות כעבד פשוט לקבל עול בביטול גדול להיות מוכן ועומד לקיים כל אשר יצוה ה' ולילך במצותיו אחרי ה' שלא לסור ימין ושמאל כל היום להיות בטל וטפל למצותיו לבד בלא טעם והשגה כלל רק באמונה פשוטה להאמין בו בלא טעם כלל ובלא התלהבות אהבה ברשפי אש התענוג כלל וכלל שזהו מדריגת השפל באמת לאמיתו שאין זה רק בחי' ההתחלה שיתחיל לילך בדרכי ה' לבחור בחיים וטוב ולמאוס ברע ע\"י קבלת עול מלכות שמים בעול פשוט ע\"י שפלות עצמו ביותר שאינו תופס מקום כלל בעצמו לומר ללבו לעבוד בטעם ודעת ובשמחה והתפעלות אהבה בתענוגים וכה\"ג רק להיות כעבד גשמי וזה היה עיקר ענין יציאת מצרים שיצאו רק באמונה פשוטה רק מצד עוצם השפלות ולא כעובד בטעם והשגה והתפעלות התענוג כו' ועל כן נצטוו לאכול מצה שנקרא לחם עני<sup data-n=\"401\">10</sup> כעני ואביון שיחיה בלחמו בשפלות גדולה ונק' מיכלא דמהימנותא<sup data-n=\"402\">11</sup> אמונה הפשוטה דוקא וזה היה התחלה הליכת' בקדש העליון דכתיב וארשתיך לי באמונה<sup data-n=\"403\">12</sup> כו' כנ\"ל ואחר שכבר הלכו והחזיקו בדרך בתוקף אמונה זאת לאחר ז' ימי הפסח הותר להם גם החמץ והשאור שהוא ברוחניות בחי' העבודה שבלב בהתנשאות רשפי אש שבאה מתוך השגה בטוב טעם ודעת האלקי דוקא והיינו בכל ז' שבועות דימי הספירה להיות עולין בקדש בעילוי אחר עילוי בתוקף התפעלות העונג ושמחה דבינה לבא בטוב טעם עריבות מתיקות ידידות<sup data-n=\"404\">13</sup> כו' עד שבמ\"ת קיבלו אור פני מלך חיים<sup data-n=\"405\">14</sup> בהשגה אלקי' בנשמת' באה\"ר בתענוגי' עד כלות נפשם שעל כל דיבור<sup data-n=\"406\">15</sup> כו' כענין טעמו וראו<sup data-n=\"407\">16</sup> שהרי ראו בראיות העין והשכל וכלתה נפשם בעונג נפלא בעריבות ידידות עוז כו' וד\"ל ולפ\"ז הרי מובן דמה שנאסר החמץ בפסח ונצטוו בחמץ בשבועות כמ\"ש בשתי הלחם דשבועות חמץ דוקא תאפינה<sup data-n=\"408\">17</sup> כו' דמפני שבפסח היה מדריגת עבודתם רק בבחי' השפלות בתכלית והוא בבחי' התחלת ההילוך באמונה לבד ובשבועות היו בתכלית העילוי שבעונג שבשכל להיות בבחי' יש מורגש כענין להנחיל אוהבי יש<sup data-n=\"409\">18</sup> דעה\"ב הרי במ\"ת היה מעין עוה\"ב ממש חירות ממ\"ה<sup data-n=\"410\">19</sup> כו' וא\"כ היה צריך שיהיה הציוי בענין העבודה בפסח בשפלות ובשבועות בהגבה' ובאמ' אין בזה הפרש כלל רק בין איסור חמץ ואכיל' מצה לבד אך הענין הוא דמ\"מ בכללות ענין עיקר המדריגה בעבודה שבלב הרי יש הפרש גדול מן הקצה לקצה",[["401","10","<b>מצה שנקרא לחם עני</b>: פ' ראה טז, ג. פסחים קטו, סע\"ב."],["402","11","<b>מיכלא דמהימנותא</b>: נסמן לעיל ח, ב."],["403","12","<b>וארשתיך לי באמונה</b>: הושע ב, כב."],["404","13","<b>עריבות מתיקות ידידות</b>: ראה בסמוך בפנים. לעיל ז, ב ובהנסמן במ\"מ לשם."],["405","14","<b>אור פני מלך חיים</b>: ע\"פ משלי טז, טו."],["406","15","<b>שעל כל דבור</b>: שבת פח, ב."],["407","16","<b>טעמו וראו</b>: תהלים לד, ט. ראה לעיל יז, א."],["408","17","<b>חמץ. . תאפינה</b>: אמור כג, יז."],["409","18","<b>להנחיל אוהבי יש</b>: משלי ח, כא."],["410","19","<b>במ\"ת. . חירות ממ\"ה</b>: ראה שמו\"ר רפל\"ב. פמ\"א, ז. זהר בראשית לז, ב."]]],[2800530042,"בין חג הפסח לחג השבועות שזה בשפלות וזה בעילוי אך מ\"מ בתפלה שהיא העבודה שבלב ותו\"מ שניהן שוין כי מה שיש הפרש זה ביניהם הרי הוא אינו בא ומתלבש רק בדבר גשמי דוקא והוא בענין חמץ ומצה דוקא כי בזה יש יתרון גדול לבחי' הגשמיות על בחי' הרוחניות כנ\"ל וד\"ל:\n(ט) <b>ויובן</b> זה בהקדים תחלה ענין א' והוא בענין עצמו' אא\"ס ב\"ה שהוא בבחי' אח\"פ בתכלית ונק' עילאה על כל עילאין<sup data-n=\"411\">1</sup> סדכ\"ס<sup data-n=\"412\">2</sup> ולמת\"ב כלל<sup data-n=\"413\">3</sup> אפי' מחשבה דא\"ק כו' והיינו בעצמו' א\"ס ממש שלפני בחי' הצמצום הראשון דקו\"ח כידוע שנקרא יחיד שלמעלה מאחד<sup data-n=\"414\">4</sup> כמ\"ש אנת הוא חד<sup data-n=\"415\">5</sup> ולא בחושבן דהיינו ולא בחושבן י\"ס כלל וכמו שמסיים ולאו מכל אינון מדות כלל<sup data-n=\"416\">6</sup> וכמ\"ש לך ה' הגדולה והגבורה<sup data-n=\"417\">7</sup> כו' עד שאין הפרש בין גדולה וגבורה שהגם שהמדות חו\"ג הן ב' הפכים ובכלל היינו ב' קוין חח\"ן מימין<sup data-n=\"418\">8</sup> כו' שנחלק מאור הכת' אבל זהו חיצוניות האור דא\"ס שבקו\"ח שבא לכלל התחלקות קוין ימין ושמאל כו' אבל פנימיות אא\"ס שבפנימית הכתר בכלל שאמר בתיקונים אא\"ס מלגיו<sup data-n=\"419\">9</sup> כתרא עילאה מלבר כו' הוא נבדל בערך מכל ההשתלשלות דקו\"ח כו' וז\"ש הנה אלהינו זה<sup data-n=\"420\">10</sup> קוינו לו שהוא נמשך ע\"י תו\"מ בג' קוין כו' עד שגם בקו\"ח שמפני שמאי' שם מפנימיו' אא\"ס גם בו ימצ' בחי' אא\"ס שלמעל' מן הצמצום ע\"כ יש ביכולתו לאכללא שמאלא בימינא<sup data-n=\"421\">11</sup> כו' שזהו בחי' התכללות הקוין בכל היחודים עליונים דע\"ס והיינו ע\"י שם מ\"ה מלגיו דאיהו ארח כל האצי'<sup data-n=\"422\">12</sup> כו' כידוע וזהו שיכול להיות חילוף האורות בכלים להיות אור החסד מאיר בכלי הגבו' ואור הגבו' בכלי החסד וכה\"ג בהתכללות חו\"ג עצמו דבר מהיפוכו וכ\"ז רק מצד שיש בקו\"ח הבוקע ועובר כל האצי' מהארת עצמו' א\"ס שלמת\"ב ואפי' אור צח<sup data-n=\"423\">13</sup> כו' אוכם הוא כו' וכל נהורין<sup data-n=\"424\">14</sup> עילאין מתחשכאן קמיה כו' ואפי' מקור החכמה הקדומה שנק' מחשבה דא\"ק כו' א\"כ גם בחי' הקוין דחו\"ג מתכללי' להיותו נבדל מהכל ואין לשום מדה וספי' תפיסא ביה כלל דאפי' כאשר כבר נאצל האצי' אינו נתפס ומלובש בזה שהרי אמר דאיהו תפיס בכ\"ע<sup data-n=\"425\">15</sup> ולמדת\"ב שזהו רבותא יותר מכמו שהוא למעלה בלתי התלבשות דגם שהוא תפוס ומלובש בכ\"ע דאבי\"ע למדת\"ב א\"כ אין זו תפיסא ממש שאם הי' נתפס ממש הי' לעלמין תפיסא ביה וכמא' הוא מקומו ש\"ע<sup data-n=\"426\">17</sup> ואין העולם מקומו וביאור דבר זה יובן ממשל התלבשות הנפש הרוחניות בכלי הגוף (אע\"פ שאין זה משל אמיתי בדומה לנמשל כי הנפש הרי היא בע\"ג ג\"כ רק מהבדל הרחוק שבין רוחניות הנפש לגוף יובן כדוגמתו למעלה) דהנה אנו רואים בעצמות הנפש הרוחניות כמו שהיא הרי נבדלת היא בערך מכל תאר גשם הנראה ממנה אחר התלבשותה בגוף ונבדלת בערך גם מבחי' הרוחניות דמדות חו\"ג שבלב ומוח חו\"ב הגם שהוא רוחני נחשב גשם גמור לגבי כחות אלו כמו שהם בנפש עצמה כי א\"א לדמות התפעלות הרצון שבלב ומוח באהבה גשמיות לגבי התפעלות הרצון באהבה שבנפש קודם בואה לחומר גופני כמו בנשמות",[["411","1","<b>עילאה על כל עילאין</b>: ת\"ז בהקדמה (יז, א). תס\"ט (קטו, א)."],["412","2","<b>סדכ\"ס</b>: ראה זהר בהקדמה ב, א. ועוד."],["413","3","<b>ולמת\"ב כלל</b>: ת\"ז בהקדמה (יז, א)."],["414","4","<b>יחוד שלמעלה מאחד</b>: ראה לקמן קטז, ב ובהנסמן במ\"מ לשם."],["415","5","<b>אנת הוא חד</b>: ת\"ז שם."],["416","6","<b>ולאו מכל אינון מדות כלל</b>: ראה ת\"ז שם (יז, ב)."],["417","7","<b>לך ה' הגדולה והגבורה</b>: דהי\"א כט, יא."],["418","8","<b>חח\"ן מימין</b>: נסמן לקמן קכד, ב."],["419","9","<b>אא\"ס מלגיו</b>: ראה ת\"ז סתכ\"ב (סח, ב). הנסמן בתו\"ח לך פג, ב הערה 17."],["420","10","<b>הנה אלקינו זה</b>: ישעי' כה, ט."],["421","11","<b>לאכללא שמאלא בימינא</b>: ראה זהר ר\"פ קרח."],["422","12","<b>שם מ\"ה. . כל האצי'</b>: ראה ת\"ז בהקדמה (יז, א) ובהדרת מלך שם (ע' קיב). סידור אדה\"ז סדר מנחת ערב שבת."],["423","13","<b>אור צח</b>: ראה ת\"ז ת\"ע (קלה, ב). מאמרי אדה\"א דברים ח\"ד ע' א'תה. וש\"נ."],["424","14","<b>וכל נהורין</b>: ראה זהר בראשית כג, א."],["425","15","<b>דאיהו תפיס בכ\"ע</b>: נסמן לקמן קטו, ב."],["426","17","<b>הוא מקומו ש\"ע</b>: נסמן לעיל ב, א."]]],[2800530043,"שנהני' בג\"ע בהתפעלות אה\"ר כו' שאין לדמות לזה ערך גם התפעלות נשמות גבוהות שבגופי' בעוה\"ז בעבודה שבלב בתפלה כו' ועכ\"ז אנו רואים במילי דעלמא הרי הרצון שבעצם הנפש באהבה הרוחניות הוא שנמשך בלב וכן השכלה הרוחניות שבכח השכל שבנפש עצמה באה במוח בהתחכמות גשמיות כו' א\"כ צ\"ל שיש חיבור לזה באופן שבא בדרך התלבשות לבד והיינו שנמשך הרצון ואהבת הרצון ומתלב' במהו' אהב' ורצון בלב וכן עד\"ז בשכל שבמוח גשמי ונק' התלבשות זו בשם תפיסא שנתפס שם ממש רק שאינו מוגבל שם אלא כלובש ופושט כו' וראיה לזה מענין הסתלקות כחות הנפש בשינה שאינו מותפס כ\"כ במדות ושכל שבמוח ולב (אז גם המדות ושכל בהסתלקות כו') ועד\"ז ממש יובן גם בעצם הנפש ממש שנבדלת היא בערך גם מכחותיה הרוחניי' בהיותה בלא גוף ע\"ד דוגמא כשאנו מדמין לומר שיש רצון לנפש עצמו הרי הענין של רצון הוא מה שתרצה הנפש כו' וא\"א לומר שיהיה חיבור לרצון עם עצם הרוחניות הפשוטה דנפש עצמה כמו שרחוק ערך רצון שבלב לרצון שבנפש וכן כל כחות שלה בנפש המדברת דבר שכל ויש בה מדות חו\"ג כלולים בעצמותם כידוע הנה כל זה בא דרך התלבשות כנ\"ל בכחות הנפש בגוף דהיינו שהנפש תומשך ותתלבש במהות רצון ובמהות שכל ונתפסת בהם וה\"ז כפושט ולובש כנ\"ל והעיקר הוא בחי' המשכת עצם הנפש מה שתומשך להתלבש בכח הרצון או תומשך להתלבש בכח החכמה שנבדלת משניהם רק שלפעמים תתלבש ברצון ולפעמים בשכל ופושט מזה לזה וכן במדות חו\"ג דאע\"פ שהן ב' הפכים פושט' עצמה מכח החסד לכח הדין או להיפך הגם שיש במהות ועצם הנפש לכ\"א בפ\"ע מ\"מ לגבי עצם הנפש אינם ב' הפכים כלל מאחר שאין בה מתוארים אלו כלל רק שנתפסת ומתלבשת בהן אשר ע\"כ יכולה לפשוט עצמה מלבוש חסד ללבוש דין וכן מלבוש רצון לחכמה כו' כי אין לכולם תפיסא בעצם מהותה כלל אע\"פ שנתפסת בהן ממש וד\"ל וע\"ד דוגמא הנה אנו רואים בהתלבשות הרוחניות בגשמיות באברים שהרצון הרוחני שעולה במוח להניע ידו או רגלו הימנית מיד היד ינוע וילך הרגל בלי עיכוב כלל ויכול לפשוט ולהתלבש ביד ורגל השמאל להניעם ולהניח יד ורגל ימין כו' א\"כ ודאי זהו כלבוש ממש וכן בחו\"ג שבלב מתהפך בלבו מחסד לדין שזהו שינוי הרצון הרוחני מלבוש חסד ודין כו' ועד\"ז יובן באותה התנועה דרגל עצמה שהיא מן הרצון שבגידי המוח הרי מי הכריח לרצון זה שבמוח ודאי זהו הכח רצון רוחני שבנפש עצמה הוא שבא בהתלבשות ברצון זה שבמוח ומשתנה מדבר להיפוכו א\"כ ודאי שגם רצון הרוחני שבנפש אינו אלא לבוש ע\"כ ישונה וממנו ישונה הרצון שבמוח לשנות התנועה שברגל וכה\"ג לפי שעצם הנפש עצמה מובדלת מכל תוארים אלה ע\"כ מושלת בהתלבשות בהם בשינוי דבר להיפוכו וכמ\"כ בחו\"ג שבלב כו' משום שאין לחו\"ג שבנפש הרוחניות תפיסא בעצם כלל (ואע\"פ שהנפש עצמה מתפעלת ממקרי הגוף בעונג וצער הגשמי זהו בא רק דרך התלבשות וא\"כ איך יתכן הגיהנם והג\"ע שזהו עונג וצער לנפש עצמה אך באמת אין המשל הזה"],[2800530044,"רק לדמות מזה למעלה בהבדלת הערך ממה שיכול להיות ההבדל בין רוחניות לגשמיות ואמנם הנפש בע\"ג וכחותי' מתייחסים אליה בעצם וגם בהיותם בגוף ע\"כ תתפעל כו' וד\"ל) אך הנה לפי כל הנ\"ל יובן שיש יתרון מעלה בגוף יותר מכחות הנפש עצמה גם מכמו שהן ברוחניות הנפש עצמה והוא בפעולת האברים בגשמית דוקא אע\"פ שאינם מקבלים רק מבחי' הרוחניות שבא בהתלבשות בגוף כנ\"ל כמו אור הרצון הרוחני העולה במוח לילך ולהניע ברגלו דודאי תנועת הילוך הרגל אינו בא רק מן הרצון הרוחני שבמוח שמלובש בו כנ\"ל אבל מי הכריח לרצון זה הרי הוא כח הרצון שבנפש שגם הוא אינו אלא לבוש כנ\"ל אם כן ודאי שלא היה סיבת זה ההילוך ברגל רק מצד הרצון עצמו שהרי לא מצד עצמו הכריח לתנועה זו ברגל רק מכח הרצון הרוחני שמעוררו ע\"י התלבשות וגם כח הרצון זה מקבל גם הוא דרך התלבשות מהמשכת עצם הנפש שנמשכה להתלבש במהות כח הרצון הזה כנ\"ל ולפ\"ז הרי יובן שגוף הילוך הרגל קדם להיות בעצם הנפש מאחר שמחמתו הנפש באה בכח הרצון לעורר הרצון שבגוף לתנועת הרגל א\"כ ודאי הליכה זו ברגל הגשמי קדמה בעצם הנפש קודם שנמשכ' עדיין במהות רצון כו' ואנו רואין כן בחוש שכאשר ילך אדם ברגליו זהו בא מעצם נפשו שעושה רצון להילוך זה ואין הרצון רק כמו אמצעי כו' שהעיקר הוא ההילוך עצמו שבא מעצם הנפש ממש והרצון הרוחני הוא שמוציא מכאה\"פ לבד ולא שהילוך זה מן הרצון מצד עצמו רק מה שקיבל ממהות הנפש כו' וזהו הוראה גמור' שיש אחיזה ותפיס' להילוך הגשמי במהו\"ע דנפש קודם שנמשך בהתלבשות ברצון ומדות כו' ועד\"ז גם בהתלבשו' הרצון במדו' חו\"ג שבלב דודאי גם חו\"ג הרוחני' יותר אינם רק בחי' לבוש כנ\"ל א\"כ גוף מעשה החסד שעושה בידו דוקא אע\"פ שמקבל מרצון של אהבה הרוחניות שבלב והוא מקבל מרצון אהבה היותר רוחני שבנפש עצמה כנ\"ל מ\"מ יש לגוף מעשה החסד עצמו תפיסא ואחיזה במהות עצם הנפש ממש טרם המשכתה בהתלבשות ברצון ואהבה הרוחניות כנ\"ל בתנועת הרגל וד\"ל ונמצא מובן מכ\"ז שבזאת יש יתרון גדול בסוף מעשה בפו\"מ על כחות הנפש עצמן ומהותן היותר מעולי' במעלה עד שכולם אינם רק כמו אמצעי לחבר עצם הנפש עם סוף מעשה כו' וד\"ל:\n(י) <b>וע\"פ</b> כל זה יובן הדוגמא למעלה בבחי' התלבשות עצמות ומהות אא\"ס בקו\"ח עד התחלקות קוין דע\"ס באו\"כ דאצי' כנ\"ל דגם דאיהו תפיס בהו למדת\"ב כלל כנ\"ל דהיינו ע\"ד דוגמא מהמשכת עצם הנפש להתלבש בכח הרצון וכח השכל ופושט ולובש כו' כך גם בחי' ע\"ס הגנוזות בעצמות המאציל אינם רק בבחי' לבוש ולמדת\"ב אפי' חכמה הקדומה וכן הרצון הקדום כמו כשעלה ברצונו<sup data-n=\"427\">1</sup> הפשוט להאציל כו' וכן בחי' המדות חו\"ג שבו הגם שהן נעשי' ב' הפכים בהשתלשלות דקו\"ח בקוין דאצי' אינם ב' הפכים כלל בעצמות המאציל עד דגם לאחר שהאצילן יכול לחלוף האור בכלי המנגדו וכן התכללות חו\"ג כנ\"ל עד בחי' מל' דא\"ס",[["427","1","<b>כשעלה ברצונו</b>: נסמן לקמן קטו, א."]]],[2800530045,"הוא ג\"כ בבחי' לבוש וכמ\"ש ה' מלך<sup data-n=\"428\">2</sup> גאות לבש כו' וכמאמר בי' לבושים<sup data-n=\"429\">3</sup> נתלבש הקב\"ה שהוא עצמות המאציל בחכמה ובתבונה ובדעת<sup data-n=\"430\">4</sup> כו' להיותו נבדל ומרומם מכל תואר ספי' ומדה גם בהעלם עצמותו דהרי אמר לאו מכל אינון מדות כלל רק שנק' בשם התלבשות לבד וזהו כללות ענין התלבשות הפרצופים שכולם אינם רק בבחי' לבוש וזה מלביש לזה כו' כמו שבגלוי הרצון העצמות שנק' כתר דאצי' ה\"ז עד\"מ כגלוי רצון שבמוח למטה שהוא לבוש שנמשך ומלובש בו רצון העליון שבהעלם העצמות וכן חכמה הגנוזה שבעצמות נמשך ומתלבש במהות חכמה דאצי' וגם חכמה ורצון דא\"ק נק' לבוש ולמת\"ב כלל עד רום המעלות רק שיורד בהשתלשלות בבחי' התלבשות ותפיסא לבד דהיינו שמהו\"ע נמשך ומתלבש בלבוש אחר לבוש עד בחי' התלבשות האורות בכלים בז\"א דאצי' שהן המדות חו\"ג כחו\"ג שבלב וז\"ש לך ה' הגדולה כו' וראיה לזה שהרי אנו אומרים בכל בקשה י\"ר מלפניך שיכבשו רחמיך את כעסך<sup data-n=\"431\">5</sup> שהן חו\"ג שבלב אדם העליון דאצי' וה\"ז שינוי שיהיה רצון באהבה וחסד שבלב ואיך נתהפך מרצון של דין ורוגז שיכבשו רחמיו ויגברו על מדה\"ד אין זה אלא שפושט א\"ע מכח הרצון שבעצמו' שנתלבש בבחי' אצי' במדה\"ד ומתלבש מחדש ברצון היפוכו של חסד ואהבה והיינו ל' י\"ר מלפניך דוקא שזהו מהו\"ע דוקא שיומשך לרצון של רחמים לגבור על רצון של דין ויכבשו רחמיו כו' עד שיורד ונמשך למטה מטה מאצי' לבי\"ע לפעול בפו\"מ החסד והרחמים לרחם על עני מדוכא ועל חולה מסוכן להחיותם וכה\"ג וכך הוא בכל חידוש מע\"ב בכל יום שברצונו מחדש על כל הברואים להשפיל ולהרים משום דכמצביי' עביד<sup data-n=\"432\">6</sup> בחיל שמיא ומסדר הכוכבים<sup data-n=\"433\">7</sup> והמזלות כרצונו דוקא שזהו שרצון העצמות נשתנה כו' וע\"ד דוגמ' מכל הנ\"ל בכחות נפש האדם בגוף שגם שרשם בנפש אינם רק בבחי' המשכת הנפש להתלבש בהן כו' וד\"ל (ובזה יובן בתו' ביאור כל המאמרים דלעיל כמ\"ש אנת הוא חד ולא בחושבן י\"ס כו' ואין הפרש בין חו\"ג כלל דלמד\"ת בי' כלל גם לאחר שנתפס בהן משום דאין זה בבחי' תפיסא ממש וכמא' אין העולם מקומו כנ\"ל וד\"ל) ומעתה יובן ג\"כ הנמשל מענין הנ\"ל בסוף מעשה דפעולת האברים בגשמיות שהן למעלה גם מכחות הנפש כמו שהן ברוחניות הנפש עצמ' וראיה מתנועת הרגל ומעשה החסד בפ\"מ כנ\"ל באריכות דמזה יובן ג\"כ למעלה בענין סוף מעשה שעלה במח' תחל' היינו תחלה להמשכות מהו\"ע בהתלבשות דרצון וחכמה ומדות שבהעל' העצמות כו' והיינו במהו\"ע ממש כנ\"ל דהילוך הגשמי קדם להיות במהו\"ע הנפש טרם שנמשכה לכח הרצון הרוחני שיעורר לרצון שבמוח עד שאין כ\"ז רק בבחי' אמצעי לחבר כו' כך כל הצמצום המשכת מהו\"ע בלבושים די\"ס דעצמות לבוא בגלוי דאצי' באו\"כ דבאמת הרי מצד עצמו לאו מכל מדות כלל כנ\"ל דלמדת\"ב כלל רק להיות סוף מעשה בגשמיות הבריאה יש מאין א\"כ קדם הסוף מעשה במהו\"ע טרם שנמשך להתלבש ברצון הפשוט העצמי להיות לו רצון להאציל כו' כנ\"ל במשל ההילוך ברגל וד\"ל וזהו טעם דמ\"ד ארץ<sup data-n=\"434\">8</sup>",[["428","2","<b>ה' מלך</b>: תהלים צג, א."],["429","3","<b>בי' לבושים</b>: ראה רקאנטי בראשית א, ג [ירושלים תשכ\"א ג, ג] בשם הפסיקתא. שם ג, ה [יב, ד]. יל\"ש ישעי' סס\"א (רמז תקו). מאמרי אדה\"א דברים ח\"ב ע' תרלא. וש\"נ. שמות ח\"ב ע' תרסג בשם ס\"י."],["430","4","<b>בחכמה ובתבונה ובדעת</b>: חגיגה יב, א."],["431","5","<b>אנו אומרים. . כעסך</b>: בסדר תקיעת שופר בסידור האריז\"ל [בדילוג]."],["432","6","<b>דכמצביי' עביד</b>: דניאל ד, לב."],["433","7","<b>ומסדר הכוכבים</b>: ע\"פ תפלת ערבית. ראה גם לקמן ל, א. תו\"ח מקץ רכ, סע\"ב."],["434","8","<b>ארץ קדמה לשמים</b>: חגיגה יב, א. ראה מאמרי אדה\"א ויקרא ח\"א ע' רלא. וש\"נ. תו\"ח ר\"פ ויגש ובהנסמן במ\"מ לשם."]]],[2800530046,"קדמה לשמים וכמו משל הנ\"ל בהילוך הרגל שגוף מעשה דהילוך זה הוא בא בעצם הנפש שהוא שמעורר לרצון להניע הרגל והרצון לא מצד עצמו הכריח לרגל לילך כ\"א ע\"י הכרח שהכריחו מעצמו' הנפש הרי הי' הילוך זה בעצם הנפש תחלה קודם שנמשך עדיין לרצון כו' כך כתיב והארץ הדום רגלי<sup data-n=\"435\">1</sup> שנק' רגל בבחי' סוף מעשה וכמו סוף מעשה החסד בפו\"מ בידו דכתיב אף ידי יסדה ארץ<sup data-n=\"436\">2</sup> כו' וכתי' עולם חסד יבנה<sup data-n=\"437\">3</sup> הרי כל מה שעל' ברצונו הפשוט כו' משום שחפץ חסד הוא<sup data-n=\"438\">5</sup> במוה\"ע<sup data-n=\"439\">6</sup> כמ\"ש בע\"ח<sup data-n=\"440\">4</sup> מטעם זה שהוא מטבע הטוב להטיב<sup data-n=\"441\">7</sup> מצד העצם ע\"כ מתלבש ברצון לזה כו' הכל הוא בשביל החסד בפו\"מ דוקא א\"כ הסוף מעשה עבמ\"ת והוא שהכריח לרצון הפשוט ואע\"פ שאח\"כ הוא בהיפוך שהרצון מקור לרצון של חסד שבלב וחס' שבלב מקו' להשתל' החסד הגשמי מ\"מ בשרש זה החסד הרי החסד הגשמי בפ\"מ קדם להתעוררו' הרצון גם בעצמו' ממש כו' וד\"ל. ונמצא מובן מכל הנ\"ל שיש יתרון גדול לסוף מעש' בגשמיו' גם על המעולה שברוחניו' כמו רצון וחכמה ומדות שהן בעצמו' כו' וגם מובן ממילא הטעם לפי שבחי' הרוחניו' דרצון וחכמה אין להם בעצמות תפיסא דלמת\"ב כלל כנ\"ל (ואינ' רק כמו אמצעי לחבר כו' כנ\"ל) א\"כ ודאי דלגבי מהו\"ע א\"ס ב\"ה אין חילוק והפרש כלל במדריגות השתלשלות הרצון ושכל ומדו' מעילה לעיל' בין היותר עליון עד היותר תחתון שזהו כמו מרצון העצמות עד רצון שבמעשה בפו\"מ שכל אשר חפץ עשה<sup data-n=\"442\">8</sup> בפ\"מ אע\"פ שזה תכלית העילוי וזה תכלית הירידה מאחר דלית מאן דת\"ב כלל וכל השתלשלות דע\"ס באבי\"ע אינו בא רק מצד בחי' המשכת מהו\"ע בהתלבשות לבד ולא מצד עצמותו כלל שלזה אין הפרש לגבי מהו\"ע בין ב' הפכים דחו\"ג עד חו\"ג שבעצמו' כו' כנ\"ל א\"כ בכל בחי' השתלשלו' הרוחני' מראש הכל לסוף הכל אין הפר' בין העליון שבה' לתחתון שבהם לגבי מהו\"ע כלל וכמו שאמ' דקמי' כחשיכה כאו'<sup data-n=\"443\">9</sup> וכה\"ג כידוע אבל בבחי' המעשה בגשמיות דוקא שזה עבמ\"ת טרם שבא בהתלבשות בע\"ס כנ\"ל בענין ארץ קדמה כו' כמשל ההילוך והמעשה בפ\"מ כו' הנה זהו מגיע במהו\"ע יותר מאחר שבשביל זה ירד' בהתלבשות כו' כנ\"ל עד שבחי' חו\"ג שבא בפ\"מ דוקא הוא שעבמ\"ת טרם לרצון דחו\"ג שברוחניות וא\"כ הרי יש יתרון גדול לגשמי' דגוף המעש' שבו תלוי הכל ולא על הרוחניו' שמריש כל דרגין עד הרוחניו' שבעשי' שלכולם אין תפיסא כלל במהו\"ע ועליון ותחתון שבהן שוין וד\"ל ואחר כ\"ז יתורץ ענין הנ\"ל בחמץ ומצה דהנה דוק' בסוף מעש' בפו\"מ שהוא באכילת חמץ גשמי הכרת תכרת הנפש מן שרש' הראשון כנ\"ל ולא ע\"י התנשאות וגסות הרוחני שהוא רוחני עכ\"פ ואינו גשמי כ\"כ כמו החמץ ושאו' לפי שכל בחי' רוחניו' שאיננו גשם גמור כעשי' גשמיות הרי אין להם תפיסא בעצמו' כלל כמו שהעליון שברוחניות למת\"ב כך התחתון והשפל במדרגת הרוחניו' שניהם שוין לגבי מהו\"ע כנ\"ל וא\"כ בבחי' חו\"ג דחמץ ומצה הרי בחי' גבורה דאצי' למעל' שבריבוי השתלשלות עד נוגה דעשי' שהגבו' שם הוא בחי' התנשאות וגסות הרוח שזהו תכלית הירידה הכל שוה וכמ\"ש קמי' כחשיכ' כאור' כו' לפי שכמו דחו\"ג דעצמו' אין להם תפיס' בי' ולא נק' בשם גבור' כלל וכמ\"ש ולאו מכל אינון מדו' כלל",[["435","1","<b>והארץ הדום רגלי</b>: ישעי' סו, א."],["436","2","<b>אף ידי יסדה ארץ</b>: ישעי' מח, יג."],["437","3","<b>עולם חסד יבנה</b>: תהלים פט, ג."],["438","5","<b>שחפץ חסד הוא</b>: מיכה ז, יח."],["439","6","<b>במוה\"ע</b>: נסמן לעיל ב, א."],["440","4","<b>שעל' ברצונו הפשוט. . בע\"ח</b>: נסמן לקמן קטו, א."],["441","7","<b>מטבע הטוב להטיב</b>: ראה שהיחוה\"א פ\"ד. מאמרי אדה\"א קונטרסים ע' ה. וש\"נ. תו\"ח בראשית ל, ב הערה 4."],["442","8","<b>שכל אשר חפץ עשה</b>: תהלים קלה, ו."],["443","9","<b>דקמי' כחשיכה כאו'</b>: ראה [תהלים קלט, יב. הנסמן במאמרי אדה\"א נ\"ך ע' שסו]. עט\"ר ע' נא."]]],[2800530047,"כך גם גסות דנוגה בהתנשאות או מדה\"ד ברוגז שלמטה אינו נק' גבורות קשות כלל לפי שכל השתלשלות הרוחניות כולם לית מאן דת\"ב וכולן שוין עד שלא נק' הגסות דנוגה גבורות קשות כמו שגבו' עליונה עד רום המעלות לא נק' בשם גבורה כלל וכן במדת החסד אין חילוק בין היותר עליון עד החסד הרוחני דנוגה דעשי' כנ\"ל אך ורק בחו\"ג שבאים בגוף המעש' דוק' בזה יש יתרון גדול לגשמיות על הרוחניות כנ\"ל וא\"כ הרי הגסו' וההתנשאות לא יחייב כרת כלל וכן הכעס והרוגז רק האוכל שאור וחמץ בגשמיות דוקא שבזה מעורר לבחי' הגבורות במהו\"ע שיומשך להתלבש ברצון של דין ולזה גורם שיכרת הנפש כו' דגם מצד טעם שזהו בחי' יש ודבר כנ\"ל ג\"כ דוקא ביש גשמי שמן החמץ גשמי ולא בישות וגסות הרוחני שבלב וכה\"ג וד\"ל וכמ\"כ במצות אכילת מצה בגשמיו' דקמח ומים בלי שאור המחמיץ כו' תדבק הנפש במהו\"ע ממש כנ\"ל ולא ע\"י השפלות והקטנו' בלב ומוח שהן רוחניות דבבחי' הרוחניו' אין להם אחיזה ותפיסא בעצמות אף להיותר עליון שבהם בשוה עם התחתון שבהם מטעם כל הנ\"ל בענין איהו תפיס בכולהו עלמין ולית מדת\"ב וזהו יסוד כל התו\"מ שבאו בפ\"מ דוק' ולא נתנו בבחי' הרוחניו' כלל כי המעש' עיק' כמצו' תפילין וציצית בקלף וצמר גשמי לעשות' בפו\"מ וכן מצו' צדק' בחסד גשמי דוקא וכה\"ג כל המצות (רק מצות אוי\"ר ויחוד אלקו' תלויי' בלב ומוח ברוחניות וגם זה העיקר שבהם הוא למעש' דוק' שהרי עיק' מצות אוי\"ר הוא מה שמקב' עמ\"ש באוי\"ר לעשות בפ\"מ וא\"ל אינו כלום וכן ביח\"ע ויח\"ת בק\"ש עיקר המצוה שיאמר פ' ק\"ש לצאת י\"ח דוקא כמ\"ש בפע\"ח וד\"ל<sup data-n=\"444\">10</sup> :\n(יא) <b>והנה</b> אחר כל הנ\"ל יובן בתוס' ביאור ענין ורעה אמונ' הנ\"ל שאין הפי' שהאמונה היא הרועה אלא בהיפוך שזן ומפרנס את האמונ' לפי שיש רועה שהוא הרועה שזן ומפרנס את האמונ' וביאור הדבר היינו שכנ\"י נק' אמונה דאיהו אמת ואיהי אמונה<sup data-n=\"445\">11</sup> וכמ\"ש אמת ואמונה כל זאת וקיים עלינו<sup data-n=\"446\">12</sup> כו' להיות שהן מקבלים במוחין ומדות שלהם מהארת עצמות א\"ס ב\"ה שנק' אמת וכמ\"ש ואמת ה'<sup data-n=\"447\">13</sup> כו' ע\"י תו\"מ ותפלה אך כל השנה נמשך לנשמות שלהם פרנסה ושפע זאת על ידי המדות עליונות דז\"א שבתוכו רק מבחי' חיצוניות דבחי' מ\"ה דאור אבא דאצילות שעל זה אמר כי אתה אבינו<sup data-n=\"448\">14</sup> כידוע וזה בחי' השגות אלקו' בבינה לבא<sup data-n=\"449\">15</sup> בכל חד וחד לפום שיעורא דילי'<sup data-n=\"450\">16</sup> ובתו\"מ שלו באוי\"ר שנמשך שרשו מבחי' בינה דמל' דאצי' ה\"א אחרונה דשם הוי'<sup data-n=\"451\">17</sup> שמקבל מן המדות ששרשם בבינה דאצי' שמלובש בה חיצוניות דמוחין דאבא לבד אבל במצות אכילת מצה בליל הא' בא ונמשך פרנס' זו דכנ\"י ממהו\"ע דמוחין דאבא ששם גלוי פנימי' ועצמו' דאא\"ס ב\"ה והוא שנמשך כח וחיזוק האמונ' בנש\"י שהיא מגעת במהו\"ע ממש כנ\"ל ולא שמשיגי' במהו\"ע בהשגה ודעת שהרי אין במצה טעם רק שבא בהעלם והלבשה עכ\"פ שנק' קטנות דאבא כנ\"ל אבל בחי' קטנות זה יש בו יתרון מעלה מבחי' הגדלות כמו התינוק שיודע לקרות אבא כו' כנ\"ל שהוא במהו\"ע ממש והוא בעצם הדבר כמו שהוא בהוייתו ומהותו העצמי והוא בחי' עצם כח מ\"ה דחכ' כמו שהוא ע\"כ כל א'",[["444","10","<b>וד\"ל</b>: כנצ\"ל: וד\"ל)."],["445","11","<b>דאיהו אמת ואיהי אמונה</b>: נסמן לעיל ז, א."],["446","12","<b>אמת ואמונה. . עלינו</b>: תפלת ערבית (ברכת אמת ואמונה)."],["447","13","<b>ואמת ה'</b>: תהלים קיז, ב."],["448","14","<b>כי אתה אבינו</b>: ישעי' סג, טז."],["449","15","<b>בבינה לבא</b>: ת\"ז בהקדמה (יז, א)."],["450","16","<b>בכל חד. . שיעורא דילי'</b>: ראה תניא בהקדמה ע\"פ הזהר וירא קג, ריש ע\"ב."],["451","17","<b>דמל'. . ה\"א. . הוי'</b>: ראה זהר ויקרא יז, א. תו\"ח ויצא קסז, ג הערה 38."]]],[2800530048,"יוכל לומ' אבינו בתפלה דכל השנה שאין זה רק ע\"י המצה שבליל א' דפסח שנק' מיכלא דמהימנות' שזן ומפרנס כח האמונה שבא ממהו\"ע דוקא וזהו ורעה אמונ' וד\"ל וזהו מצו' יאכל את ז' הימי'<sup data-n=\"452\">1</sup> יאכל ל' ממילא פי' שהז' ימי' יאכלו מצות וזה פלא דהל\"ל ז' ימים תאכלו כמ\"ש בכל המקומות דמשמעו בז' הימים האלה תאכלו מצות ואיך יתכן שיאכלו הז' ימים מצות שהימים אינם בני אכילה כלל אך הענין הוא דז' ימים אלה הן ז' מדות שבמל' דאצי' שרש נש\"י למעלה וצוה ה' שיומשך שפע פרנסה דאמונה שהיא באה ממקום גבוה ביותר והיינו ממהו\"ע דמוחין דאבא לבחי' ז' הימים דמל' שכוללי' כל נש\"י לגולגלותם וזהו מצות יאכל לז' הימים כו' כי כל השנה אין המל' מקבלת מוחין חדשי' רק מבחי' נה\"י דז\"א וגם זאת אינו רק מחיצוניות מוחין דאו\"א שבז\"א ואין במל' ממהו\"ע דמוחין דאבא אפי' בהעלם והלבשה דקטנות הנ\"ל אבל בליל א' דפסח נמשך ממהו\"ע דאור אבא בהעלם והלבשה דקטנות במל' ולפי שזהו ממקו' גבוה מאד נעלה שאין ערוך לו גם גלוי אורות ומוחין דאו\"א שבז\"א ומל' כל השנה ע\"כ אומר בהגד' חכם מה הוא אומר מה העדות והחוקים כו' ולכאור' אם חכם הוא איך אינו יודע מה העדות והחוקים האלה כו' ודאי למד וידע היטב אלא הכונה בבחי' מהו\"ע דמוחין דאבא בבחי' ג\"ר שבו שלא נמשך כל השנה ע\"י בחי' חכמ' שמתלבשת בבינה כלל וכ\"ש שלא נמשך במדות דז\"א ע\"כ גם החכם דחכמ' עילאה שואל מה העדות כו' אשר צוה ה' אתכם כלומר שמתמיה מאין צוה ה' אתכם לכנ\"י שהוא בחי' המל' ואיך נעלם הימנו כל המוחין העצמיי' הללו כו' (כמ\"ש בכונות<sup data-n=\"453\">2</sup> ) וזהו שאמ' יאכל ממילא ממקום גבוה מפני שלא יוכל להתמשך שם רק בדרך דילוג גדול ובהעלם והלבשה דבחי' הקטנו' דוק' וכנ\"ל בענין התינוק יודע לקרות אבא מפני שמזה דוקא יבא בחי' הגדלות דאבא במ\"ת כנ\"ל וד\"ל. ומעתה יש להבין<sup data-n=\"454\">3</sup> מ\"ש בשבועות בשתי הלחם חמץ תאפינה<sup data-n=\"455\">4</sup> דלכאורה הוא דבר פלא גדול איך יתכן שבחג השבועות שהוא זמן מ\"ת הותר החמץ שהוא בשרשו בחי' גבורות בחי' יש ודבר ומסתעף הימנו בחי' גבורות קשות דק\"נ<sup data-n=\"456\">5</sup> שהוא ההתנשאות והגסות כנ\"ל שהוא היפך גמור המנגד לחכמה שבתור' כח מ\"ה בחי' ביטול בתכלית כידוע דאורייתא מח\"ע נפקת<sup data-n=\"457\">6</sup> ואא\"ס אינו שורה כ\"א בבחי' אין ומ\"ה בתכלית שהוא בחי' חכמה<sup data-n=\"458\">7</sup> הקדומה דאור תורה ובאור פניו נתן לנו את תורתו וכמאמ' מה להלן באימה וביראה<sup data-n=\"459\">8</sup> כו' והחמץ הוא ההיפוך הגמור ממש כנ\"ל ומלבד שהותר החמץ עוד נוסף ע\"ז שנעשה למצוה וחובה כמ\"ש חמץ תאפינה חמץ דוקא ולא מצה ושתי הלחם הן תושב\"כ ותושבע\"פ<sup data-n=\"460\">9</sup> כידוע ובודאי יש כאן ק\"ו גדול מחג הפסח שלא היה אז רק בחי' ההתחלה של ההילוך בדרכי ה' כמ\"ש חסד נעורייך כו' לכתך אחרי<sup data-n=\"461\">10</sup> כו' היינו שקיבלו עליהם רק לצאת מאפילה דנש\"ט לאור גדול בהתדבקות במהו\"ע באמונה פשוטה לבד כנ\"ל שאין זה רק בחי' ההתעוררות לבד לילך אחר ה' כו' נאסר להם החמץ אז בתכלית הזהירות והבדלה באזהרות כמה פעמים כל מחמצת לא תאכלו<sup data-n=\"462\">11</sup> כו' לפי שהחמץ הוא המנגד לגלוי אור ה' שנגלה עליהם בליל אחד כ\"כ עד שאמר כי כל אוכל<sup data-n=\"463\">12</sup> כו'",[["452","1","<b>מצות יאכל. . הימי'</b>: בא יג, ז. ראה גם ש\"ך פינחס כה, טז. סידור סדר הגדה חצר, ב. לקו\"ת פקודי ה, ב. צו יב, ב."],["453","2","<b>כמ\"ש בכונות</b>: ראה פע\"ח (שחה\"מ) שכ\"א פ\"ז פיסקא חכם. מ\"ח וסידור האריז\"ל שם."],["454","3","<b>ומעתה יש להבין</b>: ראה מאמרי אדה\"ז על פרשיות התורה ח\"ב כאן ע' תקנא."],["455","4","<b>חמץ תאפינה</b>: אמור כג, יז."],["456","5","<b>גבורות קשות דק\"נ</b>: ראה גם סידור סדר הגדה שא, ב. ביאוה\"ז תזריע עד, ב."],["457","6","<b>דאורייתא מח\"ע נפקת</b>: זהר בשלח סב, א. יתרו פה, א. (רע\"מ) משפטים קכא, א. קדושים פא, א. חוקת קפב, א. ואתחנן רסא, א."],["458","7","<b>ואא\"ס. . בחי' חכמה</b>: ראה תניא פל\"ה בהגהה."],["459","8","<b>מה להלן באימה וביראה</b>: ברכות כב, א."],["460","9","<b>ושתי הלחם. . ותושבע\"פ</b>: ראה השמטות לזח\"א רס, א."],["461","10","<b>חסד. . לכתך אחרי</b>: ירמי' ב, ב."],["462","11","<b>כל מחמצת לא תאכלו</b>: בא יב, כ."],["463","12","<b>כי כל אוכל</b>: בא יב, טו [בדילוג]."]]],[2800530049,"ונכרתה הנפש ההיא מיום הא' כו' אם כן כ\"ש וקל וחומר גדול שבמ\"ת שנכנסו לפני ולפנים לקבלת התורה פב\"פ שיאסר להם החמץ בתכלית הזהירות הרבה יותר ונהפוך הוא שמלבד שלא נאסר החמץ הרי הוא מצו' וחובה בשתי הלחם שחמץ תאפינה דוקא כו' אך הענין הוא דאדרבה היא הנותנת דמשום שביצ\"מ היה רק בחי' ההתחלה בהילוך בקדש העליון כנ\"ל ע\"כ נאסר להם החמץ בתכלית ונצטוו באכילות מצה דוקא אבל במ\"ת שכבר החזיקו בהילוך אחרי ה' ונכנסו לפני ולפנים לקבל אור פני מלך בבחי' פב\"פ ע\"כ נצטוו בשתי הלחם שיהי' של חמץ דוקא כמ\"ש חמץ תאפינה והטעם לזה יובן עד\"מ (המבואר בזהר<sup data-n=\"464\">13</sup> ) כמו תינוק קטן מיד שגמלוהו משדי אמו שמרגילים אותו במאכלי לחם מעט מעט הנה ודאי א\"א שיתחילו להאכילו לחם גמור בטעמי' שונים שראוים לגדול פן יזיק לנפשו ביותר כי לא הוכן כלי אצטומכא שלו רק לחלב ולא יכיל כלל לחם כידוע שתינוק בן שנה א\"א להאכילו בלחם גס וגם לא מאכלים של לחם עם בשר וכה\"ג אלא רק מאכלים קלים ביותר שלא יורגש בהם טעמים שונים כלל כתבשיל קל של חטים קליות ואח\"כ של חטים ודגן גרוסו' באופן שיוכל להאכילו במשך הזמן לחם חטים אפי' ומבושל. וכ\"ז צריך להתמשך זמן רב ולא בבת אחת. והעיקר הוא שירגילוהו במאכלים קלים שאין בהם טעמים חזקים כ\"כ רק במיעוט הטעם המורגש לנפש כו' כדי שיוכל לקבל כפי מזג כלי אצטומכא שלו הדק ביותר ואח\"כ מעט מעט ירגילוהו בטעמי מאכלי קלים שונים בטעם בלתי מורגש כ\"כ עד שיוכל לאכול לחם גמור וכמ\"כ החולה שקם מחוליו שא\"א להכיל מאכלים של בריאים כי לא יוכל לקבל טעמי מאכלים שהבריאים אוכלים אלא מאכלים קלים בטעמן מאד ומעט מעט ירגילוהו עד שיוכל לקבל כל טעמי מאכלי לחם ובשר החזקים כו' והרי מובן שעיקר התועלת ברגילות המאכלים הקלים לא שיחי' בהם לעולם כי א\"א להבריא שיזון ויחיה מהם אלא שעי\"ז יבא לכלל בריאות שיוכל לקבל ולהכיל מטעמי מאכלים קשים דלחם גמור ובשר שמזה יחיה האדם הבריא כו' וד\"ל (ובזה יובן יותר ענין הטעם שהתינוק יודע לקרות או\"א בטעימ' טעם דגן דוקא אין הכונה בלחם גמור אלא בטעמי מאכלים קלים של דגן עד שירגיל כ\"כ שיוכל לטעום טעם לחם גמור וטעם דגן דקאמר הוא הכנה בלבד וע\"כ אינו יודע רק לקרות אבא לבד וכשירגיל בזמן רב לטעום בגסות טעם לחם מאכלים אלה יביאוהו שיבא לשלימות הבריאות שיוכל לאכול לחם גמור כתינוק בן ג' וד' שנים שאז אין הידיעה לקרות אבא לבד אלא היודע בדעת גמור כגדול) והנמשל מכ\"ז יובן בכנ\"י בטעם מצות אכילת מצות שאכלו ביצ\"מ שנק' לחם עוני בבחי' הקטנות דוקא לפי שהיו אז בבחי' הקטנות ביותר בשרש נשמת' וגם בנשמות שבגופות שלהם ממש כילד קטן הנולד ומתבוסס בדם לידה כמ\"ש ואעבור עליך ואראך מתבוססת בדמיך<sup data-n=\"465\">14</sup> כו' (ואם כבר הגיעו לבחי' ימי הגדלות אחר תשלום ימי היניקה",[["464","13","<b>המבואר בזהר</b>: כ\"ה גם במאמרי אדה\"ז על פרשיות התורה ח\"ב כאן ע' תקנא. ראה זהר תצוה קפג, ב."],["465","14","<b>ואעבור עליך. . בדמיך</b>: יחזקאל טז, ו."]]],[2800530050,"כמ\"ש ותרבי ותגדלי כו' שדים נכונו כו' זהו במ\"ת דוקא אבל במצרים כצמח השדה<sup data-n=\"466\">1</sup> נתתיך בבחי' הקטנות מאד) אך לאחר תשלום זמן עיקר הגלות שהוא רד\"ו שנה<sup data-n=\"467\">2</sup> אע\"פ שהיו עדיין בבחי' נער קטן עכ\"ז התחיל זמן של הרגילות ללחם קל דוקא והוא שא\"א שיכילו נשמתם מזון העליון במטעמי' דבחי' התענוג העליון שבחכמ' כלל וכלל אשר ע\"כ נצטוו בלחם מצה שאין בו טעם שהוא כמו שמרגילים לתינוק שיאכל מאכלים קלים בטעמו כו' והוא המצה שנק' מיכל' דמהימנותא שאין בה טעם כלל כי לא יוכלו לקבל החכמה שיש בה טעם שראוי לגדול בשנים כו' ואמנם עיקר המכוון לא היה שישארו במזון דמצה זו שהרי לא צוה רק ז' ימים לבד<sup data-n=\"468\">3</sup> אלא הכוונה שיהיה עי\"ז כח לקבל טעם לחם גמור שזהו בחי' לחם חמץ דשתי הלחם דשבועות שהוא קבלת חכמת התורה בטוב טעם דוקא כמו טוב טעם ודעת למדני כו'<sup data-n=\"469\">4</sup> כי באור פניך<sup data-n=\"470\">5</sup> נתת לנו תורת חיים שחכמת אדם העליון דהיינו כח מ\"ה דאור פנימית אבא דאצי' תאיר פניו לכנ\"י לקבל פב\"פ ג\"כ בטוב טעם כו' וע\"כ נצטוו אז בשתי הלחם בטעם חמץ דוקא ולא מצה ואמנם אם לא המצה שאכלו ביצ\"מ לא היו יכולים להכיל ולקבל טוב טעם לחמה של תורה זו שקיבלו בסיני כפי המובן ממשל הנ\"ל והענין הוא דיש כח במצה זו שאנו אוכלים שזהו בחי' האמונה הפשוטה שיבא לכלל טוב טעם לקבל ולהכיל כל טוב טעם ועונג העליון שבח\"ע שבתורה שבכתב ותורה שבעל פה שהן שתי הלחם דכתיב בהו לכו לחמו בלחמי<sup data-n=\"471\">6</sup> ודוקא משום דהמצה נקרא לחמא עניא הוא שגורם שיקבלו ב' לחמים דתושב\"כ ושבע\"פ בתכלית הגדלות כנ\"ל באריכות בענין ורעה אמונה דגם משה ע\"ה נצטווה לאכילת מצה לחזק כח האמונה שבנפשו שצדיק באמונתו יחיה<sup data-n=\"472\">7</sup> בעצם שמזה יסתעף ממילא כל בחי' חיים עליונים דאור פנימית ח\"ע שבתורה וזהו יש גם בכל א' מישראל בכח מ\"ה שבנפשו בעצם שהוא ביטול עצמי בכל עיקר נקודת יהדותו העצמי שלמעלה מן הטעם שהוא יסוד כל אשר יומשך מנפשו בהשגות והתפעלות ומעשה הטוב כל הימים והוא עיקר ענין הטעם שבמצות מצה בכל ליל א' דפסח כנ\"ל וד\"ל. ובכ\"ז יתורץ הקושיא דלעיל במה שמצוה בשתי הלחם בחמץ ובפסח נאסר החמץ אע\"פ שלכאורה ק\"ו גדול הוא כנ\"ל דאדרבא היא הנותנת דמשום דיצ\"מ היה ההתחלה באמונה פשוטה הרי זהו הכח העצמי שלמעלה מן השכל והטעם ע\"כ נאסר להם לחם חמץ שיש בו טעם בתכלית הזהירות וההבדלה אבל במ\"ת שהגיעו לבחי' כלי בית קיבול להכיל כל מיני טעם לחמה של תורה נצטוו דוקא בשתי הלחם בחמץ שיש בו טעם מורגש כענין טוב טעם ודעת כו' כנ\"ל ואמנם מצה זו שנצטוו בליל א' דפסח הוא שעושה בכנ\"י בחי' כלי בית קיבול במוח ולב ומעשה להכיל בנפש' ולקבל כל טוב טעם ועונג העליון שבחכמ' דתורה לקבל פב\"פ מח\"ע דאור פני מלך כו' מטעם הנ\"ל דהאמונה היא שרש ויסוד כל מה שמסתעף מן הנפש גם באה\"ר ושכל בעונג נפלא וכנ\"ל באריכות בענין מה שאמר שבא",[["466","1","<b>ותרבי. . שדים. . כצמח השדה</b>: יחזקאל שם, ז."],["467","2","<b>הגלות שהוא רד\"ו שנה</b>: ראה תנחומא מקץ ח. רש\"י מקץ מב, ב."],["468","3","<b>לא צוה רק ז' ימים לבד</b>: ראה פסחים כח, ב דר\"י סמוכין לא דריש. תוספתא פסחים ספ\"ח ובאור הגנוז שם. תוספות השלם [ירושלים תשמ\"ח] בא יב, לט ה."],["469","4","<b>טוב טעם ודעת למדני</b>: תהלים קיט, סו."],["470","5","<b>כי באור פניך</b>: סיום תפלת העמידה [בדילוג]."],["471","6","<b>לכו לחמו בלחמי</b>: משלי ט, ה. ראה זח\"א בהשמטות רס, א."],["472","7","<b>שצדיק באמונתו יחי'</b>: חבקוק ב, ד."]]],[2800530051,"חבקוק והעמיד כל התרי\"ג מצות על אחת שהיא האמונה שז\"ש וצדיק באמונתו יחיה וזהו ורעה אמונה כנ\"ל וד\"ל:\n(יב) <b>וזהו</b> שאומרים בהגדה הא לחמא עניא די אכלו אבהתנא כו' פי' הא היינו ה\"א תתאה דבחי' המל' כאשר היא בבחי' נקוד' תחת היסוד כו' נק' לחמא עניא די ד' י' (כמ\"ש בכונות<sup data-n=\"473\">8</sup> ) וביאור הענין הנה ידוע שבחי' המל' עומדת תחת היסוד<sup data-n=\"474\">9</sup> בקו האמצעי שהוא דתי\"ם ולפעמים אינה רק כמו נקודה תח\"י וזהו כמו חירק<sup data-n=\"475\">10</sup> שתחת האו' כאשר היא בתכלית הקטנות וכמ\"ש בזהר ע\"פ שחורה אני<sup data-n=\"476\">11</sup> דאזעירת גרמה ואתעבידת נקודה חדא עד שגבורי כח בהעלאות מ\"ן אהדרו לה להיות בציור ה\"א כמלקדמין שזהו בנין המל' בע\"ס<sup data-n=\"477\">12</sup> בבחי' הדיבור דהיינו ה\"א תתאה דשם הוי' כידוע ולפעמים מלבשת לד' בחי' דז\"א שהוא תנהי\"ם וזהו ד' רבתי דאחד<sup data-n=\"478\">13</sup> כו' ולפעמים עולה ומתייחדת בפב\"פ עד שהן שוין בקומתן<sup data-n=\"479\">14</sup> כו' ועוד תעלה המל'<sup data-n=\"480\">15</sup> יותר לעלות בראש הכל והוא בבחי' הכתר שע\"ג ג' הקוין חח\"ן ובג\"ה ודתי\"ם כו' לפי שהמל' מעמדה תחת קו האמצעי דת\"י ונק' בריח התיכון שמבריח מן קצה העליון דכתר לקצה התחתון דמל' וידוע דנעוץ סופן בתחלתן<sup data-n=\"481\">16</sup> ותחלתן בסופן דהרי אמר כתר מלכות דאיהו כ\"ע<sup data-n=\"482\">17</sup> וראייה לזה מעליית המל' בנעילה דיו\"כ בפנימית ע\"י<sup data-n=\"483\">18</sup> כידוע וזהו כמו החולם<sup data-n=\"484\">19</sup> שע\"ג האות (והיינו בבחי' או\"ח שהמל' נק' כתר<sup data-n=\"485\">20</sup> כו' כמ\"ש במ\"א) אך כאשר המל' בתכלית הקטנות אינה רק בבחי' נקודה א' תח\"י וזהו כמ\"ש ותבך ותפול לפני רגליו<sup data-n=\"486\">21</sup> כידוע וגם כאן במ\"ש הא לחמא עניא הכוונה על היות המל' שהוא שרש כנ\"י בתכלית הקטנות להיות רק בבחי' נקודה תח\"י שזהו מ\"ש ד' יו\"ד ולא יו\"ד במילוי אלא י' שהוא נקודה תח\"י (והד' הוא בבחי' ד' בחי' דז\"א או שהד' הוא במל' והי' עטרת יסוד ז\"א) ואמנם דוקא בחי' קטנות זאת היא המביאה לבחי' גדלות ועלי' גדולה דמל' בכתר דרך בריח התיכון דת\"י להיות בנקודה דחולם ע\"ג האות (וכמו בתשר\"י שאמר ע\"ז ותנח התבה<sup data-n=\"487\">22</sup> בחדש השביעי כו' על הרי אררט מדו' שבכתר<sup data-n=\"488\">23</sup> כו') וזהו ותרם כראם קרני<sup data-n=\"489\">24</sup> שישראל נמשלים כראם שכאשר קם משכיבתו בארץ הגבהתו בלתי הדרגה שנגבה מאד נעלה וז\"ש אל מוציאו ממצרים<sup data-n=\"490\">25</sup> דוקא כתועפות ראם לו שמעומק השפלות באו לתכלית העילוי במ\"ת ובמסעות שבמדבר עם הארון וגלוי שכינה בעמוד אש וענן כו' כראם זה שבשכיבתו מושפל ביותר ובקומו יגבה מאד וכך אמרז\"ל בישראל כשהן עולין<sup data-n=\"491\">26</sup> עולין עד למרום וכשיורדין יורדין עד לעפר ורמזו בזה על בחי' נקודה דמל' כאשר היא בשפלות כנקודה תח\"י כמו בגלות מצרים וכל גלות היינו שיורדים עד לעפר וכמ\"ש רישא שכיבת לעפרא<sup data-n=\"492\">27</sup> כו' ומקים מעפר דל שהוא המל'<sup data-n=\"493\">28</sup> היא בלתי הדרגה שעולה עד פנימיות הכתר וזהו כתועפות ראם לו והוא הנק' מרום כמ\"ש שאו מרום עיניכם<sup data-n=\"494\">29</sup> וכמו יעקב משמש במרום<sup data-n=\"495\">30</sup> כו' וזהו שגזרו אומר דכל<sup data-n=\"496\">31</sup>",[["473","8","<b>כמ\"ש בכונות</b>: ראה פע\"ח (שחה\"מ) שכ\"א פ\"ז בפיסקא הא לחמא. סידור האריז\"ל ומ\"ח שם."],["474","9","<b>המל' עומדת תחת היסוד</b>: ראה פרדס (שער סדר עמידתן) ש\"ו פ\"א. פ\"ב. קונטרס בד קודש [נדפסה גם באגרות כ\"ק אדה\"א ס\"ע רצ ואילך. ע' רצו]."],["475","10","<b>המל'. . כמו חיריק</b>: ראה מאמרי אדה\"א בראשית ע' תקיט. וש\"נ."],["476","11","<b>בזהר ע\"פ שחורה אני</b>: שה\"ש א, ה. ראה זהר בלק קצא, א. הנסמן במאמרי אדה\"א שמות ח\"ב ע' תמז. לקמן קמב, א. קמג, א."],["477","12","<b>בנין המל' בע\"ס</b>: ראה לקמן קצה, ג ואילך."],["478","13","<b>ד' רבתי דאחד</b>: ראה מאמרי אדה\"א דברים ח\"א ע' רפג. וש\"נ. לקמן קמב, א."],["479","14","<b>שוין בקומתן</b>: ראה ע\"ח (שער מיעוט הירח) של\"ו פ\"א. פ\"ב."],["480","15","<b>תעלה המל'</b>: ראה ע\"ח (שער א\"א) שי\"ג פ\"ב (סוף מ\"ק)."],["481","16","<b>דנעוץ סופן בתחלתן</b>: ראה ס\"י פ\"א מ\"ז."],["482","17","<b>כתר מל' איהו כ\"ע</b>: ת\"ז בהקדמה (יז, א). ראה מאמרי אדה\"א במדבר ח\"ב ע' תרכד. דברים ח\"א ע' רמא. ח\"ד ע' א'רצז ובהנסמן בהנ\"ל."],["483","18","<b>מעליית המל'. . בפנימית ע\"י</b>: ראה גם לקמן קמג, ב ובהנסמן במ\"מ לשם."],["484","19","<b>המל'. . כמו החולם</b>: ראה מאמרי אדה\"א בראשית ע' תקיט. וש\"נ."],["485","20","<b>או\"ח שהמל' נק' כתר</b>: ראה מאמרי אדה\"א שבהערה (דלעיל) כתר מל'."],["486","21","<b>ותבך ותפול לפני רגליו</b>: אסתר ח, ג [בהיפך הסדר ? ראה הנסמן במאמרי אדה\"א דברים ח\"ב ע' תרסז. שע\"ת ח\"א לג, ג]. ראה מאמרי אדה\"ז על ענינים ע' ריג."],["487","22","<b>בתשר\"י. . ותנח התבה</b>: נח ח, ד. ראה גם לקמן קכז, ב ובהנסמן במ\"מ לשם."],["488","23","<b>הרי אררט מדו' שבכתר</b>: ראה לקמן קה, א. סה\"מ תקס\"ז ע' קסט. מאמרי אדה\"א ויקרא ח\"א ע' שצה. וש\"נ. דברים ח\"ב ע' תרסה. ח\"ג ע' תתקצח."],["489","24","<b>ותרם כראם קרני</b>: תהלים צב, יא. ראה מאמרי אדה\"א דברים ח\"א ע' פט. וש\"נ. שמות ח\"ב ע' תסט ובהערה אל."],["490","25","<b>אל מוציאו ממצרים</b>: בלק כד, ח."],["491","26","<b>כשהן עולין</b>: ראה מגילה טז, א."],["492","27","<b>רישא שכיבת לעפרא</b>: ראה זהר במדבר קיט, ב. הנסמן במאמרי אדה\"א דברים ח\"א ע' יד."],["493","28","<b>ומקים מעפר דל. . מל'</b>: שמו\"א ב, ח. ראה פע\"ח (שער הלולב) שכ\"ט פ\"ג [לר\"י מערבי ד\"ה וזהו פירוש]. לקמן מד, א. צט, ב. מאמרי אדה\"א בראשית ע' תכו. וש\"נ."],["494","29","<b>שאו מרום עיניכם</b>: ישעי' מ, כו."],["495","30","<b>יעקב משמש במרום</b>: נסמן לקמן קלד, א."],["496","31","<b>דכל שאינו בהסתר פנים</b>: חגיגה ה, סע\"א. וראה גם לקמן לא, א."]]],[2800530052,"שאינו בהסתר פנים בגלות אינו מהם דהסתר זה בשפלות עצומה מעלה לתכלית העילוי וראייה מן הלבנה בפגימתה ובמילוא' שתמיד עולה ויורדת וחוזרת ועולה כך ישראל יורדין ועולין כנ\"ל בבחי' המל' וד\"ל:\n<b>ולהבין</b> ביאור הדברים מהו בחי' הנקוד' שתח\"י שעי\"ז דוקא תעלה לבחי' הכתר וכמ\"ש גפן ממצרים תסיע<sup data-n=\"497\">1</sup> כזמורה קטנה והגדילה למעלה עד שכיסו הרים צילה<sup data-n=\"498\">2</sup> שזהו למעלה מן האבות שנק' הרים<sup data-n=\"499\">3</sup> שהן שרש ג' קוין היינו חג\"ת דכתר<sup data-n=\"500\">4</sup> בכלל ובאמת יש להפלא בזה איך יש ביכולת המל' שעומדת תח\"י בקו האמצעי לעלות למעלה מהקוין אחר שמקבלת מג' הקוין דוקא כידוע שכל התכללות הג' קוין הכל הולכים ונמשכים ביסוד למל' כמ\"ש יקוו המים<sup data-n=\"501\">5</sup> אל מקום אחד כו' וכמו כל הנחלים הולכים אל הים שהוא המל'<sup data-n=\"502\">6</sup> ואיך יעלה המקבל למעלה מן המשפיע וכמ\"כ בענין כנ\"י שמקבלים מן האבות שהן השרשים שלהם באצילות בחג\"ת דז\"א עד חג\"ת דע\"י וא\"א איך יעלו למעלה מהם שהרי אמר כסו הרים צילה כו' ואם מצד שהיה בהם האמונה החזקה שהוא הביטול שלמעלה מן הטעם בזה נתעלו במ\"ת למעלה מן האבות בקבלת תו\"מ הרי האמונה עצמה אינה אלא ירושה מאבות<sup data-n=\"503\">7</sup> דוקא אך הנה יש להבין תחלה עיקר ענין הג' קוין ואשר יש יתרון בקו האמצעי דת\"י שעל ידו תעלה המל' בכתר כנ\"ל דהנה ידוע ע\"פ אלקי אבי אברהם<sup data-n=\"504\">8</sup> ופחד יצחק היה לי שזהו ענין ג' הקוין האצילות למעל' כו' דהיינו חח\"ן מימין הוא מ\"ש אלקי אבי אברהם דאב הוא בבחי' החכמה<sup data-n=\"505\">9</sup> שנקרא ראשית הקו הימין ומקור החכמה כמו שהיא מאין כו' נקרא א\"ב ר\"ם שרם ונבדל מבחי' גלוי יש ונקרא שכל הנעלם מכל רעיון<sup data-n=\"506\">11</sup> שכל מופלא<sup data-n=\"507\">12</sup> כו' (כמ\"ש במ\"א בענין ויאמר אל אברם לך לך<sup data-n=\"508\">10</sup> כו') וחסד ענף החכמה<sup data-n=\"509\">13</sup> הוא אה\"ר שנקרא אברהם אוהבי רחימא דמלכא<sup data-n=\"510\">14</sup> ושרשו במ\"ה דאבא נקרא אבר מ\"ה<sup data-n=\"511\">15</sup> וכן בהברא\"ם אותיות אברהם<sup data-n=\"512\">16</sup> כי נוסף הה\"א שהוא מקור החסדים דאבא ע\"כ זה הי' אחר שנעשה אב המון גוים<sup data-n=\"513\">17</sup> כו' וזהו אלקי אבי אברהם דהיינו שרש הקו הימין חח\"ן כו' ופחד יצחק הוא קו השמאל בג\"ה כמ\"ש אני בינה לי גבורה דמשמעו מגבורה העליונה דכתר<sup data-n=\"514\">18</sup> ומשמעו לי גבורה דלמטה הימנה דבינה מינה דינין מתערין<sup data-n=\"515\">19</sup> וזהו פחד יצחק ביראה שנמשך מבינה ושניהם היו לו שנכללו בקו האמצעי דיעקב שנקרא בריח התיכון<sup data-n=\"516\">20</sup> והוא בחי' הרחמים<sup data-n=\"517\">21</sup> שכלול משניהם יחד וכתיב יעקב אשר פדה את אברהם<sup data-n=\"518\">22</sup> וג' אלה נמשכו לכנ\"י שהוא המל'<sup data-n=\"519\">23</sup> ע\"י קו אמצעי זה דת\"י שהדעת והרחמים מתאחדים שכל מי שיש בו דעה<sup data-n=\"520\">24</sup> יותר יותר ירחם וזהו משה שהוא הדעת<sup data-n=\"521\">25</sup> מלגיו יעקב שהוא הרחמים מלבר<sup data-n=\"522\">26</sup> כו' כמ\"ש במ\"א וע\"כ אמר דאברהם אבי חח\"ן ופחד יצחק בג\"ה היה לי שנכללו במדת הרחמים ובנש\"י היינו שנמשך בהם כמו טבע בנפשם באה\"ר המוסתרת דאברהם אוהבי בעצם ירושה ממנו ממש ונטבע בנפשם פחד יצחק שהוא יראת אלקים ויראת חטא בכאו\"א בטבעיות תולדתו רק שע\"י הבחירה יוכל לשנות מהיפוך להיפוך כו' ומדת הרחמים שהוטבע בנפש ישראלי שיעורר",[["497","1","<b>גפן ממצרים תסיע</b>: תהלים פ, ט."],["498","2","<b>שכיסו הרים צלה</b>: תהלים שם, יא."],["499","3","<b>האבות שנק' הרים</b>: ראה ר\"ה יא, א. מאמרי אדה\"א שמות ח\"ב ע' תקסח. ויקרא ח\"א ע' קיז. דברים ח\"א ע' נה. ח\"ב ע' תרסד ובהנסמן בהנ\"ל. לקמן צז, א. קה, א."],["500","4","<b>האבות. . חג\"ת דכתר</b>: ראה מאו\"א מערכת אבות סכ\"ז (ע\"ח (שער אנ\"ך) שי\"ט פ\"ג). מאמרי אדה\"א בראשית ע' רמא. תו\"ח לך פה, ב ובהערה 11."],["501","5","<b>יקוו המים</b>: בראשית א, ט [בדילוג]."],["502","6","<b>כל הנחלים. . הים שהוא המל'</b>: קהלת א, ז. ראה זהר בהעלותך קנ, ב. מאמרי אדה\"א שמות ח\"ב ע' תסג. ויקרא ח\"א ע' שצז ובהנסמן בהנ\"ל."],["503","7","<b>האמונה. . ירושה מאבות</b>: נסמן לעיל ו, א."],["504","8","<b>אלקי אבי אברהם</b>: ויצא לא, מב [בדילוג. וכ\"ה בהמובא בסמוך]. ראה מאמרי אדה\"א ויקרא ח\"ב ע' תשסג. וש\"נ. שע\"ת ח\"א ס, ב. תו\"ח בראשית מא, ד ובהערה 43. לקמן עג, א."],["505","9","<b>דאב. . החכמה</b>: ראה תניא פ\"ג. הנסמן לעיל ח, ב."],["506","11","<b>שכל הנעלם מכל רעיון</b>: נסמן לקמן קכז, ב."],["507","12","<b>שכל מופלא</b>: ראה הקדמת הראב\"ד לס\"י ?הנתיב הא'\". תו\"ח לך פ, א הערה 8."],["508","10","<b>א\"ב ר\"ם. . לך לך</b>: ראה תו\"א ר\"פ לך. אוה\"ת שם כרך ו ע' תתרעב."],["509","13","<b>וחסד ענף החכמה</b>: נסמן לקמן קכד, ב."],["510","14","<b>אברהם אוהבי רחימא דמלכא</b>: ישעי' מא, ח. זהר ואתחנן רסב, ב. מאמרי אדה\"א שמות ח\"ב ע' שמג. וש\"נ."],["511","15","<b>אברהם. . אבר מ\"ה</b>: ראה זהר בהקדמה ד, רע\"א."],["512","16","<b>בהברא\"ם אותיות אברהם</b>: ראה ב\"ר פי\"ב, ט. תנחומא באבער בראשית טז. מדרש תהלים קד, יח (עה\"פ הרים). לקח טוב בראשית ב, ד. זהר לך פו, ב."],["513","17","<b>אם המון גוים</b>: לך יז, ה."],["514","18","<b>אני בינה לי גבורה. . דכתר</b>: משלי ח, יד. ראה גם לקמן קכז, סע\"ב."],["515","19","<b>דבינה מינה דינין מתערין</b>: נסמן לקמן קכד, ב."],["516","20","<b>דיעקב שנקרא בריח התיכון</b>: נסמן לקמן קלג, ב."],["517","21","<b>דיעקב. . הרחמים</b>: נסמן לקמן קכה, א."],["518","22","<b>יעקב. . אברהם</b>: ישעי' כט, כב."],["519","23","<b>לכנ\"י שהוא המל'</b>: ראה זהר בלק קצז, א."],["520","24","<b>שכל מי שיש בו דיעה</b>: ראה סה\"מ תקס\"ג ח\"ב ס\"ע תצז (נוסח א') ואילך. שם ע' תצח (נוסח ב') ואילך. לקמן קלד, א. מאמרי אדה\"א ויקרא ח\"א ע' כא. במדבר ח\"א ע' כ. דברים ח\"א ע' שיא. ח\"ב ע' תלד ואילך."],["521","25","<b>משה שהוא הדעת</b>: ראה תניא פמ\"ב. מאמרי אדה\"א בראשית ע' ר. וש\"נ."],["522","26","<b>משה. . מלגיו יעקב. . מלבר</b>: ראה ת\"ז תי\"ג (כט, א). סה\"מ תקס\"ג שם. מאמרי אדה\"א במדבר ח\"א ע' יז ואילך."]]],[2800530053,"ר\"ר ע\"ע לבלתי ידח שזהו מצד הדעת והאמונה שיעלה מעלה מעלה והוא למעלה מהתחלקות הקוין דאוי\"ר וזהו בריח התיכון דת\"י שמבריח לקצה העליון דפנימית הכתר כנ\"ל והיינו כמו בזמן גלות מצרים שמררו את חייהם ותעל שועתם<sup data-n=\"523\">27</sup> כו' שנתעוררו ר\"ר העליונים שבפנימי' הכתר כו' ולא הי' זה רק ע\"י האמונה שבנפשם שעולה למעלה מן הדעת דקו אמצעי כו' והוא בחי' נקודה תח\"י שהאמונה אינה רק ביטול העצמות מכל וכל לדבק במהו\"ע<sup data-n=\"524\">28</sup> שלמעלה מהתפעלות רצון ושכל כנ\"ל כנקודה שאין לה התפשטות וזהו הא לחמא עניא הנ\"ל שמזה באו למעלה מן האבות שהן ג' קוין דאצילות כמ\"ש כסו הרים צילה ואע\"פ שזה אמת שהמל' מקבלת מהכל כנ\"ל כמו דאיהו אמת שהוא המשפיע ואיהי אמונה בחי' מקבל וכמ\"ש ואנכי נטעתיך שורק<sup data-n=\"525\">29</sup> כולו זרע אמת וידוע דאמת הוא רת\"ס<sup data-n=\"526\">30</sup> שזהו קו האמצעי דת\"י וחותמו אמת להשפיע במל' ע\"כ נקרא כנ\"י זרע אמת וגם זה אמת שמקבלים בנשמתם מאמיתת מהו\"ע שלמעלה מג' הקוין שהוא אור עצמות א\"ס שבפנימי' הכתר כנ\"ל והיינו דוקא כאשר מתוך שפלות וביטול עצמם באמונה הפשוט' עלו למעלה ברצון העליון בפנימית ועצמיות שלמעלה מן הקוין כו'. וזהו ישראל לסגולתו<sup data-n=\"527\">31</sup> סגול העליון שנעשה מסגול התחתון<sup data-n=\"528\">32</sup> דאמת דקו האמצעי בעליי' המל' בכתר כנ\"ל וכמ\"ש במ\"א באורך על ענין שור\"ק וסגול דנטעתיך שור\"ק ג' נקודות<sup data-n=\"529\">33</sup> זו למטה מזו שמזה דוקא נעשה זרע אמת במ\"ת כו' וד\"ל:\n<b>ולהבין</b> זה בתוס' ביאור הנה יש להקדים ענין א' והוא מה שאמר על ג' דברים<sup data-n=\"530\">34</sup> העולם עומד על התורה ועבודה וגמ\"ח שהן ג\"כ בחי' ג' קוין הנ\"ל באבות תורה הוא קו האמצעי דת\"י שכלולה מחו\"ג כמ\"ש מימינו אש<sup data-n=\"531\">35</sup> כו' וקו ימין הוא גמ\"ח וקו שמאל הוא הקרבנות שנק' עבודה (והקדים עבודה לגמ\"ח שזהו עכשיו תפלה במקום קרבן<sup data-n=\"532\">36</sup> שזהו כסדרן תורה ותפלה וצדקה והל\"ל גמילות חסדים ועבודה דקו ימין קודם אך זהו מלמעלה למטה מן המשפיע אל המקבל ואשר הקדים תורה שהיא קו האמצעי מפני שכולל שניהם בין מלמעלה למטה בין מלמטה למעלה שכל העליות וירידות ע\"י דוקא) אבל מלמטה למעלה שהוא בעליית המל' שז\"ש העולם עומד הקדים עבודה שהוא התפלה קודם לגמ\"ח אע\"פ שנא' אני בצדק אחזה פניך<sup data-n=\"533\">37</sup> ורבא יהיב פרוטה לעני והדר מצלי<sup data-n=\"534\">38</sup> היינו שיהי' הכנה להעלאת מ\"ן דתפלה כו' אבל מ\"ש העולם עומד היינו שעומד ומתקיים כמו על ג' עמודים או משמעו שמעמידים אותו מלמעלה ע\"י ג' אלה דוקא וז\"ש אל יתהלל<sup data-n=\"535\">39</sup> חכם בחכמתו שהוא קו ימין חח\"ן וגבור בגבורתו קו שמאל בג\"ה ועשיר בעשרו קו אמצעי דת\"י<sup data-n=\"536\">40</sup> כידוע שהעושר הוא בדעת<sup data-n=\"537\">41</sup> והיינו ג\"כ תורה ועבודה וגמ\"ח כ\"א בזאת יתהלל כו' השכל כו' לעשות חסד ומשפט וצדקה בארץ<sup data-n=\"538\">42</sup> דוקא שהוא ג\"כ ג' קוין חסד קו ימין ומשפט קו השמאל וצדקה הוא הרחמים קו אמצעי ובארץ דוקא שע\"ז העול' העליון ועול' התחתון עומ' לפי שהכל הולך אחר המעמי'<sup data-n=\"539\">43</sup> והן חסד ומשפט וצדקה בארץ דוקא כו' וד\"ל ויש להבין דמזה משמע דג' דברים הן שהעול' עומד וכוללי' כל המצו' בגמ\"ח נכלל כל רמ\"ח מ\"ע שהן בחי' ה\"ח<sup data-n=\"540\">44</sup> ובעבוד' דקרבנו'",[["523","27","<b>ותעל שועתם</b>: שמות ב, כג."],["524","28","<b>במהו\"ע</b>: נסמן לעיל ב, א."],["525","29","<b>ואנכי נטעתיך שורק</b>: ירמי' ב, כא."],["526","30","<b>דאמת הוא רת\"ס</b>: נסמן לקמן קלד, א."],["527","31","<b>ישראל לסגולתו</b>: תהלים קלה, ד."],["528","32","<b>סגול העליון. . התחתון</b>: ראה מאמרי אדה\"א דברים ח\"א ע' יט. וש\"נ. תו\"ח וישלח קצב, ג ובהערה 48."],["529","33","<b>דנטעתיך שור\"ק ג' נקודות</b>: ראה דרך חיים צו, ג ואילך."],["530","34","<b>על ג' דברים</b>: ראה אבות פ\"א, מ\"ב."],["531","35","<b>מימינו אש</b>: ברכה לג, ב. ראה שהיחוה\"א פ\"ה."],["532","36","<b>תפלה במקום קרבן</b>: נסמן לעיל ג, ב."],["533","37","<b>אני בצדק אחזה פניך</b>: תהלים יז, טו."],["534","38","<b>ורבא. . והדר מצלי</b>: כ\"ה גם במאמרי אדה\"א ויקרא ח\"ב ע' תשא. וש\"נ. ראה ב\"ב י, א."],["535","39","<b>אל יתהלל</b>: ירמי' ט, כב [ושם: ואל יתהלל הגבור. . אל יתהלל עשיר]."],["536","40","<b>חכם. . חח\"ן. . דת\"י</b>: ראה גם לקמן לה, א."],["537","41","<b>שהעושר הוא בדעת</b>: ראה כתובות סח, א. ביאוה\"ז תשא נד, ג. מאמרי אדה\"ז על פרשיות התורה ח\"ב ריש ע' תרטו."],["538","42","<b>לעשות. . בארץ</b>: ירמי' שם, כג [ושם: עושה ? ראה לקמן לה, א. הנסמן במאמרי אדה\"א קונטרסים ע' תא]."],["539","43","<b>שהכל הולך אחר המעמי'</b>: לשון הגמ' שבת טו, ב."],["540","44","<b>רמ\"ח. . ה\"ח. . שס\"ה. ה\"ג</b>: מכות כג, סע\"ב. ראה קו\"א לתניא (להבין מ\"ש בפע\"ח) קנח, ב. הנסמן במאמרי אדה\"א נ\"ך ע' רלה."]]],[2800530054,"שהוא (התפלה עכשיו) נכלל כל שס\"ה ל\"ת בחי' ה\"ג ותורה כולל שניהם דמ\"ע ול\"ת הן חו\"ג דתורה והיינו דת\"ת כנגד כולם<sup data-n=\"541\">1</sup> כו' והרי אמרו דתרי\"ג מצות העמידן חבקוק על אחת<sup data-n=\"542\">2</sup> שהיא האמונה (והוא עמוד א' וצדיק שמו שהוא יסוד עולם<sup data-n=\"543\">3</sup> ) והוא מ\"ש וצדיק באמונתו יחי'<sup data-n=\"544\">4</sup> כנ\"ל הרי נכללו ג' אלה דתור' ועבודה וגמ\"ח באמונה ולמה אמ' על ג' דברים דוקא אך הנה בזה יובן ההפרש שבין יצ\"מ למ\"ת דביצ\"מ באמונה לבד שכוללת ומעמדת כל התרי\"ג מצות ובמ\"ת קיבלו בדרך ג' קוין כי מימינו אש דת למו שנתנה בימין ובאש ובממוצע שהוא הקול שמורכב מאמ\"ר<sup data-n=\"545\">5</sup> והן מ\"ע ה\"ח הכלולים באנכי ושס\"ה ל\"ת הכלולים בלא יהיה לך<sup data-n=\"546\">6</sup> ומפי הגבורה<sup data-n=\"547\">7</sup> עצמו שמעו שהוא קול מורכב מחו\"ג כו' ועל כל דבור<sup data-n=\"548\">8</sup> כו' הרי נמשך בהן מג' הקוין העליונים שלמטה הוא ג' דברי' שהעול' עומד תורה ועבוד' וגמ\"ח כנ\"ל והכל א' ממש והא בהא תליא דמשום שיצ\"מ היה באמונה דוקא מזה באו לכלל בית קיבול לקבל ג' קוין דתורה כו' ולעלות למעלה מהקוין והוא בבחי' אנכי מי שאנכי<sup data-n=\"549\">9</sup> דלמת\"ב כלל שלמעלה גם מן התו\"מ כמ\"ש אם צדקת<sup data-n=\"550\">10</sup> כו' וד\"ל:\n(יג) <b>ויובן</b> זה בהקדים תחלה ענין א' והוא במה שאנו מוצאי' בכלל המצו' שיש בהן ב' מיני מצו'<sup data-n=\"551\">11</sup> הא' מצות התלויי' באיזה טעם ודעת כמו כיבוד אב ושבת וכה\"ג וגם מצות שאין טעמן במפורש מ\"מ מובן בהם איזה טעם וכונה ע\"ד הסוד עכ\"פ שמובן לכל יודעים בסוד ה' כו' כמו טעם מצות הקרבנות שהוא להעלות<sup data-n=\"552\">12</sup> לה' לריח ניחוח מבחי' בירורים דרפ\"ח כו' בעלות הקרבן ע\"ג המזבח באש של מעל' ובכלל זה יש כמה מצות שעיקר הטעם והסוד בהם הוא<sup data-n=\"553\">14</sup> רק בחינת העלאה ובירור דרפ\"ח כו' וכמ\"כ יש הרבה מצות שעיקר הטעם והסוד בהם הוא רק בחי' החסדים שהוא גלוי אור המשכות<sup data-n=\"554\">13</sup> אלקות מלמעלה למטה כמו במצות תפילין וציצית וכה\"ג בצדקה<sup data-n=\"555\">15</sup> ות\"ת<sup data-n=\"556\">16</sup> וכן מצות סוכה ולולב (והשופר הוא העלאה<sup data-n=\"557\">17</sup> ) וכן בכל המצות התלויות בארץ כתרומות ומעשרות וכה\"ג כלולים במדריגות דאו\"י ואו\"ח שהוא העלאה או המשכה יש מהן רבים שהן בבחי' העלאות והרבה מהן שהן בבחי' המשכות וכמ\"כ במל\"ת הכל יש בהן סוד וטעם למעלה בב' אופנים אלו דרך כלל וכמה מצות יש שאין בזה מב' אלה כלל רק סוד וטעם אחר שלא מענין העלאה והמשכ' כלל כמובן בכמה מצות אך לכולן או רובם יש בהם טעם וסוד למעלה יהיה מה שיהיה ונק' טעם כמוס לרצון העליון שבמצות כו' וע\"ז אמ' במדרש ע\"פ ישקני<sup data-n=\"558\">18</sup> מנשיקות פיהו דלע\"ל יתגלו טעמי מצות שהן טעמים העליונים שנק' נסתרות לה' אלקינו<sup data-n=\"559\">19</sup> ויבאו בגלוי לע\"ל ואפס קצתו נגלה במ\"ת לנש\"י וע\"כ על כל דיבור כו' וקצת מזה מלובש בטעמים ונגינות כו' אך הנה יש כמה מצות רבות שאין בהם טעם כלל גם לא טעם כמוס בסוד ה' למעלה והן הנק' חוקים כמו מצות פרה אדומה שאמ' עליה זאת חקת התורה<sup data-n=\"560\">20</sup> כחוקה זו שאין בה טעם כלל רק גזירת מלך לבד ועליה אמר שלמה אחכמה והיא רחוקה<sup data-n=\"561\">21</sup> כו' שהיא למעלה מכל טעם ורצון אלא הוא בבחי' רצון פשוט ועצמי שנבדל ומרומם מלבא בבחי' טעם וסוד לגמרי לא בענין הבירורים דרפ\"ח ולא ענין טעם וסוד אחר אלא הוא באמת בלא<sup data-n=\"562\">22</sup>",[["541","1","<b>דת\"ת כנגד כולם</b>: פאה רפ\"א."],["542","2","<b>דתרי\"ג מצות. . אחת</b>: מכות כג, סע\"ב ואילך."],["543","3","<b>וצדיק. . יסוד עולם</b>: משלי י, כה."],["544","4","<b>וצדיק באמונתו יחי'</b>: חבקוק ב, ד."],["545","5","<b>הקול שמורכב מאמ\"ר</b>: נסמן לקמן קלד, ב."],["546","6","<b>מ\"ע. . באנכי. . ושס\"ה. . בלא יהיה לך</b>: ראה זח\"ב (יתרו) צא, א. (תוספות) רעו, א. של\"ה ר\"פ יתרו שטו, ב. תניא רפ\"כ."],["547","7","<b>באנכי. . בלא יהיה. . ומפי הגבורה</b>: מכות כד, א. ראה מאמרי אדה\"א נ\"ך ע' תקכ."],["548","8","<b>ועל כל דבור</b>: שבת פח, ב."],["549","9","<b>אנכי מי שאנכי</b>: נסמן לעיל יג, א."],["550","10","<b>אם צדקת</b>: איוב לה, ז."],["551","11","<b>ב' מיני מצו'</b>: ראה מאמרי אדה\"ז על פרשיות התורה ח\"ב כאן ע' תקנב."],["552","12","<b>הקרבנות שהוא להעלות</b>: ראה גם מאמרי אדה\"א קונטרסים ע' תקעד."],["553","14","<b>הוא</b>: ניתוסף ע\"פ דפו\"ר."],["554","13","<b>מצות. . העלאה. . המשכות</b>: ראה מאמרי אדה\"א ויקרא ח\"ב ע' תקסט. וש\"נ. תו\"ח בראשית כו, ג ובהערה 27."],["555","15","<b>בצדקה</b>: ראה תו\"א יתרו עא, ב. סה\"מ תקס\"ט ע' קסא."],["556","16","<b>ות\"ת</b>: ראה מאמרי אדה\"א דברים ח\"ד ע' א'תסז."],["557","17","<b>והשופר הוא העלאה</b>: ראה ספר המאמרים תקס\"ט ע' קסא."],["558","18","<b>במדרש ע\"פ ישקני</b>: ראה רש\"י שה\"ש א, ב. לעיל ג, ב הערה ישקני."],["559","19","<b>נסתרות לה' אלקינו</b>: ע\"פ נצבים כט, כח."],["560","20","<b>זאת חוקת התורה</b>: חוקת יט, ב."],["561","21","<b>אחכמה והיא רחוקה</b>: קהלת ז, כג. במד\"ר פי\"ט, ג. ראה סה\"מ תקס\"ה ח\"ב ס\"ע תרעח ואילך וע' תרצא. לקו\"ש (חוקת) כרך ח ע' 124."],["562","22","<b>בלא טעם כלל</b>: ראה במד\"ר שם, ו. לקו\"ש (חוקת) כרך יח ע' 299 ואילך. ע' 301."]]],[2800530055,"טעם כלל עד\"מ מלך שגוזר דבר שאין לו בו טעם כלל גם לעצמו רק חפץ שיקיימו רצונו יהיה איך שיהיה שנק' חוקה ונק' רצון הפשוט שבלתי מוגבל כלל בטעמי' והוא אשר כולל כמה מצות רבות שלא נמצא בהם טעם וסוד כלל וכלל שנק' חוקים כמ\"ש העדות והחוקים<sup data-n=\"563\">23</sup> כו' ואמ' בכמה דוכתי מצותי וחוקותי<sup data-n=\"564\">24</sup> אם בחקתי תלכו<sup data-n=\"565\">25</sup> ומצותי תשמרו כו' וכידוע וד\"ל:\n<b>והנה</b> בשעת מ\"ת שקבלו עליהם לשמור ולעשות כל אשר יצוה ה' עליהם ואמ' כל אשר דבר ה' נעשה<sup data-n=\"566\">26</sup> כו' ודאי היה בזה קבלת הלב גם לאותן המצות שהן למעלה מן הטעם ודעת רק חוקה וגזירו' מלך לבד מאחר שאמרו הכל נעשה גם שלא שמעו עדיין מה שיצוה א\"כ ה\"ז בחי' ביטול רצון לגמרי מכל וכל לבטל עצמם מפני רצונו שבלא טעם שזה א\"א כ\"א שהיה בהם בחי' ביטול רצון ג\"כ בזה האופן שהוא למעלה מן הטעם ודעת לגמרי לפי שזה הרצון הפשוט העליון שבמצות שנק' חוקים שלמעלה מן הטעם וסוד לגמרי כנ\"ל א\"א שיקבלוהו בנפשם כ\"א בהעלאת וביטול עצמי ג\"כ באותו אופן שהוא רצון פשוט עצמי דהיינו ביטול דכל מוה\"ע<sup data-n=\"567\">27</sup> שלמעלה מן הטעם ודעת לגמרי וזהו שהקדימו נעשה לנשמע<sup data-n=\"568\">28</sup> כמ\"ש במ\"א בארוכה וד\"ל אך מאין היה בהם כח הביטול העצמי כזה לקבל בעצמם מבחי' רצון הפשוט העליון שלמעלה לגמרי מכל טעם וסוד ע\"י שאמרו נעשה אין זה רק מאשר הכינו בנפשם ביצ\"מ ע\"י האמונה החזקה שבנפשם ע\"י אכילת מצה בליל א' דפסח שהאמונה ניתוסף בהם ע\"י אכילה זו עד שיצאו במס\"נ שלמעלה מן הטעם ודעת והי' שעמד' לאבותינו כו' כנ\"ל והוא בחי' רצון פשוט ועצמי שעי\"ז יכלו לומר כל אשר דיבר ה' נעשה בביטול רצון פשוט למעלה מן הטעם כדי שיומשך להם החוקים דהיינו רצון העליון הפשוט שלמעלה מטעם וסוד העליון לגמרי כי כל העלא' גורם המשכה<sup data-n=\"569\">29</sup> באותו אופן ומדריגה שהיא כו' ובהיות שיש בכלל מאתי' מנה<sup data-n=\"570\">30</sup> אז ממילא נמשך להן אותן המצות שבאו בטע' וסוד העליון שזהו בהתחלקות קוין דימין ושמאל באנכי ולא יהיה לך (שמתחלק מח\"ס<sup data-n=\"571\">31</sup><sup data-n=\"572\">32</sup> שבכתר שנק' טעם כמוס לרצון<sup data-n=\"573\">33</sup> הפשוט כידוע) והן טעמי המצות שיתגלו לע\"ל כמ\"ש ע\"פ ישקני כו' כנ\"ל וזהו ענין הנ\"ל דבאמונה זו דוקא שיצאו ממצרים זכו לקבלת התור' שיבא להם מלמעל' מן הטעם כמוס (דהוא בחי' ח\"ס<sup data-n=\"574\">34</sup> שנחלק לקוין) כי עלו למעלה בעצמו' ומהות אא\"ס ב\"ה שבפנימית הרצון הפשוט שלמעלה מן הטעם כמוס לרצון כו' דזהו מ\"ש אם צדקת מה תתן לו כו' וממילא נמשך אח\"כ בג' קוין שהן תור' ועבודה וגמ\"ח שהן מצות שיש בהן סוד וטעם העליון בהעלאת מ\"ן שזהו בקו השמאל והמשכות חסדי' בקו הימין והממוצע דקול תורה כו' ובכולן יש בהם טעמי' וסודות העליונים שנק' טעמי מצות וד\"ל וזהו ההפרש בין יצ\"מ דפסח לחג השבועות ובאמת הן א' ממש והא בהא תליא דמשום שיצאו באמונ' באו לכלל טעמי מצות כנ\"ל ונמצא דשניהם אמת דצדיק באמונתו יחי' הוא רק עמוד א' שהיא האמונה ועל ידה דוקא נמשך ג' דברים שהן תור' ועבודה וגמ\"ח שיומשך בבחי' טעם עכ\"פ למעלה ויש מהן שנגלה למטה כמ\"ש הנסתרות נסתרות לגמרי והנגלות לנו מן הנסתרות למטה אך אין עלינו רק לשמור ולעשות כמ\"ד מצות א\"צ כוונה<sup data-n=\"575\">35</sup> אלא רצון פשוט שהוא",[["563","23","<b>העדות והחוקים</b>: ואתחנן ד, מה. ו, כ."],["564","24","<b>מצותי וחוקותי</b>: מלכים-א יא, לד."],["565","25","<b>אם בחקתי תלכו</b>: בחוקותי כו, ג."],["566","26","<b>כל אשר דבר ה' נעשה</b>: יתרו יט, ח. משפטים כד, ז."],["567","27","<b>מוה\"ע</b>: נסמן לעיל ב, א."],["568","28","<b>שהקדימו נעשה לנשמע</b>: שבת פח, א. ראה סה\"מ תקס\"ב ח\"א ע' רח."],["569","29","<b>כל העלא' גורם המשכה</b>: ראה סידור ערב שבת קסג, ד. מאמרי אדה\"א קונטרסים ע' שעט [ושם: הכלל הידוע]. הנחות תקע\"ז ע' קצה. תו\"ח וישלח קצד, ב ובהערה 35."],["570","30","<b>שיש בכלל מאתי' מנה</b>: ב\"ק עד, א."],["571","31","<b>בהתחלקות קוין. . מח\"ס</b>: ראה תו\"ח וירא קב, א. ד\"ה דור לדור מכ\"ק אדה\"א [קה\"ת תשנ\"ב ע' 12]."],["572","32","<b>מח\"ס</b>: כ\"ה בדפו\"ר. ובמהדורת לעמבערג: מא\"ס."],["573","33","<b>מח\"ס. . טעם כמוס לרצון</b>: ראה לקו\"ת שלח מט, ג. הנסמן במאמרי אדה\"א דברים ח\"ד ע' א'שצב."],["574","34","<b>ח\"ס</b>: כ\"ה בדפו\"ר. ובמהדורת לעמבערג: א\"ס."],["575","35","<b>מצות א\"צ כוונה</b>: נסמן לעיל ה, א."]]],[2800530056,"האמונה וד\"ל. ובכל הנ\"ל יובן מ\"ש בשתי הלחם דשבועות חמץ תאפינה<sup data-n=\"576\">1</sup> כו' חמץ דוקא דהנה שתי הלחם הן תושב\"כ ותושבע\"פ<sup data-n=\"577\">2</sup> שהוא לחם שיש בו טעם דוק' והן טעמי תור' בטוב טו\"ד כו' וזהו שציוה לאפותם בחמץ דוק' וזה נמשך דוק' מן המצה שאין בה טעם אע\"פ שהי' בקטנו' אבל שרשה מעצמו' ומהו' החכ' שלמעל' מן הטעם דהיינו שלא יוכל לבא בגלוי טעם ודע' כלל ובמ\"ת הוא שיצאו הטעמי תורה לידי גלוי מן ההעל' ויובן עד\"מ אב רחמן שחפץ בבנו יחידו שיגיע לאמיתי' המעלה במדריגת עבודת ה' אמנם אם יגלה לו טעמי הדברים עפ\"י שכל וטעם לא יכילנו הבן וגם לא יכוין במעשה רק כפי הוראו' הטעם והדעת שילמדנו ויוכל לנטו' מן הדרך לימין או שמאל ולא יכוין לאמיתת הדבר מצד שהמע' עצמ' יש בה עומק שלא יושג ע\"פ שכל וטע' וראי' שאם לא יעש' רק כפי אופן הטע' לא יכוין אמיתי' המע' כמו שהיא באמ' ע\"כ אין עיקר שלימו' הדב' רק שיצונו בציווי על אופן המע' בלא טעם ושכל כלל רק ע\"פ הציווי שיצונו אז יעש' ודאי כפי הצריך באמת ולא יטה ימין ושמאל מאחר שאין בו טעם שיטעה אותו (דוגמא לדבר בטעמי דינין זה אוסר וזה מתיר כב\"ש וב\"ה שא' מהן אינו הלכה למעשה אמיתית וזה בא מצד שבא הדבר בטעמי' וסברות זה נוטה שכלו כך וזה להיפך כי גם באותו הדבר שקבלו הטעם מרבם זה יטהו לחסד וזה יטהו לדין<sup data-n=\"578\">3</sup> משא\"כ הלכות פסוקות בלא טעם כלל שא\"א לנטות ולטעות כלל ואין בזה מחלוקת כלל ועד\"מ גזירת מלך בלא טעם ופירוש אין לנטות בזה רק כפי המבואר באופן הציווי אבל כאשר בא עם פירוש וטעם זה יפרש כך וזה יפרש כך כו') כמו שיצוה אדם לבנו בגזרת כיבוד אב לטובתו כל הימים שזה תאכל וזה לא תאכל ובדברים אלו דוקא תדבק תמיד ובדברים אחרים פרטי' תרחק ביותר שאלו הדברים יהיו לטובתך וזולתם יהיו לרעתך מאד או שאם תעשה כך וכך ייטיב לך ואם תעשה דבר שאני מזהירך לרחק תרע לך ואע\"פ שאינו אומר לו טעם כלל בכ\"ז וגם הבן אינו רואה בשכלו שזה טוב לו וזה רע לו יאמין באמונה שלימה ולא יטה ימין ושמאל מכל אשר ציוהו אביו שבודאי אמיתית הדבר כן הוא בלי ספק מצד אמונתו זהו יותר טוב משהי' אומר לו אביו שכל וטעם לכל ציווי שזה האופן יהיה לטובתך מטעם זה וזה האופן יהיה לרעתך מטעם זה אע\"פ שלכאורה היה הבן מקבל יותר בכי טוב את הציווי שלו להזהר מכל אשר רע לו כי יודע היט' בטוב טעם למה יהי' לרע לו וכן במעשה הטוב היה שומר בכל לב לעשותו מצד הטעם בטוב זה מ\"מ היה נוטה מן הדרך לימין או שמאל וגם שקיבל בכי טוב אבל לא ישמור יפה אופן המעשה כמו שהיא באמת רק ע\"פ תוקף האמונה שיאמין שבודאי דבר זה אמת לאמיתו בלי ספק וא\"צ רק לשמור אופן הציווי על המעשה לבד שלא יטה מן הדרך לעולם (וכמו עד\"מ הסגולות שיעשו שאינו יודע טעמם כלל רק מאמין שפועל לטוב כשיעשה כך וכך א\"צ רק לשמור אופן מעשה הסגולה וכן הרפואה בסממנים שאינו יודע טעם וחכמת הרפואה כלל א\"צ רק לשמור אופן מעשה הרפואה אבל אם יודע בטעם של הסגולה ורפואה יכול לנטות כי יטה מן האמת ע\"פ טעות השכל כי יש ברפואה כח מה שלא ישיגנו הטעם ונעלם מכל חכם וכה\"ג ועיקר הענין",[["576","1","<b>חמץ תאפינה</b>: אמור כג, יז."],["577","2","<b>שתי הלחם. . ותושבע\"פ</b>: השמטות לזח\"א רס, א."],["578","3","<b>כב\"ש וב\"ה. . לחסד. . לדין</b>: נסמן לקמן קכד, א."]]],[2800530057,"לפי שהמעשה למעלה מן השכל וע\"כ לא יכוין בשכל כפי אמיתית המעשה וראיה ממה שאין שלימות החכמה רק בנסיון<sup data-n=\"579\">4</sup> במעשה הרי גם שמצד השכל הוא בטוב טעם ודעת הישר עיקר בירורו בין טו\"ר אמת או שקר רק בנסיון דוקא וד\"ל) ואמנם אם הבן עשה וקיים כל ציווי אביו הכל באמונה פשוטה בלי חקירת טעם ושכל כלל וכלל הנה אחרי ימים רבים כשהגדיל בשנים ועמד על טוב טעם ודעת שבכל פרטי ציווי אביו אז ישמח נפשו ויגיל מאד ויתחזק במעשה זו יותר ויותר כי אחר האמונה החזקה דוקא שנגלה לו טעמי הדבר לא יהיה זה רק כפי שהוא באמת לאמיתתו בלי נטי' ימין ושמאל כלל ואז הטוב טעם ודעת מוסיפי' אור גדול להורות כפי האמת דוקא והנמשל יובן מכ\"ז בענין פסח ושבועות דאמונה שיצאו בה ממצרים קבלו הדבר לאמיתתו ואע\"פ שלא נודע להם טעם כלל כמצה זו שאין בה טעם כמשל הציווי שבלא טעם כלל כנ\"ל ואח\"כ במ\"ת נתגלו לכנ\"י טעמי תורה בסוד ה' הכמוס למעלה אך לא היו יכולים לקבל תחלה רק היו כל טעמי תורה בהעלם ובקטנות כדי שלא יטו ימין ושמאל והוא מ\"ש לכתך אחרי<sup data-n=\"580\">5</sup> כו' ואז דוקא כשנגלה להם טעמי תורה במ\"ת הועיל לנשמתם שילכו אחרי ה' בתו\"מ בלי נטית ימין ושמאל בתוס' חיזוק כל ימי עולם בכל דור ודור שהכל מקבלים ממה שניתן לכנ\"י במ\"ת וכ\"ז רק מצד הקדם האמונ' ביצ\"מ וזהו שאמר בשתי הלחם דשבועות חמץ דוקא תאפינה שהן טעמי תורה כנ\"ל לפי שאכלו מצה ביום א' דפסח ונזהרו מן החמץ משום דהא בהא תליא וד\"ל:\n(יד) <b>ובכל</b> זה יובן מה שקורין פ' זכור<sup data-n=\"581\">6</sup> לפני חג הפסח דמה ענין מלחמת עמלק שהיה אחר קבלת מקצת תורה במרה<sup data-n=\"582\">7</sup> ליצ\"מ שקדם לזה אך הנה עפ\"י כל הנ\"ל בענין פסח ושבועות יובן מה שנחלקו בגמרא<sup data-n=\"583\">8</sup> אם מצות צריכות כונה או א\"צ כונה וקי\"ל דא\"צ כונה (וע\"פ הסוד היינו כונה שע\"פ הטעם וסוד העליון וגם לפי הפשט דא\"צ כונה לצאת י\"ח או שצריכות כונה לצאת י\"ח הכל עולה לענין א' וד\"ל) הענין הוא דבמצות הנה העיקר הוא הציווי שהוא על עצם המעשה לבד בלא טעם כלל ומה שיש בה טעם וסוד ה' הוא כמו דבר נוסף על העצם וכטפל לגבי העיקר וכמובן ממשל הנ\"ל בציווי האב אל בנו כו' וזהו מ\"ד מצות א\"צ כונה (גם לצאת י\"ח שהמעשה מצד העצם הוא העיקר גם אם אינו מכוין לצאת דאין כונתו כלום כי הרי כטבע בנפשו ע\"י האמונה שהיא סוד הכל וע\"כ מצות מצד עצם המעמיד שלהם שהיא האמונה א\"צ כונה כלל) וזהו ענין מצה דפסח בבחי' אמונה שלמעלה מן הכונה והטעם כלל שהוא העיקר ומעמיד לקיים כל הטעמים וכונות ביחו\"ע שבמצות כו' ומ\"ד מצות צריכות כונה היינו כמו ענין טעמי תורה שנגלה במ\"ת שהן שתי הלחם כנ\"ל וכמ\"ש טוב טעם ודעת למדני<sup data-n=\"584\">9</sup> כו' כל טוב טעם העליון שבפלאות חכמתו חכים ולא בחכמה ידיע'<sup data-n=\"585\">10</sup> למדני בגלוי המושג כמו לע\"ל שיתגלו טעמי מצות כנ\"ל ומפרש הטעם למה ראוי לזה האור הגדול לפי שבמצותיך האמנתי",[["579","4","<b>שלימות החכמה רק בנסיון</b>: ראה מאמרי אדה\"א בראשית ע' נד. וש\"נ. תו\"ח בראשית ג, א ובהערה 1."],["580","5","<b>לכתך אחרי</b>: ירמי' ב, ב."],["581","6","<b>שקורין פ' זכור</b>: ראה להבא להלן מאמרי אדה\"ז על פרשיות התורה ח\"ב כאן ע' תקנג."],["582","7","<b>קבלת מקצת התורה במרה</b>: ראה רש\"י בשלח טו, כה. מכילתא שם. סנהדרין נו, ב. לקו\"ש משפטים כרך כא ע' 142."],["583","8","<b>שנחלקו בגמרא</b>: נסמן לעיל ה, א."],["584","9","<b>טוב טעם ודעת למדני</b>: תהלים קיט, סו."],["585","10","<b>חכים ולא בחכמה ידיע'</b>: ת\"ז בהקדמה (יז, ב)."]]],[2800530058,"באמונה פשוטה שלמעלה מן הטעם ודעת דוקא כמשל הנ\"ל כבן שעושה ציווי אביו בלא טעם שמכוין לאמיתת הטעם שבו כמו שהוא והוא הגורם לו שיעמוד אח\"כ על אמיתת הדבר כו' כנ\"ל וכך לפי שבמצותיך האמנתי בלא טעם הוא שזוכה שיקבל טוב טעם ודעת שבתורה וע\"כ מבקש טוב טעם ודעת כו' והיינו מה שנתגלו טעמי תורה במ\"ת שזהו ענין שתי הלחם לפי שהאמינו בה' ובמשה עבדו ביצ\"מ כנ\"ל וד\"ל. וזהו שקורין פ' זכור לפני חג הפסח דהנה שמואל הוכיח לשאול על אודות עמלק שהביא מראשית החרם<sup data-n=\"586\">1</sup> לזבוח לה' עולות כו' ואמר לו החפץ לה' בעולות וזבחים כו' שמוע מזבח טוב להקשיב<sup data-n=\"587\">2</sup> כו' כמבואר במ\"א באריכות בענין מ\"ש חנה רמה קרני ולא רמה פכי ששאול נמשח בפך<sup data-n=\"588\">3</sup> לא נמשך מלכותו ודוד בקרן כו' שזהו מ\"ש לריעך הטוב ממך<sup data-n=\"589\">4</sup> מפני שדוד היה מקים עול מצות כמ\"ש הוקם על<sup data-n=\"590\">5</sup> והיינו כמ\"ד מצות א\"צ כונה שיעשה המצוה בלא טעם כלל ושאול היה עושה המצוה בכונה ובטעם דוקא וכמו במצוה זאת דמלחמת עמלק היה יודע שאול טוב טעם ודעת העליון שבמצוה זו ועשה במס\"נ ובכונה שלימה כפי אמתית הטעם וסוד ה' שיש בזה וראיה לזה שאמר הקימותי דבר ה'<sup data-n=\"591\">6</sup> שהקים דבר ה' כמו שהוא לאמיתתו למעלה וגם הוסיף עוד לעשות לטוב הדבר כפי שהיה יודע שצריך למחות זכר עמלק שיעלו עולות וזבחים ממיטב הצאן שלהם שזהו בחי' הבירורים דניצוצות הטוב שיוכלו לעלות למעלה מקליפת עמלק אחר שלא החי' כל נשמה<sup data-n=\"592\">7</sup> והשיב לו שמואל שמוע מזבח טוב כו' שמצות א\"צ כונה וטעם וסוד כלל ואע\"פ שיש בעו\"ז<sup data-n=\"593\">8</sup> שהן קרבנות טעם וסוד ה' אבל אין זה העיקר והגם שבודאי יש חפץ ה' עכ\"פ בזבח הקרבן כי רצה\"ע הוא במעשה עצמה של הקרבן אך בכאן בקליפות עמלק אין חפץ ה' בזבח שיעלה מהם לפי שהקרבן עולה לריח ניחוח כו' ויעלה לרצון למעלה ובאמת הנה עיקר הקליפה דעמלק שהוא חוצפא ועזות זהו היפך גמור כ\"כ לקדושה האלקי' עד ששנא' שלו הוא למעלה מן הטעם וכמו שרואים בחוש ששונאים לכל מי שיעבוד ה' באמת שהי' שנאה שאין בה טעם כלל שהשונא בתכלית נקוד' שבנפשו לא יוכל לסבול עליה שכנגדו למעלה מן הטעם כמו שבאהבה יש אה\"ר שלמעלה מן הטעם לגמרי עד שמתבטל כל עצמותו ומהותו שלא יוכל לבא בטעם ודעת כלל כך יש בשנאה עצמי' שלמעלה מן הטעם שיפקיר ע\"ע<sup data-n=\"594\">9</sup> להרע לו בכל אשר לו כו'. וזה היה סיבת מלחמת עמלק ברפידים<sup data-n=\"595\">10</sup> אחר שראה נסים דיצ\"מ כו' מצד תכלית השנאה והוא תכלית העזות והחוצפא שלמעלה מן הטעם ולנגדו בקדושה האלקי' אין לזה תיקון כ\"א בבחי' הביטול לאין באמצעות אה\"ר מכל וכל שלמעלה מן הטעם לגמרי והיא האמונה כנ\"ל שזהו עיקר המנגד לקליפ' עמלק שזהו מה שהרים משה ידו<sup data-n=\"596\">11</sup> למעלה מן הראש שהוא למעלה מן הדעת וגבר ישראל על עמלק ובהניח ידו שהוא למטה מן הדעת גבר עמלק שהוא בשרשו בעזות ושנאה שלמעלה מן הדעת וד\"ל ונמצא שאין קרבן מן הצאן דעמלק שהוא העלאת מ\"ן לריח ניחוח בבחי' המוחין שבהן טעם שאין זה",[["586","1","<b>מראשית החרם</b>: שמואל-א טו, כא."],["587","2","<b>החפץ לה'. . להקשיב</b>: שם, כב."],["588","3","<b>רמה קרני. . ששאול נמשך בפך</b>: שמואל-א ב, כא. י, א. טז, יג. מגילה יד, א. סה\"מ תקס\"ט ע' קנז ואילך. תו\"א יתרו עב, ג. מאמרי אדה\"א הנחות תקע\"ז ע' קטז."],["589","4","<b>לריעך הטוב ממך</b>: שמואל-א טו, כח."],["590","5","<b>הוקם על</b>: שמואל-ב כג, א. ראה במדב\"ר פי\"ח, כא. מאמרי אדה\"א שמות ח\"א ע' רכה. וש\"נ."],["591","6","<b>הקימותי דבר ה'</b>: שמואל-א טו, יג [ושם: את דבר ? ראה סה\"מ תקס\"ה ח\"ב ע' תשצו. מאמרי אדה\"א שמות ח\"ב ע' תקסו]."],["592","7","<b>שלא החי' כל נשמה</b>: שמואל-א טו, ח."],["593","8","<b>בעו\"ז</b>: בעולה וזבחים."],["594","9","<b>ע\"ע</b>: על עצמו. ואוצ\"ל: א\"ע את עצמו."],["595","10","<b>מלחמת עמלק ברפידים</b>: בשלח יז, ח ואילך."],["596","11","<b>שהרים משה ידו</b>: שם, יא. ראה גם מאמרי אדה\"א שמות ח\"ב ע' תקכ."]]],[2800530059,"תיקון כלל אדרב' יחזקנו אלא גם הצאן יחרם וע\"ז אמר החפץ לה' בעו\"ז דעמלק כמו בשאר קרבן ובזה טעה שאול וגם בעיקר העובדא שלו שהי' לו לעשות במלחמת עמלק בבחי' הביטול שלמעלה מן הטעם כי זהו עיקר המנגדו לעורר האה\"ר שלמעלה מן הטעם וז\"ש שמוע מזבח טוב שמוע בלא טעם יותר טוב מעו\"ז שהיא בטעם וכונה מפני שבזה עיקר מפלת קליפ' דעמלק וד\"ל:\n<b>ומזה</b> יובן בכל המצות כמ\"ד א\"צ כונה שזהו יותר טוב מן הכונה וזה היה מעלת דוד שהקים עול כו' והוא מ\"ש רמה קרני שנמשך מלכותו ושאול שנמשח בפך שהוא בחי' המדות שבאים מן השכל וטעם ע\"כ לא נמשך מלכותו כו' (ולע\"ל דוד מ\"י חי וקים<sup data-n=\"597\">12</sup> מטעם זה כמ\"ש במ\"א מ\"ש ואלה דברי דוד האחרונים<sup data-n=\"598\">13</sup> כו') והנה כאשר נמחה זכר עמלק כאשר קורין פ' זכור לפני הפסח דוקא אזי יוכל להיות מצות דמצה שהיא האמונה שלמעלה מן הטעם בליל א' דפסח שהוא עצמות הביטול שלמעלה מן הטעם שזהו המנגד לקליפות עמלק בסטר' דקדושה ואע\"פ שבזמן היה מפלת עמלק אחר יצ\"מ שזהו לאחר שיצאו באמונה וקבלו מקצת התורה בטוב טעם אזי היה יכול להיות מפלת עמלק אך עכשיו לאחר שכבר נמחה זכר עמלק ברוחניות ע\"פ התורה בפ' זו שכתב משה וצוה ליהושע זכור<sup data-n=\"599\">14</sup> כו' ע\"כ קורין פ' זו לפני הפסח שיהיה בחי' האמונה שע\"י המצה בשלימותה וראיה שביום א' דפסח הי' עיקר מפלת המן בפו\"מ כי אחר חצות לילה דא' דפסח ויום א' דפסח שזהו עיקר המצוה תלוהו על העץ ביום ב' דפסח<sup data-n=\"600\">15</sup> והמן היה צורר היהודים בשנאה שלמעלה מן הטעם ועזות וחוצפא שאין כמוה כי הפיל פור לפניו<sup data-n=\"601\">16</sup> כו' וכ\"ז מאשר מרדכי אינו כורע<sup data-n=\"602\">17</sup> שהוא יסוד אבא<sup data-n=\"603\">18</sup> כח מ\"ה דאור אבא דקדושה המנגדו ממש כו' וזהו שביום ב' דפסח מתחיל ימי הספיר' שזהו ביום שתלו את המן וכמ\"ש ממחרת השבת תספרו נ' יום<sup data-n=\"604\">19</sup> והספיר' אינה אלא מ\"ט יום וידוע שמ\"ט הימים הן בחי' נש\"ב<sup data-n=\"605\">20</sup> שהן ז' מדות דבינה דוקא וכ\"א כלול מז' והבינה נק' יש<sup data-n=\"606\">21</sup> ויש לזה אחיזה ליש דקליפה הוא עמלק ראשית גוים<sup data-n=\"607\">22</sup> כו' כמ\"ש במ\"א בענין המן מן התורה<sup data-n=\"608\">23</sup> מנין שנאמר המן העץ אשר צויתיך כו' שהוא עה\"ד כו' ואמנם ביום ב' דפסח שמתחיל נש\"ב דקדושה זהו מפני שתלו את המן למעלה מנ' אמה<sup data-n=\"609\">24</sup> אז יאירו אור ימי הספיר' דנש\"ב דקדושה וד\"ל ובזה יובן מה שאומרים<sup data-n=\"610\">25</sup> והיא שעמדה לאבותינו שהיא האמונה שמנגד לקליפת עמלק שהוא המן וזה שלא אחד בלבד עמד עלינו כו' וד\"ל:\n(טו) <b>ואחר</b> כל הנ\"ל יובן מ\"ש ממחרת השבת תספרו נ' יום דבאמת זהו פלא גדול לכאור' למה יקרא יו\"ט דפסח בשם שבת יותר משאר המועדים שנקראים מקראי קדש<sup data-n=\"611\">26</sup> ולא קדש ואין נק' קדש רק השבת שנ' כי קדש היא לכם<sup data-n=\"612\">27</sup> ואיך אמר ממחרת השבת תספרו כו' והל\"ל ממחרת המועד ועוד למה מתחיל מצו' הספי' ממחר' יום א' דפס' ולא מיו' א' דפסח עצמו כו' אך הנה יש להקדים תחלה ענין הידוע בעיקר ענין השבת שבו שבת וינפש<sup data-n=\"613\">28</sup> שזהו",[["597","12","<b>דוד מ\"י חי וקים</b>: נסמן לעיל יא, א."],["598","13","<b>ואלה דברי דוד האחרונים</b>: שמו\"ב כג, א. ראה גם שע\"ת פב, ג."],["599","14","<b>בפ' זו שכתב משה. . זכור</b>: ראה ספורנו ורמב\"ן בשלח יז, יד."],["600","15","<b>תלוהו. . ביום ב' דפסח</b>: ראה שו\"ע אדה\"ז הל' פסח סת\"צ ס\"ב."],["601","16","<b>הפיל פור לפניו</b>: אסתר ג, ז."],["602","17","<b>מרדכי אינו כורע</b>: אסתר ג, ב."],["603","18","<b>מרדכי. . יסוד אבא</b>: ראה פע\"ח (שער הפורים) שי\"ט פ\"ה."],["604","19","<b>ממחרת השבת. . יום</b>: אמור כג, טז [בדילוג]."],["605","20","<b>שמ\"ט הימים. . נש\"ב</b>: ראה לקו\"ת במדבר י, ד. שה\"ש לה, ג. תו\"ח נח נח, ב הערה 30."],["606","21","<b>והבינה נק' יש</b>: נסמן לקמן קכז, א."],["607","22","<b>עמלק ראשית גוים</b>: בלק כד, כ."],["608","23","<b>המן מן התורה</b>: חולין קלט, ב. בראשית ג, יא. ראה תו\"א מג\"א צא, ב. מאמרי אדה\"א קונטרסים ע' שפה. וש\"נ. תו\"ח משפטים תמ, ב ואילך."],["609","24","<b>שתלוי. . למעלה מנ' אמה</b>: ראה גם מאמרי אדה\"א נ\"ך ע' תלה. וש\"נ."],["610","25","<b>מה שאומרים</b>: בהגדה."],["611","26","<b>המועדים שנקראים מקראי קדש</b>: ראה אמור כג, ז ואילך."],["612","27","<b>כי קדש היא לכם</b>: תשא לא, יד."],["613","28","<b>שבת וינפש</b>: תשא שם, יז."]]],[2800530060,"הנק' נייחא דרוחא בזוהר וענין נייחא דרוחא<sup data-n=\"614\">1</sup> זה היינו עד\"מ משביתת אדם ממלאכתו שנק' נייחא או מנוחה שזהו ענין החזרת אותו כח הפעול' שנתפשטה במלאכ' פעולתה לעצם הכח שבידו שזהו נק' נייחא אבל הוא רק נייחא דנפש שהוא רק המנוחה של כח הדם הוא הנפש המתפשט בתנוע' כידוע ואמנם נייחא דרוחא הוא למעלה מזה והוא מנוחת הרוח שבלב שהן המדו' שהוא מקור לכח התנועה שבמלאכ' הוא הנק' נייחא דרוחא וכמו שתשוב רוח האדם אליו בעת שנח ממלאכת עבודתו כידוע ועד\"ז הוא המנוחה שלמעלה גם מזה והוא הנק' נייחא דנשמתא שבמוחא שהוא כח השכל והתחכמות שבכלי המוח הנמשך למדות שברוח הלב חוזר אל בחי' עצמותו ומקורו והוא העיקר בענין השבת למעלה שזהו הנק' קדש העליון דבחי' החכמה נק' קדש<sup data-n=\"615\">2</sup> אך בשבת עולה בבחי' פנימיו' החכמה דהיינו בבחי' מקורה כמו שהחכמה באין דכתר כמ\"ש והחכמה מאין תמצא<sup data-n=\"616\">3</sup> ונק' אין דחכ' קודם שנמשכה בבחי' גלוי ליש במוח החכמה והוא מ\"ש כי קדש היא לכם בקדש העליון דכתר שבבחי' אין דחכמה שנקרא קדש מלה בגרמיה<sup data-n=\"617\">4</sup> כו' שלא נמשך למטה כלל כמ\"ש במ\"א וזהו עולת שבת שהשבת עולה כענין מזמור שיר ליום השבת<sup data-n=\"618\">6</sup> שהשבת עצמו ששרשו בחכמה עולה בשיר מפני ששובת וכשעולה עולה במקורו בבחי' אין שמשם תמצא והיינו בשבתו<sup data-n=\"619\">5</sup> לשון נסתר כידוע וד\"ל והיינו בחי' כח מ\"ה דחכמה כמו שהיא בבחי' אין ומ\"ה במקור' הנעלם לפי שבראשית דחכמה שבמע\"ב נמי מאמר<sup data-n=\"620\">7</sup> הוא לפי שבמע\"ב הרי ירד האור דחכמה מאין ליש ובשבת חוזר ועול' למקורו העצמי וידוע שזהו ענין או\"ח שחוזר למקורו הראשון<sup data-n=\"621\">8</sup> אחר שירד למטה בבחי' אור ישר והוא כל ו' ימי בראשית שירד אור החכמה בבינה ומדות בבחי' או\"י עד בחי' המעשה בפו\"מ ובשבת הכל עולה בבחי' או\"ח וזהו כמו עד\"מ המים שבהר גבוה שיורדים ונמשכי' מגבוה לנמוך בעמק שכאשר עולין מלמטה למעלה עולין עד מקור חוצב'<sup data-n=\"622\">9</sup> בהר שמשם התחילו לירד ולמשוך למטה ואמנם א\"א שיוגבהו למעלה ממקורם כלל וזהו משל להבין שא\"א שיעלה ויגיע בחי' או\"ח למעלה מהתחלה דאו\"י כי זהו שאמר בס\"י נעוץ תחלתן בסופן<sup data-n=\"623\">10</sup> וסופן בתחלתן א\"כ אין לסוף יותר כח לעלות מן התחלה דנעוץ סופן בתחלתן לבד ולא למעלה מתחלתו כו':\n<b>אך</b> הנה פי' ממחרת השבת היינו למעלה גם מכל עיקר בחי' עולת שבת הנ\"ל דהיינו למעלה גם מבחי' אין דחכמה שנקרא קדש מלה בגרמי' הנ\"ל וע\"כ נקרא ממחרת של השבת שהשבת עצמו מקבל משם כו' והוא יום ב' דפסח שבו מתחיל הספי' שנקרא מחרת השבת דיום א' דפסח נקרא שבת ויום שלאחריו נקרא ממחרת השבת (דלא כצדוקים שאומרים מחרת השבת סתם דהיינו יום א'<sup data-n=\"624\">11</sup> דוקא) ואמנם באמת הנה גם בשבת עצמו יש בו עליה ב'<sup data-n=\"625\">12</sup> שעולה למעלה גם מבחי' אין דחכמ' הנ\"ל אע\"פ שאו\"ח אינו מגיע רק לתחלה דאו\"י כנ\"ל אך הנה במנוח' דשבת יש ב' מדריגות הא' בחי' עליה והסתלקות אותו האור ושפע שירד בוי\"מ הוא שחוזר ומתעלה ובא למקור חוצבו בלבד כנ\"ל כמו כח הפעולה שחוזר",[["614","1","<b>נייחא דרוחא</b>: ראה גם זהר בהר קח, א. מאמרי אדה\"ז על מארז\"ל ע' קעו. וראה גם שע\"ת ח\"ב צו, א ואילך."],["615","2","<b>חכמה נק' קדש</b>: ראה זהר (רע\"מ) בא מג, ריש ע\"ב. אמור צד, ב. מאמרי אדה\"א דברים ח\"ג ע' תתקב. וש\"נ."],["616","3","<b>והחכמה מאין תמצא</b>: איוב כח, יב."],["617","4","<b>קדש מלה בגרמי'</b>: ראה זהר אמור צד, ב. לקו\"ת מסעי צג, א. שע\"ת ח\"ב צו, ב ואילך. מאמרי אדה\"א בראשית ע' מה ואילך."],["618","6","<b>מזמור שיר ליום השבת</b>: תהלים צב, א. ראה גם סידור קפח, ד."],["619","5","<b>עולת שבת. . בשבתו</b>: פינחס כח, י. ראה גם שע\"ת שם צח, ד. מאמרי אדה\"א שמות ח\"ב ע' רלח."],["620","7","<b>שבראשית. . נמי מאמר</b>: ר\"ה לב, א."],["621","8","<b>או\"ח שחוזר למקורו הראשון</b>: ראה הנסמן במאמרי אדה\"א נ\"ך ע' תצ. תו\"ח נח ס, ב הערה 22."],["622","9","<b>עולין עד מקור חוצב'</b>: ראה יומא לא, א. מאמרי אדה\"א נ\"ך ע' קנ. וש\"נ."],["623","10","<b>בס\"י נעוץ תחלתן בסופן</b>: ראה ס\"י פ\"א מ\"ז."],["624","11","<b>דלא כצדוקים. . יום א'</b>: ראה מנחות סה, סע\"א ואילך."],["625","12","<b>בשבת. . עלה ב'</b>: ראה גם מאמרי אדה\"א נ\"ך שם."]]],[2800530061,"אל עצם הכח עד כח של השכל שבעשיה שירד ונטרד במלאכה זו עולה אל עצם כח השכל שלוקח משם ובודאי לא יעלה ויגיע רק למקו' חוצבו כמו שהיה בתחלת ירידת אור השכל הזה כו' כנ\"ל בענין נעוץ סופן בתחלתן לבד אך ע\"י ביטול והתכללות זאת הרי מגיע גם אותו מקור השכל לבחי' פנימיות מהות ועצמות כח המשכיל ההיולי שזהו טרם שנעשה מקור לירידת והתפשטות כלל שזהו למעלה הרבה גם מראשית ירידת אור שכל זה שנקרא אין דחכמה כו' כמו שאנו רואים בטבע המנוחה שגם שהוא נח ממלאכה וטירדא לבד אבל כשהוא נח בא לעצמות ומהות נפשו ממש לפי שזהו טבע דבחי' או\"ח כשהוא חוזר חוזר לקדמותו ממש שהוא בחי' העצמות ממש וזהו פי' הפשוט דבו שבת וינפש ממש וד\"ל וזהו מדריגה הב' במנוחה דשבת שהעלאה דאו\"ח עולה ונכלל בעצמות המאציל ממש שלמעלה גם מבחי' מקור להתפשטות וירידות אור החכמה מאין כו' שהוא למעלה מאין דחכמה עצמה וזהו השתחוו לה' בהדרת קדש<sup data-n=\"626\">13</sup> הדורו של קדש דאין דחכמה למעלה הימנו והוא ביטול דכח מ\"ה דחכמה ליכלל בעצמות כו' וזהו כמו שאם היו המים יכולים לעלות גם למעלה ממקו' חוצבם כו' וזהו עיקר ענין השבת שנקרא עליות העולמות בכלל גם בבחי' התענוג שמלובש בחכמה (שנקרא עתיקא קדישא ) עולה למהות ועצמות התענוג הפשוט שבמוה\"ע<sup data-n=\"627\">15</sup> המאציל ממש (שנקרא עתיקא סתימא<sup data-n=\"628\">14</sup> או ע\"י דע\"י<sup data-n=\"629\">16</sup> כו') אך ממקום שעלה בעלי' הב' במוה\"ע<sup data-n=\"630\">17</sup> ממש הרי משם חוזר ויורד בבחי' או\"י שהוא ג\"כ בבחי' ירידות העצמות ממש ויורד ונמשך ומתלבש עד למטה ממש והוא כמו שאנו רואים דבר זה בכל הנסים ונפלאות שנעשו למטה בהיפוך הטבע כמו רחב\"ד שאמר<sup data-n=\"631\">18</sup> מי שא' לשמן וידליק הוא יאמר לחומץ וידליק הרי צירוף האותיות האלקי' דטבע השמן נמשך בחומץ וכאשר נהפך הצירוף בשרשו בי' מאמרות ודאי כך עלה עד רום המעלות בשרש דשרש האותיות הראשון והוא גם בבחי' אין דחכמה שהמשיך ממקור האין דחכמה המשכה חדשה והיינו ממהו\"ע המאציל והרי ירד ביריד' והמשכ' למטה בפ\"מ כתחיית המתים בפ\"מ וכהפיכת ים ליבשה בפ\"מ וכן כחומץ שהדליק וכה\"ג א\"כ הרי בא האור הזה שממהו\"ע ממש בדרך התלבשות וירידה בדבר גשמי באות ומופת שבו נעשה היפוך הטבע בצירופים דדיבור וע\"כ הרואה מקום שבו נעשה הנס מברך<sup data-n=\"632\">19</sup> ברוך אתה לנוכח מפני שזהו הבא למטה במקום זה ממהו\"ע ממש כו' ולפ\"ז הרי גם בבחי' ירידה דאו\"י יש מבחי' אור העצמות ממש כמו בעליי' הב' דאו\"ח שחוזר לקדמותו ממש כנ\"ל רק שהוא בדרך העלא' וזהו בדרך ירידה בלי שום הפרש ביניהם כלל בעצם זה האור שהוא מהעצמות דוקא אך מ\"מ זהו ההפרש שיש ביניהם שבהעלאה דאו\"ח שהוא בבחי' עליה דביטול היש לאין עד בחי' האין דחכמה שגם הוא עולה ומתכלל בעצמו' נקרא מופלא ונעלם בבחי' סדכ\"ס למעלה ממש אבל בנסים וכה\"ג הרי בא האור העצמות למטה בבחי' יש ממש באותו מקום ודבר שנעשה בו הנס אע\"פ שנק' נפלאות להיותו בא ועולה בביטול כח צירוף הראשון עד מקורא דכולא אבל הרי חוזר ויורד",[["626","13","<b>השתחו לה' בהדרת קדש</b>: תהלים כט, ב. ראה גם מאמרי אדה\"א נ\"ך ע' קמט."],["627","15","<b>שבמוה\"ע</b>: נסמן לעיל ב, א."],["628","14","<b>עתיקא קדישא. . עתיקא סתימא</b>: ראה גם לקמן סא, ב ובהנסמן לשם."],["629","16","<b>ע\"י דע\"י</b>: עתיקא דעתיקין. ראה גם מאמרי אדה\"א שמות ח\"א ע' מד. וש\"נ."],["630","17","<b>במוה\"ע</b>: נסמן לעיל ב, א."],["631","18","<b>רחב\"ד שאמר</b>: נסמן לקמן קמד, א."],["632","19","<b>הרואה מקום. . מברך</b>: ברכות נד, א. ראה גם שע\"ת ח\"א יד, ג ואילך ובהנסמן במ\"מ לשם."]]],[2800530062,"משם ונמשך להיות בצירוף אותיות חדשים ביש גמור כמו להחיות המת בפ\"מ ולהדליק המים<sup data-n=\"633\">1</sup> וחומץ וכה\"ג אשר דוקא ביש גמור הנפרד נמשך ומלובש מבחי' אור העצמות ממש ששם עולה ונכלל גם בחי' אין דחכמ' בעליי' דאו\"ח בבחי' ההעלם דסדכ\"ס הוא עצמו שיורד למטה בנסים וכה\"ג בגלוי אור הנבואה וגלוי שכינ' בהיכל ק\"ק וכה\"ג וד\"ל אך א\"כ יש להבין למה נק' הנסים שהיה במצרים בשם נפלאות ובשם מופתים כי' מכות שהיה בהיפוך הטבע שנאמר ונתתי מופתים<sup data-n=\"634\">2</sup> כו' מאחר שבהיפך הטבע הרי הוא בחי' גלוי אור העצמי' ולא בהעלם כעלי' דאו\"ח כנ\"ל וכתיב כימי צאתך מארץ מצרים אראנו נפלאות<sup data-n=\"635\">3</sup> משמע דלעתיד דוקא אראנו למטה אותן הנפלאות שהיו בבחי' העלם ביצ\"מ וכן אמר ביום ההוא יהיה<sup data-n=\"636\">4</sup> ה' אחד ושמו אחד דיח\"ת דשמו אחד שזהו ביטול היש לאין כמו בנסים וכה\"ג יהיה שוה לה' אחד יח\"ע דע\"ס דאצי' שהוא דכמו שאא\"ס הוא למעלה מעלה עד אין קץ במהו\"ע ממש כך יהי' ממש בירידתו ביחו\"ת למטה<sup data-n=\"637\">5</sup> עד כו' בלי שום הפרש כלל וזהו יהי' ב\"פ י\"ה<sup data-n=\"638\">6</sup> ולא כשם הוי' דעכשיו שיח\"ת אינו בבחי' יח\"ע ממש משום דבחי' סדכ\"ס כמו שהוא למעלה במהו\"ע ממש אינו נגלה למטה ביח\"ת גם בנסים וכה\"ג בנבואה וגלוי אלקות בבהמ\"ק כו' אלא צ\"ל כמ\"ש במ\"א (בענין מזמור לתודה<sup data-n=\"639\">7</sup> הריעו כו' ר\"ת הלכה<sup data-n=\"640\">8</sup> והשתחוו לה' ס\"ת קבלה<sup data-n=\"641\">9</sup> ) שיש בנסים ב' מדריגות הא' נסים שנעשו בהיפך הטבע דוקא שבא האור מלמעלה מן הטבע לגמרי ונקרא אות ומופת כי' מכות דמצרים שנהפך המים לדם כו' וכה\"ג שז\"ש ומופתים בארץ חם<sup data-n=\"642\">10</sup> בהיפוך מ\"ח צרופי'<sup data-n=\"643\">11</sup> דשם אלקים שמושל על הטבע מכח העליון שלמעלה מן הטבע דוקא וע\"כ אמרו אצבע אלקים היא<sup data-n=\"644\">12</sup> כו' והב' נסים שבאו בהתלבשות בדרך הטבע דוקא כמו ד' שצריכים להודות<sup data-n=\"645\">13</sup> כחולה שנפל למשכב שסיבת רפואתו הי' ע\"פ סממני הרפוא' לרפאות חולה המסוכן וכעמיד' רוח סערה בים ע\"י שישתוק הים מזעפו<sup data-n=\"646\">14</sup> ומי שיצא מבית האסורים ממות לחיים ע\"י סיבה טבעית כיוסף שהזכירוהו לטוב<sup data-n=\"647\">15</sup> וכה\"ג בכל הצלה ונסים שנעשו בדרך הטבע כנס דאסתר עם אחשורוש<sup data-n=\"648\">16</sup> וכנס דחנוכה ע\"י מלחמה<sup data-n=\"649\">17</sup> וכך בכל אדם בפרט נסים נעשו לו עפ\"י הטבע שלא ניכר בזה אור אלקי שלמעלה מן הטבע כלל ועכ\"ז נס גמור הוא אלא שמלובש בדרכי הטבע כמו בגלות שנסים ממש נעשו לישראל בכל דור ודור בלא נודע איך ומה כמו שאמר אותותינו לא ראינו<sup data-n=\"650\">18</sup> כו' ולכאורה אין זהו<sup data-n=\"651\">19</sup> מובן מהו עיקר ההפרש ביניהם הלא באמת ברצון ה' נעשה הנס ומהו ההפרש אם נעשה בדרך הטבע או למעלה מן הטבע כתחה\"מ והפך ים ליבשה וי' מכות וכה\"ג אך הענין הוא דהנס הנעשה בדרך הטבע ה\"ז ענין ממשלה האלקי' בכוחות הטבע עצמם לשנותם מהיפך להיפוך שלא יעשו ויתנהגו כרצונם כמו להשתיק הרוח סערה ולרפאות חולי המסוכן בכחות הטבע עצמו כי אלקי' גי' הטבע<sup data-n=\"652\">20</sup> למשול בטבע עצמו ע\"פ דרכי הטבע שיהופך מדין לחסד ומרע לטוב וזהו ל' אלקים ל' שררה<sup data-n=\"653\">21</sup> וממשלה כמו נשיא אלקים<sup data-n=\"654\">22</sup> כו' וכמו מסדר הכוכבים ומזלות<sup data-n=\"655\">23</sup> שהן שרשי הטבע דדצח\"מ להפוך בהם עצמם כרצונו דוקא כגרזן ביד החוצב<sup data-n=\"656\">24</sup> כו' וכמ\"כ ענין כללות הנסים שצריכים להודות שניצולים מן המות לחיים",[["633","1","<b>ולהדליק המים</b>: לעיל (כט, ב) וכהפיכת ים ליבשה. וראה גם לקמן (ל, ב). מלכים-א יח, לח."],["634","2","<b>ונתתי מופתים</b>: יואל ג, ג. הגדה של פסח. וראה ג\"כ הנסמן במאמרי אדה\"א נ\"ך ע' כב."],["635","3","<b>כימי צאתך. . נפלאות</b>: מיכה ז, טו."],["636","4","<b>ביום ההוא יהי'</b>: זכרי' יד, ט. נסמן לקמן קמה, א."],["637","5","<b>שאא\"ס הוא למעלה. . למטה</b>: ראה ז\"ח יתרו לד, ג. ת\"ז תי\"ט (מ, ב). סתנ\"ז. תו\"ח נח סט, ב ובהערה 11. לקמן לו, א. נז, א. נח, סע\"א ואילך."],["638","6","<b>יהי' ב\"פ י\"ה</b>: ראה לקו\"ת וספר הליקוטים להאריז\"ל זכרי' שם. הנסמן במאמרי אדה\"א נ\"ך ע' קנב."],["639","7","<b>בענין מזמור לתודה</b>: מאמרי אדה\"א נ\"ך ע' קנא ואילך."],["640","8","<b>הריעו כו' ר\"ת הלכה</b>: תהלים ק, א. ראה לקו\"ת להאריז\"ל שם. הנסמן במאמרי אדה\"א דברים ח\"ד ע' א'תעה. תו\"ח בראשית לה, ג ובהערה 47."],["641","9","<b>והשתחוו לה' ס\"ת קבלה</b>: ראה פע\"ח (שער השבת) שי\"ח ספכ\"א. הנסמן במאמרי אדה\"א ויקרא ח\"ב ע' תשל. נ\"ך ע' קלט."],["642","10","<b>ומופתים בארץ חם</b>: תהלים קה, כז."],["643","11","<b>חם בהיפוך מ\"ח צרופי'</b>: נסמן לקמן קמו, ב."],["644","12","<b>אצבע אלקים היא</b>: וארא ח, טו."],["645","13","<b>ד' שצריכים להודות</b>: ברכות נד, ב."],["646","14","<b>שישתוק הים מזעפו</b>: ראה יונה א, יא. טו."],["647","15","<b>כיוסף שהזכירוהו לטוב</b>: מקץ מא, יב ואילך."],["648","16","<b>כנס דאסתר עם אחשורש</b>: ראה אסתר פ\"ה ואילך. לקו\"ש (תזריע) כרך יז ע' 154 בהערה 51."],["649","17","<b>וכנס דחנוכה ע\"י מלחמה</b>: ראה גם לקו\"ש (חנוכה) כרך טו ע' 368 ובהערות שם. ס' השיחות תשמ\"ט ח\"א ע' 114 בהערה."],["650","18","<b>אותותינו לא ראינו</b>: תהלים עד, ט."],["651","19","<b>זהו</b>: כנצ\"ל: זה."],["652","20","<b>אלקי' גי' הטבע</b>: ראה של\"ה (מס' פסחים מצה עשירה) קסג, סע\"ג. שהיחוה\"א רפ\"ו. הנסמן במאמרי אדה\"א דברים ח\"ג ע' תתקעג."],["653","21","<b>אלקים ל' שררה</b>: ראה גם מאמרי אדה\"א בראשית ע' קצו. וש\"נ. נ\"ך ע' קנג."],["654","22","<b>נשיא אלקים</b>: חיי שרה כג, ו."],["655","23","<b>מסדר הכוכבים ומזלות</b>: ראה גם לעיל כא, ב ובהנסמן לשם."],["656","24","<b>כגרזן ביד החוצב</b>: ראה גם לעיל ז, א ובהנסמן לשם."]]],[2800530063,"ע\"פ הטבע עצמו שזה מורה כח השתררות האלקי' על דרכי הטבע בכח עצמם דוקא לשנותם כרצונו כו' כמו כשעלה ברצונו חסד להציל החולה והשבוי בדרך הטבע כנ\"ל אך האות והמופת שבא מלמעלה מן הטבע האנושית להפוך הטבע דוקא ה\"ז הארה האלקי' כמו שהיא למעל' מן הטבע לגמרי והיינו מעלמא דאתכסיא שבבחי' הוי' שלמעלה משם אלקי' גי' הטבע וכענין מי שאמר לשמן כו' והיינו ענין כ\"ו כל\"ח<sup data-n=\"657\">25</sup> כידוע שחסדים דהוי' בוקעים ומאירים להסיר מסך הטבע כו' וכן כי' מכו' דמצרי' להפוך מים לדם וכה\"ג נק' מופתי' בארץ חם כנ\"ל והן הנק' נפלאו' כי יפלא האור הזה לעין כל רוא' ואינ' יודעי' מה הוא לפי שאין לטבע האנושי' שום השגה ותפיסא בזה כלל ופלא יקרא כמ\"ש לעוש' נפלאו' לבדו<sup data-n=\"658\">26</sup> כו' שלא נודע רק מצי' שנראה לעין דבר הפלא הזה אבל לא נודע ומושג מהות אור אלקי זה שבא מלמעלה מן הטבע כלל אעפ\"י שרואה תחיית המת בפ\"מ או חומץ ומים שנדלק<sup data-n=\"659\">27</sup> אבל אינו משיג ויודע מהותו מה הוא כו' משא\"כ ההצלה שנעשה בדרך הטבע עצמו כמו שנשתק הרוח סערה או רפואו' חול' המסוכן שרוא' במהות אות' ההארה בתפיסא והשגה אנושית כהשגת מהות הטבע עצמה ממש מאחר שנעשה ההצלה בדרך הטבע עצמו שהוא מושג ונראה בטבע האנושית ממש וד\"ל (וכנס דאחשורוש<sup data-n=\"660\">28</sup> שנהפך הענין מרע לטוב ע\"י אהבתו לאסתר שסיבה זו עצמה נשלחה מאת ה' ולהיפך כאחאב שנפל ברמו' גלעד<sup data-n=\"661\">29</sup> כו' וכה\"ג) (וז\"ש לאחז העמק שאל' שיהי' הנס מלוב' בטבע בעמ\"ת כמ\"ש אתה אל מסתתר<sup data-n=\"662\">31</sup> וכן אותותינו כו' או הגב' למעלה<sup data-n=\"663\">30</sup> בעמ\"ר מבחי' נפלאות ה' שלמעלה מעלה שיאיר למטה כו' וכן במצרים אני ולא מלאך<sup data-n=\"664\">32</sup> מסדכ\"ס שעושה נפלאות לבדו כו' וז\"ש העלמה הרה<sup data-n=\"665\">33</sup> ע\"פ הטבע כו') ועפ\"ז יובן ג\"כ ענין ההפרש בין בחי' העלאה דאו\"ח בעצמות ממש שנק' נפלא ומכוסה בהעלם העצמו' למעל' מעל' סדכ\"ס כו' ובין בחי' או\"י שבא ירידת האור למט' מטה דוקא שזהו כמו בנסים שבאו בהתלבשו' ביש גמו' בדרכי הטבע עצמם עד שיש השגה אנושי' בזה ממש כנ\"ל עד שהוא היפך הפלא כי זהו ממש אותו הנס שהוא למעלה מן הטבע רק שהוא נק' נפלאות ובבואו בדרך הטבע בא בבחי' או\"י שאין כאן אפי' בטול היש כלל אדרבה מלובש ביש גמור שהרי מותפס בדרך הטבע כו' שמשיגי' מהותו דוקא כנ\"ל אבל הוא אותו אור העצמו' שלמעלה במהו\"ע שנק' סדכ\"ס כו' שזהו בנסים שנק' נפלאות כנסים דמצרי' שהן בבחי' ההעלם דעצמו' רק שמאי' למט' בדרך פלא דוקא שלא נודע מהות' כלל כנ\"ל וד\"ל (ועד\"ז הוא ההפרש בין קבלה שהוא בבחי' סוד ה' גנוז למעלה מעלה ובין הלכה שמושג מהות הדבר למטה כמ\"ש שם באריכות<sup data-n=\"666\">34</sup> ):\n(טז) <b>ובכ\"ז</b> יובן מ\"ש כימי צאתך מארץ מצרים אראנו נפלאות דהגם שהנסים שהיו במצרים היו בגלוי גמור לעין כל מלובשי' ביש גמור כמים שנהפכו לדם וכצפרדע וכנים כו' שלא יכלו החרטומים להוציא כו' אבל זה היה היפך הטבע הבא מכח האלקי העליון עד רום המעלו' שנק' נפלאות בלי נודע מהות' כלל רק מציאותן נראה בעליל אבל לע\"ל אראנו נפלאו' העליונו' למטה שיהיו מושגי' במהות' כמו שהן למעל' ולא יהיו נקראי' מופל' כלל כמו",[["657","25","<b>כ\"ו כל\"ח</b>: ראה גם מאמרי אדה\"א שמות ח\"ב ע' תיז? דברים ח\"א ע' קעט? ח\"ד ע' א'שיח? הנחות תקע\"ז ע' רכט ובהנסמן בהנ\"ל."],["658","26","<b>לעוש' נפלאו' לבדו</b>: תהלים קלו, ד [בדילוג]. עב, יח [ושם: עושה]."],["659","27","<b>ומים שנדלק</b>: ראה לעיל (ל, א) הערה ולהדליק."],["660","28","<b>וכנס דאחשורוש</b>: ראה אסת\"ר א, א."],["661","29","<b>כאחאב שנפל ברמו' גלעד</b>: מלכים-א כב, כ ואילך."],["662","31","<b>אתה אל מסתתר</b>: ישעי' מה, טו."],["663","30","<b>העמק שאל'. . או הגב' למעלה</b>: נסמן לקמן קט, א."],["664","32","<b>אני ולא מלאך</b>: ספרי תבוא כו, ח. זהר (מהנ\"ע) וירא קיז, א. הגדה של פסח."],["665","33","<b>העלמה הרה</b>: ישעי' ז, יד. ראה גם מאמרי אדה\"א נ\"ך ע' קנד ובהנסמן שם."],["666","34","<b>כמ\"ש שם באריכות</b>: מאמרי אדה\"א נ\"ך ע'\nקנו."]]],[2800530064,"הנסי' שנעשו בדרך הטבע שמושג מהות' ואינן נק' פלא כלל כנ\"ל וד\"ל (ומ\"ש וירא ישראל<sup data-n=\"667\">1</sup> את היד הגדולה אשר עשה ה' במצרים כו' היינו בקי\"ס שהיה שם גלוי ההעל' דעצמות למטה מעין דלע\"ל כמאמ' ראתה שפחה על הים<sup data-n=\"668\">2</sup> מה שלא ראה יחזקאל כו' ומ\"ש עד יעבור עמך ה' ולע\"ל אמ' עד יעבור<sup data-n=\"669\">3</sup> סתם שלמעלה משם הוי' כו' היינו משום דבנהר יעברו ברגל<sup data-n=\"670\">4</sup> בנהר דבינה שם נשמחה בו ממש וקי\"ס יהי' אז טפל כמ\"ש במ\"א ויתבא' בסמוך) (ונמצא מובן מכל הנ\"ל דנסים שבזמן הגלות שמלובשי' בהסתר בדרכי הטבע דוקא עד שאמ' אותותינו לא ראינו שעכשיו הן למטה הרבה מנסים שלמעל' מן הטבע לגמרי שנק' נפלאות ה' עד בחי' העצמות ממש הנה לע\"ל יהי' להיפך שנסים האלו יגלו מה שבהן מבחי' העצמו' ממש ונסים שנק' נפלאו' יבואו לגלוי מההעלם בדרכי הטבע לפי שהטבע עצמו לא יסתיר כלל וז\"ש רז\"ל כל שאינו בהסת' פנים<sup data-n=\"671\">5</sup> אינו מהם כו' שהוא מ\"ש ואנכי הסתר אסתיר פני<sup data-n=\"672\">6</sup> בזמן הגלות כו' שהסתר זה יגלה לע\"ל דוקא שיהיו למעל' מן הנפלאו' שביצ\"מ מטעם שבהם יורד מבחי' העצמות ממש עד שאין כמוהו בנפלאו' העליונות עכשיו ועכ\"ז אמ' למען תזכור<sup data-n=\"673\">7</sup> כו' כל ימי חייך לימוהמ\"ש ועוה\"ב וגם מ\"ש כיצי צאתך מא\"מ משמע פשוטו כמו שהי' הגלוי נסים ונפלאות ביצ\"מ כך אראנו נפלאות לע\"ל משום שאמר ועברתי אני ולא מלאך<sup data-n=\"674\">8</sup> כו' וד\"ל) ועפ\"י כל הנ\"ל יובן עיקר ענין השבת והחול שהשבת גורם ירידת האור מן העצמות להתלבש בימות החול בבחי' א\"י ג\"כ כמו שעלה בבחי' או\"ח בעול' שבת כנ\"ל וכמ\"ש וקראת לשב' עונג<sup data-n=\"675\">9</sup> כידוע דקריאה זו היינו בחי' ההמשכה והירידה מן עצמות התענוג הפשוט שבמהו\"ע ממש שעלה לשם בבחי' או\"ח לקדמותו ממש למעלה מעלה גם מבחי' אין דחכמה הוא עצמו שיורד בימות החול וע\"כ אומ' מזמור לתודה בחול<sup data-n=\"676\">10</sup> שימות החול זהו כמו הנסים שמלובשים בטבע שמביאי' קרבן תודה כנ\"ל כך יורד אא\"ס ב\"ה להתלבש בימות החול מעצמותו לרצון וחכמה ומדות ומדו\"מ כו' אבל בקב\"ש אומ' השתחוו לה'<sup data-n=\"677\">11</sup> כו' בבחי' עלי' דאו\"ח אל העצמו' ממש ועלי' זו עצמה חוזר ונמשך וזהו וקראת לשבת עונג העליון כו' וע\"כ השבת גורם לו' ימי המעשה דחול וחול גורם לשבת והיינו הך דהשביתה מן המלאכה דוקא עושה העלי' דאו\"ח בשבת ועלי' דאו\"ח דשבת עושה ירידה דאו\"י בחול והא בהא תליא משו' דזהו הכלל דעצמו' אא\"ס ב\"ה למעלה מעלה עד אין קץ שזהו בבחי' העלי' דאו\"ח ולמטה מטה עד אין תכלי' שזהו ירידה דאו\"י וכאש' בחי' ההעל' דאחר העל' שבעצמו' בא לידי ירידה למטה עד אין כו' היינו בחי' עמ\"ר שנמשך לעמ\"ת והוא ענין השבת והחול שהן עתה ב' הפכים רק זה גורם לזה אבל לע\"ל יתאחדו ממש כו' דהיינו שבחי' העילוי דהעלם אחר העל' שנק' סדכ\"ס שבמהו\"ע עד אין קץ כו' יבא כמו שהוא למטה כו' בלי שום הפרש בין בחי' מעלה ומטה כלל ולא יהיה בחי' עליה וירידה כלל רק למטה כמו למעלה ממש בשוה וז\"ש ביום ההוא יהיה ה' כו' יח\"ע ויח\"ת שוין ממש וזהו השוה ומשוה שבת וחול או\"ח ואו\"י (וכן ענין קבלה והלכה שהלכ' הוא כמו ימות החול שמלובש בדבר המושג בשכל האנושי במהותו",[["667","1","<b>וירא ישראל</b>: בשלח יד, לא."],["668","2","<b>ראתה שפחה על הים</b>: מכילתא בשלח טו, ב."],["669","3","<b>עד יעבור. . עד יעבור</b>: בשלח טו, טז. ראה גם לקמן לג, ב. פט, ב ואילך. צה, ב. מאמרי אדה\"א דברים ח\"ג ע' א'קכ."],["670","4","<b>דבנהר יעברו ברגל</b>: תהלים סו, ו. ראה גם ד\"ה לה\"ע קי\"ס מכ\"ק אדה\"א [קה\"ת תשמ\"ט ע' 27 ואילך]. מאמרי אדה\"א ויקרא ח\"א ע' רג. תו\"ח בשלח ע' רסד וע' רצד."],["671","5","<b>כל שאינו בהסת' פנים</b>: חגיגה ה, סע\"א. וראה גם לעיל כד, סע\"ב ואילך."],["672","6","<b>ואנכי הסתר אסתיר פני</b>: וילך לא, יח."],["673","7","<b>למען תזכור</b>: נסמן לעיל ב, ב."],["674","8","<b>ועברתי אני ולא מלאך</b>: בא יב, יב. נסמן לעיל ל, ב."],["675","9","<b>וקראת לשב' עונג</b>: ישעי' נח, יג."],["676","10","<b>אומ' מזמור לתודה בחול</b>: ראה גם מאמרי אדה\"א נ\"ך ע' קמח ואילך."],["677","11","<b>בקב\"ש אומ' השתחוו לה'</b>: ראה הערה שלפנ\"ז."]]],[2800530065,"בבחי' או\"י והקבלה בסוד הנעלם כבחי' העלי' דאו\"ח ושניהם יהיו שוין בע\"ל<sup data-n=\"678\">12</sup> לפי שלא יהי' בחי' מעלה ומטה בחילוק כי למטה ולמעל' שוין כמ\"ש הנה אלקינו זה<sup data-n=\"679\">13</sup> לנוכח כו' ואיך יתכן בחי' סוד והעלם כי כל העלם הוא בגלוי למטה ממש כמו למעלה וד\"ל וזה מה שאמר לע\"ל ולא ילמדו עוד<sup data-n=\"680\">14</sup> איש את רעהו כי כולם ידעו אותי מקטנ' עד גדולם כו' דלכאורה אין זה מובן דאם אמר ידעו אותי בל' דעת וכמ\"ש ומלאה הארץ<sup data-n=\"681\">15</sup> דעה את ה' הרי ודאי בבחי' הדעת והבינה צריכא לימוד שילמוד איש את רעהו דעת ובינ' כמו רב לתלמיד שא\"א שידע התלמיד מצד עצמו כ\"א שילמדנו רבו וכיהושע שקיבל ממשה וכה\"ג בכל דור יש ראשי אלפי כו' וכמשה שהיה רועה נאמן להשפיע דעת לכנ\"י כך יש בכל דור כו' ואיך אמ' ולא ילמדו עוד איש את רעהו כו' ואעפ\"י שתמלא הארץ דעה את ה' זה גופא יש להבין איך ימלאו דעה מצד עצמם כו' ואם אנו מבקשים<sup data-n=\"682\">16</sup> אתה חונן לאדם דעת כו' חונן הדעת וכן וחננו<sup data-n=\"683\">17</sup> מאתך חו\"ב<sup data-n=\"684\">18</sup> ודעת כו' דמשמע שיומשך מלמעלה בלי לימוד מרב כלל גם זה יש להבין איך יוכל להיות המשכה זו דדעת ולכל אדם בשוה כו' אך הנה באמת מ\"ש ידעו אותי אין ידיעה זו בהשגת שכל שא\"כ איך אמ' ידעו אותי דפי' אותי היינו אותי ממש שהו' לבחי' מהו\"ע ממש והרי אמ' דלמת\"ב כלל<sup data-n=\"685\">19</sup> (אפי' מחשבה דא\"ק<sup data-n=\"686\">20</sup> כו') אלא ידעו זה היינו ל' הכרה שיכירוהו ממש וזה אינו בא בהשגת שכל אלא ע\"י ראיה במהותו ועצמו' דוקא כאדם שיודע ומכיר לרעהו לפי שרואהו תמיד שייך בזה לומר ענין ידיעה עצמי' כמו רק אתכם ידעתי<sup data-n=\"687\">21</sup> כו' וכה\"ג אבל בהשגת שכל נק' שמיעה ודעת מרחוק ולא ידיעה והכרה מקרוב וע\"ז אנו מבקשים חונן הדעת שנדעהו ונכירהו בראי' במוה\"ע<sup data-n=\"688\">22</sup> כמו טעמו וראו<sup data-n=\"689\">23</sup> ממש כו' וכמ\"ש הנה אלקינו זה לנוכח כו'. וזה א\"צ לימוד כלל דהלימוד לא שייך רק בדבר המושג עפ\"י השכל והשגה כמו אאלפך חכמ'<sup data-n=\"690\">24</sup> ובל' תרגום נק' לימוד אולפנא<sup data-n=\"691\">25</sup> וכן לימודי ה'<sup data-n=\"692\">26</sup> כו' אבל בראי' מקרוב לא שייך ל' לימוד כלל אחר שמכיר ורוא' מהות אמיתת הדבר כמו שהוא דאינו דומה שמיעה לראי'<sup data-n=\"693\">27</sup> כלל כידוע לכך לע\"ל אמר כולם ידעו אותי שידעו ויכירו בראי' המהות כמו שהוא לאמיתתו אותי ממש שבזה לא שייך ל' לימוד איש לרעהו כלל ומ\"ש נדעה נרדפה<sup data-n=\"694\">28</sup> לדעת את ה' וכה\"ג היינו בבחי' דעת והשגה אלקי' בנשמו' שנהנין בהשגת אלקו' בג\"ע (דאימא מקננא בכורסייא<sup data-n=\"695\">29</sup> בחי' בינה שבמל' דאצי') שאין זה בחי' ראי' המהות אבל לע\"ל ידעו אותי ע\"כ כולם ידעו בשוה מקטנם לגדולם דבהשג' שכל יש חילוק מדריגות בין גדול בדעת לקטן בדעת אבל בראי' במהות אין הפרש כלל בין גדול לקטן וז\"ש ומלאה הארץ דעה את ה' כולם בשוה כמים לים מכסים שכיסוי א' לכולם כו' וזה שאנו מבקשים וחננו ידיעת עצמותך מאתך דוק' כו' שאז יהיה כל אדם בשוה כמשל הרואי' במהות המלך שכולם מכירים ויודעים אותו מגדול עד קטן בשוה וכך היה במ\"ת דכתיב וכל העם רואים<sup data-n=\"696\">30</sup> כו' וכולם כא' הכירוהו מעין דלע\"ל עד שעל כל דיבור<sup data-n=\"697\">31</sup> כו' (רק שהיו רואי' את הנשמע<sup data-n=\"698\">32</sup> דהיינו ראי' החכמ' שבבינה לפ\"ע השגת כאו\"א כו' כמשי\"ת) והיינו מטעם הנ\"ל דאא\"ס כמו שהוא למעל' בהעל' העצמו' ממש יהי' למטה בלי חילוק כלל וכמ\"ש הנה אלקינו זה כאו\"א<sup data-n=\"699\">33</sup>",[["678","12","<b>בע\"ל</b>: כנצ\"ל: לע\"ל."],["679","13","<b>הנה אלקינו זה</b>: ישעי' כה, ט."],["680","14","<b>ולא ילמדו עוד</b>: ירמי' לא, לג [בדילוג. ושם: למקטנם ועד ? ראה גם לקמן לד, א הערה 19]."],["681","15","<b>ומלאה הארץ</b>: נסמן לעיל ב, א."],["682","16","<b>אנו מבקשים</b>: בתפלת שמו\"ע."],["683","17","<b>וחננו</b>: ראה גם לקמן קטו, א ובהנסמן לשם."],["684","18","<b>חו\"ב</b>: בסידור אדה\"ז: חכמה בינה."],["685","19","<b>דלמת\"ב כלל</b>: ת\"ז בהקדמה (יז, א)."],["686","20","<b>אפי' מחשבה דא\"ק</b>: ראה גם תו\"ח תולדות קמב, ב."],["687","21","<b>רק אתכם ידעתי</b>: עמוס ג, ב."],["688","22","<b>במוה\"ע</b>: נסמן לעיל ב, א."],["689","23","<b>טעמו וראו</b>: תהלים לד, ט."],["690","24","<b>אאלפך חכמ'</b>: איוב לג, לג [ושם: ואאלפך ? ראה לקמן נז, ב. הנסמן במאמרי אדה\"א ויקרא ח\"א ע' טו]."],["691","25","<b>לימוד אולפנא</b>: ראה תרגום עה\"פ שמובא בהערה הבאה."],["692","26","<b>לימודי ה'</b>: ישעי' נד, יג."],["693","27","<b>דאינו דומה שמיעה לראי'</b>: נסמן לעיל ט, ב."],["694","28","<b>נדעה נרדפה</b>: הושע ו, ג [ושם: ונדעה]."],["695","29","<b>דאימא מקננא בכורסייא</b>: נסמן לקמן קיב, ב."],["696","30","<b>וכל העם רואים</b>: יתרו כ, טו."],["697","31","<b>שעל כל דיבור</b>: שבת פח, ב."],["698","32","<b>רואי' את הנשמע</b>: ראה מכילתא ורש\"י יתרו כ, טו. הנסמן בתו\"ח נח נז, ד הערה 64."],["699","33","<b>כאו\"א מראה באצבע</b>: ראה תענית בסופה."]]],[2800530066,"מראה באצבע לנוכח כו' משא\"כ עכשיו אל מסתתר ויש בחינת עליה וירידה דא\"ח וא\"י כנ\"ל וד\"ל (וכן בענין הקבלה עתה הוא בסוד נסתר והלכה באה בהלבשה גשמיות ולע\"ל יבאו שניהם כא' ממש וזהו הלכה אותיות הכלה<sup data-n=\"700\">1</sup> כו' דלע\"ל יתגלה בכנ\"י עצמות המאור ולא יבא האור ושפע בבחי' השתלשלות דקו\"ח וזהו ולא ילמדו כו'):\n<b>ואחר</b> כל זה יובן ענין הספי' שהיא ממחרת השבת שהוא ביום ב' דפסח דוקא כנ\"ל דהנה יום א' דפסח הגם שנקרא מקרא קדש כשאר המועדים ולא קדש עצמו כשבת מ\"מ בענין א' נקרא שבת עד שיום ב' שלאחריו נקרא ממחרת השבת כנ\"ל להיות מבואר למעלה בענין עיקר השבת במדריגה הב' שבו שהיא בחי' עלי' דאו\"ח למוה\"ע<sup data-n=\"701\">2</sup> ממש וזהו כמו הנסים שנקרא נפלאות עד בחי' סדכ\"ס עצמו כנ\"ל וזה היה בליל א' דפסח בנסים עליונים שנק' נפלאות ומופתים דוקא כנ\"ל ובפרט בחצי הלילה במכות בכורות דכתיב ועברתי בעצמי כו' ויצאו ביד רמה באותות ומופתים כו' ואע\"פ שהיה נראה בעליל לעין כל מ\"מ ה\"ז היה מבחי' אור העצמות שנעלם בבחי' סדכ\"ס שלא נודע מהותו כלל רק מציאותו כנ\"ל בפי' אראנו נפלאות לע\"ל כו' ואמנם בחי' עלי' זו דאו\"ח אל העצמות ממש הוא הגורם מיד בחי' ירידה דאו\"י ג\"כ מאותו המדריגה דמהו\"ע ממש שיבא למטה ממש כנ\"ל בענין או\"ח דשבת שגורם ירידה דאו\"י שבחול כמ\"ש וקראת לשבת ענג כו' דהא בהא תליא ממש וזהו כניסים שבאו ביש גמור בדרכי הטבע דוקא כנ\"ל משום דאא\"ס שהוא למעלה מעלה עד כו' הוא עצמו ממש שיורד למטה מטה כו' כנ\"ל. וזהו ענין יום ב' דפסח שנקרא ממחרת השבת שהוא מחר דיום א' דפסח שהיה בבחי' עילוי דאו\"ח בנפלאות דמוה\"ע<sup data-n=\"702\">3</sup> כמ\"ש לעושה נפלאות לבדו דוקא הוא שיורד ממחרת השבת הזה שהוא יום הב' שמתחיל הספירה שהן נש\"ב שיורד האור מעצמות המאציל בבחי' או\"י בז' מדות דפנימית ע\"י וא\"א וכן בא\"ק עד ז' מדות העצמיי' דא\"ס עצמו עד שיומשך למטה מטה בז' מדות דבינה דאצילות שנקרא יש ומשם למדות דז\"א ומל' עד מל' דמל' דעשי' בבחי' התלבשות גמור בנש\"י שבגופים גם בז' מדות דנוגה שהן ז' מדות רעות דק\"נ להפכם לקדושה האלקי' כדי שיוכלו לקבל התורה בגשמיות דוקא כמו לא תרצח לא תנאף<sup data-n=\"703\">4</sup> כו' דהיינו כמו התלבשות הנסים שבדרך הטבע בהסתר גמור וכמו ימות החול שבא בפ\"מ במע\"ב ליש גמור אחר יום השבת דוקא כנ\"ל שזהו הכל בבחי' השגת המהות עכ\"פ מאחר שנתפס הדבר בטבע האנושי' שבזה יש יתרון מעלה על הנפלאות שלא נודע מהותם כנ\"ל ואמנם שניהם א' הוא ממש רק שזה בעלי' וזה בירידה והא בהא תליא והיינו הך ממש כמובן מכל הנ\"ל באורך וד\"ל:\n(יז) <b>אך</b> הנה<sup data-n=\"704\">5</sup> עדיין יש להבין למה נקרא ממחרת השבת דמשמע שיש בו יתרון מעלה על יום השבת עד שהשבת מקבל ממנו להיותו קודם בשרשו ע\"כ השבת כמו הכנה לפני בואו ולפי הנ\"ל אין בו יתרון",[["700","1","<b>הלכה אותיות הכלה</b>: פע\"ח (שער הנהגת הלימוד) שי\"ז. ראה מאמרי אדה\"א שמות ח\"א ע' סד? ויקרא ח\"א ע' קיא? דברים ח\"ד ע' א'תנט? נ\"ך ע' קנז ובהנסמן בהנ\"ל. תו\"ח בראשית לה, ד ובהערה 61."],["701","2","<b>למוה\"ע</b>: נסמן לעיל ב, א."],["702","3","<b>דמוה\"ע</b>: נסמן לעיל ב, א."],["703","4","<b>לא תרצח לא תנאף</b>: יתרו כ, יג."],["704","5","<b>אך הנה</b>: להבא להלן ראה הנסמן בריש הדרוש (ח, ב)."]]],[2800530067,"מעלה כלל דודאי אותו בחי' העליה דאו\"ח במוה\"ע<sup data-n=\"705\">6</sup> הוא עצמו שיורד באו\"י ולא למעלה מזה כלל דהיינו הך ממש כנ\"ל וא\"כ למה נקרא מחרת השבת וגם למה לא יתחילו הספי' מיום א' דפסח כו' והנה באמת יש להבין בענין הספי' למה הוכרח שיומשך זמן ז' שבועות מיום א' דפסח שהיה בו העליה דאו\"ח בנש\"י בתכלית עד יום מ\"ת שהיה בו בחי' הירידה דאו\"י בהתלבשות במצות גשמיי' הנגלות לנו כו' והרי משה אמר לפרעה דרך ג' ימים בלבד נלך<sup data-n=\"706\">7</sup> כו' אך הנה באמת במ\"ת הי' בחי' ראיה במוה\"ע ע\"ד שיהי' לע\"ל דכתיב ידעו אותי ממש כנ\"ל באריכות שזהו גילוי העלם העצמות למעל' ולמטה בשוה ממש ולא יש בחי' עלי' וירידה כלל כנ\"ל ולפי המובן מענין הספי' הרי הי' עלי' ביום א' דפסח והספי' הוא בחי' ירידה כו' כשבת וחול (וכקבלה והלכה או כנסים שנק' נפלאות ונסים שבטבע כנ\"ל) וגם הרי במ\"ת הי' ב' דברים הפוכים מן הקצה לקצה שהוא תכלית המעלה בראיה המהות כמו לע\"ל דכתיב וכל העם רואים כו' וגם תכלית ההשפלה וירידה שהוא בחי' ההתלבשות בדברים גשמיים דוקא כנ\"ל ואם מפני שזהו כמו לע\"ל שמעלה ומטה שוין כנ\"ל ע\"כ יבא האור העצמות בהתלבשות ביש גמור שזהו בחי' השגת המהות עכ\"פ ואין היש מסתיר כלל כנ\"ל שהרי במ\"ת בא הציווי בבחי' יש גמור דטו\"ר דנוגה הנפרד ממש כו' וד\"ל. אך הנה כ\"ז יובן בהקדים ענין קריעת ים סוף תחלה שהי' בו מעין דלע\"ל בגלוי העלם העצמות עד שראתה שפחה כו' כנ\"ל וזה הי' בז' ש\"פ<sup data-n=\"707\">8</sup> דוקא (שהוא יום הששי לספי' כידוע) דהנה ידוע דקריעת י\"ס היה עיקר הכנה למ\"ת<sup data-n=\"708\">9</sup> דוקא ולא לטבוע מצרים בלבד<sup data-n=\"709\">10</sup> שזה היה דרך אגב בלבד ולכאורה מה שייך הליכה בי\"ס למ\"ת אך יש להקדים תחלה מ\"ש במ\"א על מ\"ש ששת ימים תאכל מצות<sup data-n=\"710\">11</sup> וביום השביעי עצרת לה' אלקיך ואמרז\"ל מה שביעי רשות<sup data-n=\"711\">12</sup> אף ו' ימים כו' דהנה יפלא זה שאמר דיום השביעי עצרת לה' כו' מהו ענין עצרת ביום זה להוי' אלקיך דוקא יותר מששת ימים שקדמו אליו כו' והנה כללות ענין קי\"ס ידוע על מ\"ש הפך ים ליבשה<sup data-n=\"712\">13</sup> כו' שזהו בחי' גלוי ההעלם דעלמא דאתכסיא הוא שנקרא ים ועלמא דאתגליא<sup data-n=\"713\">14</sup> נקרא ארץ<sup data-n=\"714\">15</sup> ויבשה וכמ\"ש בזוהר ותראה היבשה עלמא דאתגליא<sup data-n=\"715\">16</sup> כו' דהנה נס דקי\"ס הי' בדרך כללו' כל ההשתלשלות שאינו בא רק בבחי' העלם וגלוי שנק' סובב וממלא בכלל וישנו דרך פרט עד למטה מטה בבחי' עו\"ע דרוחניות וגשמיות שלמטה בגידול הדצח\"מ מן המזלות וכה\"ג ונק' זה בשם ים ויבשה בחי' העלם וגלוי שבכלל ובפרטי פרטו' דהנה ידוע שבחי' הדיבור נק' עלמא דאתגליא<sup data-n=\"716\">17</sup> והוא בחי' ה\"א תתא' בה\"א בראם בה\"א מוצאות הפה<sup data-n=\"717\">18</sup> העליון שבדבר ה' כו' וברוח פיו<sup data-n=\"718\">19</sup> כמו בי' מאמ' יהי אור יהי רקיע<sup data-n=\"719\">20</sup> וכל פרטיהם כידוע ונק' מאמר פתוח ובחי' המחשבה העליונה שמקפת לאותיות הדיבור נק' מאמר סתום<sup data-n=\"720\">21</sup> שהוא בהעלם כי א\"א שיבא אמיתית המחשבה בגלוי הדיבור רק נשאר בהעלם ומקיף לדיבור כידוע וזהו הנק' ים העליון והדיבור נק' ארץ עלאה והן ב' עולמים כמ\"ש מן העולם<sup data-n=\"721\">22</sup> כו' דמ\"ש תראה היבשה היינו שהי' היבש' תחלה כלול' בים ואח\"כ אמר",[["705","6","<b>במוה\"ע</b>: נסמן לעיל ב, א."],["706","7","<b>דרך ג' ימים. . נלך</b>: וארא ח, כג. שמות ה, ג. ג, יח."],["707","8","<b>קריעת ים סוף. . בז' ש\"פ</b>: נסמן לקמן צז, א."],["708","9","<b>דקריעת י\"ס. . הכנה למ\"ת</b>: ראה מאמרי אדה\"ז על פרשיות התורה ח\"א ע' רנה וע' רס. ע' רסז. תקס\"ז ע' מד וע' מה. תו\"א בשלח סג, א. לקו\"ת צו יז, א. מאמרי אדה\"א ויקרא ח\"א ע' קמז וע' רפד. דברים ח\"א ע' יח ובהנסמן בהנ\"ל. לקמן פג, ב."],["709","10","<b>ולא לטבוע מצרים בלבד</b>: ראה גם מאמרי אדה\"ז על פרשיות התורה ח\"א ע' רנה וע' רסז. לקמן פג, ב."],["710","11","<b>ששת ימים תאכל מצות</b>: פ' ראה טז, ח. ראה סידור שחה\"מ רפה, ג ואילך."],["711","12","<b>מה שביעי רשות</b>: פסחים קכ, א. מכילתא ורש\"י בא יב, טו. שו\"ע אדה\"ז הל' פסח סתע\"ה סל\"ב."],["712","13","<b>הפך ים ליבשה</b>: תהלים סו, ו."],["713","14","<b>עלמא דאתכסיא. . דאתגליא</b>: ראה זהר בראשית יח, א. ויצא (ס\"ת) קנב, א. קנח, ריש ע\"ב. ת\"ז בהקדמה (א, סע\"א ואילך)."],["714","15","<b>דעלמא דאתכסיא. . ים. . דאתגליא. . ארץ</b>: ראה גם לקמן פד, סע\"א ואילך. צו, ב. מאמרי אדה\"א שמות ח\"א ע' חצר. וש\"נ. הנחות תקע\"ז ע' נה. וש\"נ."],["715","16","<b>ותראה היבשה עלמא דאתגליא</b>: בראשית א, ט. ראה זהר בראשית יח, א. מאמרי אדה\"א קונטרסים ע' רכד. וש\"נ."],["716","17","<b>הדיבור נק' עלמא דאתגליא</b>: ראה שהיחוה\"א פי\"א. תו\"ח ויצא קסח, ג ובהערה 24. שע\"ת ח\"ב צא, ב."],["717","18","<b>בה\"א בראם. . הפה </b>: בראשית ב, ד. ראה מנחות כט, ב. ב\"ר פי\"ב, ב. שע\"ת שם צא, רע\"ג."],["718","19","<b>שבדבר ה'. . פיו</b>: תהלים לג, ו."],["719","20","<b>יהי אור יהי רקיע</b>: בראשית א, ג. ו."],["720","21","<b>מאמר פתוח. . סתום</b>: נסמן לקמן קלט, א."],["721","22","<b>מן העולם</b>: נסמן לקמן פד, ב."]]],[2800530068,"יקוו המים<sup data-n=\"722\">1</sup> לצד אח' ותראה היבשה וכמ\"כ בים ויבשה העליונים מחשבה ודבור העליון הי' בחי' הדבור כלול בהעלם המחשב' עליונ' ואח\"כ צוה שיקוו מים העליונים ותראה היבשה בחי' הדבור העליון והן המאמר שאמר לארץ דוקא תוציא הארץ<sup data-n=\"723\">2</sup> עלאה מאין ליש כל הברואים עליונים כעוף<sup data-n=\"724\">3</sup> זה מיכאל<sup data-n=\"725\">4</sup> כו' ונפש חי' דבהמות וחיות פני ארי' ופני שור<sup data-n=\"726\">5</sup> כו' וכידוע ומבואר במ\"א ועד\"ז נקרא ים ויבשה עד רום המעלות דהיינו בכללות הכל הוא בחי' העלם העצמות ממש שלפני הצמצום הראשון נקרא ים הקדמוני כו' ואחר הצמצום שבא לבחי' גלוי דקו\"ח כו' נקרא יבשה וע\"ז אמר יקוו המים העליונים מתחת השמים דהיינו בחי' טה\"ע<sup data-n=\"727\">6</sup> כו' ואמנם בירידת האור ושפע בהשתלשלות בפרטיות הרי כל עילה ועלול בפרט שבקו\"ח באבי\"ע בירידתו עד מל' דמל' דעשי' בפו\"מ נקרא כל עילה בשם ים והעלול בשם יבשה שכל עילה מקפת לעלול ותחלה הי' כלול בו ויצא לגלוי מן ההעלם דעילה שלו כמו כל משפיע ומקבל כרב ותלמיד שמקבל השפע אינו רק בחי' גלוי אפס קצהו דמשפיע ועצם השפע שבמשפיע הוא בבחי' העלם ומקיף כידוע וכך נשתלשל מעילה לעלול בכל קו\"ח באבי\"ע בע\"ס כו' עד היותר סוף במדריגה במל' דעשי' שהוא מקור התהוות המלאכים דעשיה והן יורדים ונמשכים ג\"כ מעילה לעלול וכמ\"ש וקרא זא\"ז ותרגומו ומקבלין<sup data-n=\"728\">7</sup> דין מן דין ונק' המשפיע בחי' העלם והמקבל העלול בחי' גלוי כים ויבשה כנ\"ל עד גם באחרון שבכולם שהוא השפעת שפע גשמיות דדצ\"ח מרוחניות דמזלות<sup data-n=\"729\">8</sup> עד שאין לך כל עשב<sup data-n=\"730\">9</sup> שאין לו מזל המגדלו וכמגד תבואת שמש<sup data-n=\"731\">10</sup> כו' כידוע ה\"ז ג\"כ בא בדרך עו\"ע משפיע ומקבל ע\"ד הנ\"ל ממש בים וביבשה בכללות הכל וד\"ל דגבוה מעל גבוה<sup data-n=\"732\">11</sup> כו' הכל באופן א' מראש לסוף הכל כל א' נקרא העלם לגבי התחתון המקבל הימנו כידוע וכמ\"כ נק' בשם בחי' סובב וממלא בכללות הכל היינו עצמות א\"ס שלפני הקו וחוט הוא שנק' סובב כללי להקיף הכל וקו\"ח נק' ממלא כללי דאבי\"ע כו' ועד\"ז יורד בהשתלשלות בדרך פרט בכל עו\"ע שנקרא סובב וממלא דרך פרטי פרטיות עד עולם השפל הזה הוא כמו שמים וארץ דשמים והמזלות נק' משפיעים לארץ<sup data-n=\"733\">12</sup> וכמ\"כ הים דומה לרקיע<sup data-n=\"734\">13</sup> כו' הרי השמי' כמו מקיפי' וסובבי' לארץ כו' וכידוע ומבוא' במ\"א וד\"ל והנה כאשר הפך ים ליבשה למטה בגשמיו' דים ויבשה שלמט' כמ\"כ נעש' עד רום המעלו' בכל עו\"ע הרוחני' העליו' עד רום המעלו' בכללו' הכל כנ\"ל הרי נעש' מן בחי' ההעל' גלוי כמו בחי' המחש' עליונ' שנק' ים העליון נעש' ונהפך לגלוי דדבור שנק' ארץ ויבש' למעל' וכך בכל עו\"ע משפיע ומקבל בפרט נעש' מהעל' דמשפי' בחי' גלוי ממש כו' מאחר שהי' שינוי ממש בצירוף דים למט' שנהפך לצירו' דיבש' למטה כמ\"ש הפך ים ליבשה א\"כ ודאי היה שינוי כזה ממש עד רום המעלות גם בכללות הכל עד בחי' העלם המקיף הכללי דעצמות א\"ס ב\"ה שנתגלה בבחי' קו\"ח שזהו מים העליון ליבשה בכללות וכך במחשבה ודבור דאצי' עד בחי' העלם וגלוי שלמטה ממש ומובן מזה שכאשר נתגלה עצם ההעלם דמחשבה ממילא אין מקום אז לגלוי דדבור ומתבטל מאליו כי אין מקום לדיבור בפה כ\"א כאשר המחשבה",[["722","1","<b>יקוו המים</b>: בראשית א, ט. ראה גם סה\"מ תקס\"ו ע' קמה ואילך."],["723","2","<b>תוציא הארץ</b>: בראשית א, כד."],["724","3","<b>תוציא הארץ. . כעוף</b>: ראה חולין כז, ב. רש\"י בראשית ב, ח. יט. מאמרי אדה\"א הנחות תקע\"ז ע' צח."],["725","4","<b>כעוף זה מיכאל</b>: ראה בראשית א, כ. זהר שם מו, ב. מאמרי אדה\"א קונטרסים ע' שעו. וש\"נ. תו\"ח בראשית יט, א ובהערה 5."],["726","5","<b>תוציא. . פני ארי' ופני שור</b>: יחזקאל א, י. ראה תו\"ח ח\"ש קל, ג ובהערה 32. מאמרי אדה\"א הנחות תקע\"ז שם."],["727","6","<b>בחי' טה\"ע</b>: ראה גם לקמן קיד, ב."],["728","7","<b>וקרא. . ומקבלין</b>: ישעי' ו, ג ובת\"י שם."],["729","8","<b>השפעת שפע. . דמזלות</b>: ראה גם מאמרי אדה\"א במדבר ח\"א ע' לג. דברים ח\"ב ע' תקנב."],["730","9","<b>שאין לך כל עשב</b>: נסמן לקמן קמו, א."],["731","10","<b>וכמגד תבואת שמש</b>: ראה ברכה לג, יד."],["732","11","<b>דגבוה מעל גבוה</b>: קהלת ה, ז."],["733","12","<b>דשמים. . משפיעים לארץ</b>: ראה סידור ש' הל\"ג בעומר שג, א. שע\"ת כ, א. תו\"ח בראשית כא, ג. לקמן לד, ב."],["734","13","<b>הים דומה לרקיע</b>: סוטה יז, א."]]],[2800530069,"בהעלם ולא באה בגלוי הדיבור רק אפס קצהו אבל כאשר עצם העלם המחשבה נתגלה בטל הדיבור ממילא כו' וכך הוא עד רום המעלות ולזה אמר ואתם תחרישון ואיתא בזוהר לא תתערו מידי<sup data-n=\"735\">14</sup> פי' בדיבור בצלותא לא תתערו כלל רק תחרישון לגמרי לפי שבגלוי ההעלם העצמות אין מועיל שם העלאת מ\"ן דדבור בתפלה בלחש גם כן רק תחרישון בשתיקה וביטול במציאות לגמרי מכל וכל כי הרי נתגלה מה שלמעלה מבחי' הדיבור שאין הדיבור מגיע שם כלל אלא ה' ילחם לכם<sup data-n=\"736\">15</sup> פי' הוי' עצמו ילחם לכם שזהו מבחי' סובב הכללי כנ\"ל שלמעלה מכל הגלוי דהשתלשלות ואתם תחרישון שלא להעלות אתדל\"ת כמ\"ש אדני שפתי תפתח<sup data-n=\"737\">16</sup> שאין כח לדיבור כלל בשעה שהמלך בעצמו מתגלה כידוע וז\"ש הים ראה וינוס<sup data-n=\"738\">17</sup> כו' שגם הים בא בירידת המדריג' מעצמותו להיות רק בבחי' יבשה שהוא הגלוי מצד שנגלה כל מהו\"ע ממש שלמעלה מבחי' סובב וממלא בכלל דבחי' סובב ג\"כ אינו רק להיות מקיף להשתלשלות דאבי\"ע וכמ\"ש גאות לבש<sup data-n=\"739\">18</sup> כו' וכמו שאנו או' המלך המרומ' לבדו<sup data-n=\"740\">19</sup> לבדו ממש טרם שבא להיות מתנשא מימות עולם שהוא נקרא סובב כ\"ע כו' (וכמ\"ש במ\"א עמ\"ש כי גאה גאה כו' אגוסטוס יושב<sup data-n=\"741\">20</sup> ומלך עומד כו'. ויתבאר בסמוך בענין אז ישיר משה<sup data-n=\"742\">21</sup> ובני ישראל כו') וזהו מ\"ש בשירת הים עד יעבור עמך ה' פי' שעבר למעלה משם הוי\"ה<sup data-n=\"743\">22</sup> דהנה ידוע דד' אותיות דשם הוי\"ה כולל כל ההשתלשלות דקו\"ח שבאבי\"ע יו\"ד באצי' ה\"א בבריאה וי\"ו ביצירה ה\"א בעשיה<sup data-n=\"744\">23</sup> וקוצו ש\"י<sup data-n=\"745\">24</sup> בע\"י וא\"א עד א\"ק כו' ולמעלה משם הויה בכלל היינו בחי' הארת סובב כ\"ע הכללי שהוא בחי' עצמות אא\"ס ממש שלפני הצמצום דקו\"ח שבא בבחי' גלוי מן ההעלם לפי שנתגלה ממהו\"ע ממש שע\"כ אמר הים ראה וינוס כו' דהעלם וגלוי שוין לגבי עצמותו ממש מאחר שהו' נבדל בערך לגמרי מכל עיקר השתלשלות דסובב וממלא כמ\"ש גאה גאה כו' בחי' יחיד ונק' מלך מרומם לבדו שהוא התנשאות שמצד עצמותו ממש שנבדל בערך מהתנשאות על ימו\"ע כו' וזהו שאמר עד יעבור ל' עתיד מפני שעיקר זה הגלוי יהיה לע\"ל שיתגלה מהו\"ע ממש וז\"ש עד יעבור סתם<sup data-n=\"746\">25</sup> שלא נזכר שם הויה כלל ואמנם בקי\"ס היה מעין דלע\"ל ששם אמר נשמחה בו<sup data-n=\"747\">26</sup> ממש (כמשי\"ת) ע\"כ אמר גם כאן עד יעבור עמך ה' למעלה משם הוי\"ה כמ\"ש כימי צאתך מא\"מ אראנו נפלאות כו' וכנ\"ל וד\"ל:\n(יח) <b>וזהו</b> שאמרז\"ל ראתה שפחה על הים מה שלא ראה יחזקאל כו' דהנה מבואר למעלה בשרש בחי' השתלשלות שהוא רק בחי' העלם וגלוי בכל עו\"ע בפרט וכמ\"כ בדרך כללות עד למטה בשרש הד' יסודות כו' שנקרא רוחניות וגשמיות בחי' הרוחניות בהעלם והגשמיות דהרכב' ד' יסודות ודצח\"מ בגלוי ויובן מזה עד רום המעלות עד לפני האצי' בהעלם וגלוי שבכללות וכאשר הפך ים ליבשה למטה זהו מצד שנגלה אז מבחי' העצמות ממש דקמיה ממש כחשיכה כאורה העלם וגלוי שוין ע\"כ ההעלם דים נהפך לגלוי דיבשה וז\"ש הים ראה וינוס כו' וכך היה עד רום המעלות כנ\"ל לפי שכל עיקר ענין העלם וגלוי לא יתכן רק בבחי' ההמשכ' וההתפשטות",[["735","14","<b>ואתם תחרישון. . לא תתערו מידי</b>: בשלח יד, יד. ראה זהר בשלח מז, ב. סה\"מ תרל\"ד ע' קיח."],["736","15","<b>ה' ילחם לכם</b>: בשלח שם."],["737","16","<b>אדני שפתי תפתח</b>: תהלים נא, יז. ראה מאמרי אדה\"א קונטרסים ע' שז. וש\"נ. תו\"ח בראשית כא, ב ובהערה 21."],["738","17","<b>הים ראה וינוס</b>: תהלים קיד, ג."],["739","18","<b>גאות לבש</b>: תהלים צג, א."],["740","19","<b>המלך המרומ' לבדו</b>: ברכת יוצר."],["741","20","<b>כי גאה. . אגוסטוס יושב</b>: בשלח טו, א. שמו\"ר רפכ\"ג. ראה מאמרי אדה\"ז על פרשיות התורה ח\"א ע' רפו וס\"ע רצא. תקס\"ה ח\"א ע' רלו ואילך וע' רמד. תו\"א מקץ מ, ב. לקו\"ת בשלח ב, ד. להלן עו, א. מאמרי אדה\"א בראשית ע' תכז. דברים ח\"ג ע' א'מט. נ\"ך ע' תיח."],["742","21","<b>אז ישיר משה</b>: ראה לקמן לו, א ואילך."],["743","22","<b>עד יעבור. . למעלה משם הוי\"ה</b>: בשלח טו, טז. ראה סידור כאן רפה, ד. סה\"מ תקס\"ה שם ע' רמו."],["744","23","<b>יו\"ד באצי'. . בעשיה</b>: ראה ע\"ח (שער סדר אצי') ש\"ג פ\"א. לקו\"ת להאריז\"ל בראשית עה\"פ (ג, כג) וישלחהו ה\"א. הנסמן במאמרי אדה\"א דברים ח\"ד ע' א'תצא? תו\"ח ח\"ש קכח, ב הערה 21."],["745","24","<b>וקוצו ש\"י</b>: ראה זהר ויקרא י, ב. ע\"ח שם. הנסמן במאמרי אדה\"א קונטרסים ע' תכז."],["746","25","<b>עד יעבור סתם</b>: ראה גם לעיל לא, א."],["747","26","<b>נשמחה בו</b>: תהלים סו, ו."]]],[2800530070,"שיתכן בזה ענין סובב וממלא מקיף ופנימי שזהו העלם וגלוי כידוע אבל בבחי' העצמות ממש שהוא למעלה מעלה מבחי' השפעה והמשכה עדיין רק כמו שהוא לבדו יחיד כו' כנ\"ל העלם וגלוי דהיינו סובב וממלא בכלל ובפרט עד רוחניות וגשמיות למטה שוין בלי הפרש כלל בין רוחניות שפע המזלות לגשם הד\"י העלולים מהם כו' (וזהו בשמים ממעל ועל הארץ מתחת אין עוד<sup data-n=\"748\">1</sup> בשוה וכן השמים וארץ אני מלא<sup data-n=\"749\">2</sup> בשוה וכן מ\"ש אם אסק שמים<sup data-n=\"750\">3</sup> כו' וכן מ\"ש איהו תפיס בכ\"ע<sup data-n=\"751\">4</sup> ולמדת\"ב גם לאחר השתלשלות דאבי\"ע זהו הוראה גמורה אל עצמותו שמובדל ומרומם לבדו כו') והנה ענין הנבואה ידוע שהוא רק בחי' גלוי אלקות מן ההעלם והיינו מבחי' מל' דאצי' שמאיר בבי\"ע ע\"י מסך וצמצום דשם אלקים המעלים ומסתיר כו' כמ\"ש כי שמש ומגן<sup data-n=\"752\">5</sup> הוי' אלקים וכמ\"ש באורך נראה אור<sup data-n=\"753\">6</sup> כאור של תולדה כידוע וכמו נבואת יחזקאל היה בבחי' נו\"ה דיצירה<sup data-n=\"754\">7</sup> שזהו אחר המסך שבין בריאה ליצירה<sup data-n=\"755\">8</sup> שממל' דבריאה נעשה כתר דיצירה<sup data-n=\"756\">9</sup> כו' ונבואת ישעיה מנו\"ה דבריאה<sup data-n=\"757\">10</sup> וכה\"ג נבואה דמשה בנו\"ה דז\"א<sup data-n=\"758\">11</sup> דאצי' אבל עצמות ומהות המאציל לא בא לידי גלוי גם למשה וכמ\"ש לו ופני לא יראו<sup data-n=\"759\">12</sup> וגם שבנבואה דמשה היה פא\"פ<sup data-n=\"760\">13</sup> ונתנבא בזה<sup data-n=\"761\">14</sup> לנוכח כו' ועד\"ז היה ענין גלוי שכינה בהיכל ק\"ק שזהו ממל' דאצי' עצמו כידוע שכ\"ז אינו ממהו\"ע ממש אלא<sup data-n=\"762\">15</sup> רק בחי' התפשטות האור בלבד שיתכן בזה בחי' העלם וגלוי שבא בחילוק מדרגות דאבי\"ע לנביאים וכל בחי' גלוי אור שפע האלקי' כמו בנסים ונפלאות שבמצרים וכה\"ג וכמו בתחה\"מ דאליהו וכו' (וכן בכל שבת וי\"ט ובכל ר\"ח שעולין הנשמות<sup data-n=\"763\">16</sup> מג\"ע התחתון לג\"ע העליון שזהו עליי' מן הגלוי שבעולם התחתון להעלם שבעליון הימנו וכך יש ירידות והמשכות מעליון לתחתון במועדי הוי' ובשבת וביחודים שבמ\"ע וכה\"ג) ואמנם בשעת קי\"ס שנתגלה עליהם מבחי' מהו\"ע ממש כנ\"ל שזהו למעלה מבחי' התפשטות והמשכה כלל ה\"ז למעלה גם מבחי' הנבואה וכה\"ג וע\"כ גם שפחה ראתה על הים כו' ולא שראתה בדרך נבואה אלא רק מצד עוצם בחי' גלוי העצמות דא\"ס ב\"ה דקמיה כחשיכה כאורה רוחניות וגשמיות שוין ממש ע\"כ גם השפחה ראתה מה שלא ראה יחזקאל<sup data-n=\"764\">17</sup> בדרך הנבואה מאחר שהנבואה אינו מבחי' מהו\"ע כלל רק גלוי ההעלם שבעליון ובקי\"ס היה הארה דעצמות ממש שכולן שוין לקבל שם כמ\"ש גם חשך לא יחשיך<sup data-n=\"765\">18</sup> כו' להיותו נבדל בערך מבחי' התפשטות כו' קטן וגדול שוין ממש בלי הפרש כלל וכלל וכמ\"ש בשמים ממעל ועל הארץ כו' וד\"ל (וכדוגמא זו לע\"ל דכתיב כולם ידעו אותי בדעת והכרת מהו\"ע שזה שוה בקטן וגדול כמ\"ש מקטנם<sup data-n=\"766\">19</sup> כו' וכן הבהמות וחיות כמ\"ש וגר זאב עם כבש ופרה ודוב<sup data-n=\"767\">20</sup> כו' לא ירעו ולא ישחיתו<sup data-n=\"768\">21</sup> כו' מצד בחי' הביטול האלקי בכל הברואים כמו שאומרים ובכן תן פחדך<sup data-n=\"769\">22</sup> על כל מעשיך ואימתך על כו' ויראוך כל המעשים וכו' לפי שידע ויכיר כל פעול כי אתה פעלתו ויבין כל יצור כו' וחמורו של רפב\"י<sup data-n=\"770\">23</sup> יוכיח כידוע וד\"ל):\n<b>ובכ\"ז</b> יובן מ\"ש בשירת הים אשירה לה'<sup data-n=\"771\">24</sup> כי גאה גאה כו' ויש לדקדק למה אמר ב\"פ גאה גאה כו' ומה שייך זה לקי\"ס דוקא וגם מה שאמר סוס ורוכבו רמה בים דמשמע שזהו משום דגאה גאה",[["748","1","<b>בשמים ממעל. . אין עוד</b>: ואתחנן ד, לט."],["749","2","<b>השמים והארץ אני מלא</b>: ירמי' כג, כד [ושם: ואת הארץ ? ראה הנסמן לשע\"ת ח\"א יד, ג]."],["750","3","<b>אם אסק שמים</b>: תהלים קלט, ח."],["751","4","<b>איהו תפיס בכ\"ע</b>: נסמן לקמן קטו, ב."],["752","5","<b>כי שמש ומגן</b>: תהלים פד, יב."],["753","6","<b>באורך נראה אור</b>: תהלים לו, י. ראה לקמן קמד, ב ובהנסמן במ\"מ שם."],["754","7","<b>נבואת יחזקאל. . נו\"ה דיצירה</b>: ראה גם לקמן קמה, ב ובהנסמן לשם."],["755","8","<b>המסך שבין בריאה ליצירה</b>: נסמן לקמן קטז, א."],["756","9","<b>שממל' דבריאה נעשה כתר דיצירה</b>: נסמן לקמן קמה, ב."],["757","10","<b>ונבואת ישעי' מנו\"ה דבריאה</b>: נסמן לקמן קמה, ב."],["758","11","<b>נבואה דמשה בנו\"ה דז\"א</b>: ראה שהיחוה\"א פ\"ה. אגה\"ק סי\"ט. לקו\"ש שמות כרך ו ע' 251 ואילך. וש\"נ. לקמן צד, א."],["759","12","<b>ופני לא יראו</b>: תשא לג, כג."],["760","13","<b>פא\"פ</b>: תשא שם, יא."],["761","14","<b>ונתנבא בזה</b>: ספרי ר\"פ מטות הובא ברש\"י שם."],["762","15","<b>אלא</b>: ניתוסף ע\"פ דפו\"ר."],["763","16","<b>בכל שבת. . שעולין הנשמות</b>: ראה זהר תרומה קנו, סע\"ב. מאמרי אדה\"א נ\"ך ע' תסז. וש\"נ. לקמן קה, ריש ע\"ב."],["764","17","<b>שפחה ראתה. . נבואה. . יחזקאל</b>: ראה גם מאמרי אדה\"א ויקרא ח\"א ע' שכב ואילך."],["765","18","<b>גם חשך לא יחשיך</b>: תהלים קלט, יב."],["766","19","<b>כולם ידעו אותי. . מקטנם</b>: ירמי' לא, לג [ושם: למקטנם ? ראה לעיל לא, ב. שע\"ת ח, ב. תו\"ח שמות נג, א. מאמרי אדה\"א דברים ח\"ג ע' תשמו]."],["767","20","<b>וגר זאב. . ופרה ודוב</b>: ישעי' יא, ו. ז."],["768","21","<b>לא ירעו ולא ישחיתו</b>: ישעי' יא, ט. סה, כה."],["769","22","<b>ובכן תן פחדך</b>: תפלת העמידה לימים נוראים [בדילוג]. ראה גם לקמן מה, ב. הנסמן בתו\"ח נח עה, ד בהערה 41? מאמרי אדה\"א הנחות תקע\"ז ע' קסח."],["770","23","<b>וחמורו של רפב\"י</b>: חולין ז, סע\"א ואילך. ראה מאמרי אדה\"א ויקרא ח\"ב ע' תשסו. וש\"נ. שע\"ת ח\"א ח, א ובהנסמן במ\"מ לשם."],["771","24","<b>אשירה לה'</b>: בשלח טו, א."]]],[2800530071,"דוקא כו' והנה יש להקדים תחלה לבאר ענין המחלוקת הנזכר בגמרא<sup data-n=\"772\">25</sup> אם שמים קדמו לארץ או ארץ קדמה לשמים והמכריע אומר ששמים וארץ כאחד נבראו שנאמר קורא אני אליהם<sup data-n=\"773\">26</sup> יעמדו יחדיו כו' והנה מ\"ד שמים קדמו לארץ היינו משום שנאמר בראשית ברא שמים<sup data-n=\"774\">27</sup> ואח\"כ ארץ ומ\"ד ארץ קדמה משום שנאמר ביום עשות ה' אלקים ארץ<sup data-n=\"775\">28</sup> ואח\"כ שמים וידוע ששניהם אמת דמ\"ד שמים קדמו לארץ היינו לפי שבסדר ההשתלשלות מעצמו' המאציל והבורא כו' מלמעלה למטה שמים קדמו שהוא מ\"ש בראשית ברא שמים כו' והענין הוא כידוע ששמים וארץ למטה היינו כמו משפיע ומקבל<sup data-n=\"776\">29</sup> ממש כמ\"ש אני אענה את השמים<sup data-n=\"777\">30</sup> והם יענו את הארץ ופי' יענו לשון השפעה<sup data-n=\"778\">31</sup> והוא כל שפע רוחניות דמזלות שבשמים שמשפיעים לארץ להוציא צמחה וכל חלקי ד\"י ודצח\"מ וכל אשר בארץ הכל בחינת מקבל והמשפיע ודאי קדם למקבל ע\"כ גזר אומר דשמים קדמו לארץ וכך הוא עד רום המעלות בכל עו\"ע משפיע ומקבל ברוחניות דגבוה מעל גבוה כו' עד מל' דאצי' נקרא ארץ וז\"א נקרא שמים וכמ\"ש השמים כסאי<sup data-n=\"779\">32</sup> והארץ הדום רגלי כידוע ועד\"ז גם במקור האצי' בשמים ושה\"ש העליונים יותר שהוא בחי' טה\"ע וטה\"ת<sup data-n=\"780\">33</sup> שנק' סובב בכלל ובחי' קו\"ח שאחר הצמצום בחי' ממכ\"ע בכלל שבודאי המשפיע קדם למקבל וז\"ש בראשית שזהו בראשית ההמשכ' מן העצמות להיות בבחינת סובב וממלא הרי שמים תחלה ואח\"כ ארץ והיינו בראשית בחכמה או בקדמין<sup data-n=\"781\">34</sup> כמ\"ש בחכמה<sup data-n=\"782\">35</sup> כו' עד רום המעלות כשעלה ברצונו וחכמתו להאציל כו' כידוע וזהו לפי סדר ההשתלשלות מלמעלה למטה שנק' בחי' או\"י כידוע וד\"ל ומ\"ד ארץ קדמה לשמים היינו בבחי' או\"ח דוקא והענין הוא כידוע שסוף מעשה עבמ\"ת<sup data-n=\"783\">36</sup> דהיינו טרם שעלה ברצונו הפשוט ובחכמתו העצמי' כו' עלה סוף מעשה דוקא כשיהיה נברא יש מאין בארץ ויעשה חסד וצדקה ומע\"ט זהו שעוררו לרצון הפשוט כו' וא\"כ ארץ קדמה שהוא בחי' המקבל קדם למשפיע שנק' שמים (עד\"מ הידוע משפע הרב לתלמיד שקבלת התלמיד עולה ראשון במשפיע<sup data-n=\"784\">37</sup> שמזה יבא לכלל רצון להשפיע כו' וכמ\"ש במ\"א) וז\"ש שנתאוה ה' להיות לו דירה בתחתונים<sup data-n=\"785\">38</sup> דוקא והיינו מ\"ש ביום עשות ה' אלקים דוקא אז ארץ קדמה לשמים שזהו בגמר המעשה שזהו שעבמ\"ת כידוע (ומה שאמר בס\"י שנעוץ סופן בתחלתן<sup data-n=\"786\">39</sup> זהו רק כמו שנעוץ תחילתן בסופן שאין זה העילוי דבחי' או\"ח שעולה רק לתחלתן דאו\"י ולא למעלה מתחלתן אבל ענין ארץ קדמה לשמים היינו שחוזר לקדמות העצמות ממש כנ\"ל וד\"ל) ומ\"ד שמים וארץ כאחד נבראו היינו משום שיש מדריגה הג' שלמעלה משמים וארץ דמשפיע ומקבל והוא בחי' מהו\"ע דמאציל שנבדל בערך לגמרי מבחי' השפעה והמשכה עדיין כנ\"ל באורך דקמיה שוין ממש המשפיע עם המקבל בכלל ובפרט כו' משום דכלא חשיבי ממש ע\"כ שניהם שוין כו' וזהו טעם מ\"ד דס\"ל שמים וארץ כאחד נבראו שנאמר קורא אני אליהם יעמדו יחדיו פי' קורא אני שזהו מבחי' העצמות שיעלו שם במחשבתו בעצמות שניהם כאחד ממש מבלי קדימה לאחד על זולתו כלל מאחר שבעצמו מובדל ומרומם משניהם יחד כנ\"ל ע\"כ יעמדו יחדיו כו' בהשואה א' ממש מטעם הנ\"ל",[["772","25","<b>המחלוקת הנזכר בגמרא</b>: חגיגה יב, א. ראה סידור כאן רפו, א. תו\"ח ר\"פ ויגש ובהנסמן במ\"מ לשם."],["773","26","<b>קורא אני אליהם</b>: ישעי' מח, יג."],["774","27","<b>בראשית ברא שמים</b>: בראשית א, א [ושם: אלקים את השמים]."],["775","28","<b>ביום עשות ה' אלקים ארץ</b>: בראשית ב, ד."],["776","29","<b>שמים וארץ. . משפיע ומקבל</b>: ראה סידור כאן רפו, א. תו\"ח ויגש רל, ד. הנסמן לעיל לג, א הערה דשמים."],["777","30","<b>אני אענה את השמים</b>: הושע ב, כג [בהוספת תיבת ?אני\" ? ראה לקמן נג, א. מאמרי אדה\"א הנחות תקע\"ז ע' רכב. וש\"נ]."],["778","31","<b>יענו לשון השפעה</b>: ראה גם סידור שער ל\"ג בעומר שג, א. שע\"ת ח\"א כ, א. תו\"ח בראשית כא, ג."],["779","32","<b>השמים כסאי</b>: ישעי' סו, א."],["780","33","<b>בשמים ושה\"ש. . טה\"ע וטה\"ת</b>: ראה גם לקמן נח, ב. מאמרי אדה\"א שמות ח\"ב ע' שצה. וש\"נ."],["781","34","<b>בראשית בחכמה או בקדמין</b>: ראה תרגום ירושלמי ואונקלוס לבראשית א, א."],["782","35","<b>בחכמה</b>: משלי ג, יט."],["783","36","<b>שסוף מעשה עבמ\"ת</b>: ע\"פ פיוט לכה דודי."],["784","37","<b>שקבלת התלמיד. . במשפיע</b>: ראה גם תו\"ח ויגש רל, ב."],["785","38","<b>שנתאוה. . דירה בתחתונים</b>: תניא רפל\"ו. וראה הנסמן בליקוט פירושים לשם."],["786","39","<b>שנעוץ סופן בתחלתן</b>: ראה ס\"י פ\"א מ\"ז."]]],[2800530072,"וד\"ל:\n<b>(אך</b> הנה עדיין אינו מובן מ\"ש כאחד נבראו איך שייך לשון בריאה במשפיע ומקבל יחד כו' וכן מ\"ש הללו את ה'<sup data-n=\"787\">1</sup> מן השמים כו' עד כי הוא צוה ונבראו ובהללו מן הארץ מסיים כי נשגב שמו לבדו הודו על ארץ ושמים ארץ קדמה לשמים כו') דהנה ידוע שיש ב' מדריגות בע\"ס א' ע\"ס דאו\"י שכתר קודם לכולן והב' ע\"ס דאו\"ח<sup data-n=\"788\">2</sup> שהמל' קוד' ולמעלה משניהם הוא מ\"ש קורא אני כו' כמו קורא הדורות מראש<sup data-n=\"789\">3</sup> כו' דלשון קריאה היינו בחי' המשכה מן ההעלם דעצמות לגלוי בלב' וז\"ש קורא אני כו' יעמדו יחדיו ע\"ס דאו\"י ואו\"ח כו' והענין הוא כידוע בענין אנת הוא חד<sup data-n=\"790\">4</sup> ולא בחושבן י\"ס כו' דלאו מכל אינון מדות כלל ע\"כ שניהם כאחד יבואו מבלי קדימה לאחד על זולתו שזהו מבלי שימצא ראש וסוף<sup data-n=\"791\">5</sup> כמשל העיגול שאין בו מעלה ומטה<sup data-n=\"792\">6</sup> כלל ומה שנמצא ראש וסוף היינו בקו הנמשך מעליונו של עיגול לתחתיתו כידוע וד\"ל וביאור זה ידוע במ\"ש אל יתהלל חכם<sup data-n=\"793\">7</sup> בחכמתו גבור בגבורתו כו' כ\"א בזאת יתהלל<sup data-n=\"794\">8</sup> כו' שהזכיר ב' דברים השכל וידוע אותי ולעשות חסד ומשפט וצדקה בארץ דוקא כי באלה חפצתי נאם ה' ופי' חכם בחכמתו כו' ידוע שהן בחי' הג' קוין דאצילות חח\"ן ובג\"ה ודת\"י שהן הג' מדריגות דחכם וגבור ועשי'<sup data-n=\"795\">9</sup> והיינו בבחי' ע\"ס דאו\"י דוקא שלא לזה היה עיקר המכוון שבעצמות דלאו מכל אינון מדות כלל כו' כ\"א בזאת יתהלל כו' בזאת הוא בחי' המל'<sup data-n=\"796\">10</sup> שעומדת תחת קו האמצעי דת\"י<sup data-n=\"797\">11</sup> כו' ובריח התיכון מבריח כו' לפנימית הכתר דוקא ששם אא\"ס העצמות כידוע וז\"ש השכל וידוע אותי דוקא והוא מ\"ש לעשות חסד ומשפט<sup data-n=\"798\">12</sup> וצדקה בארץ דוקא שהוא בחי' או\"ח מלמטה למעלה דסוף מעשה שבארץ דוקא עבמ\"ת כנ\"ל שלזה הטעם ארץ קדמה כו' וז\"ש כי באלה חפצתי במח' תחלה כו' ומסיים נאם ה' שהוא בחי' המל'<sup data-n=\"799\">13</sup> וד\"ל. והיינו לפי שבחי' או\"ח דחסד כו' בארץ ג' קוין דתורה ועבודה וגמ\"ח שהעולם עומד<sup data-n=\"800\">14</sup> עליהם הוא שחוזר לקדמותו ממש כנ\"ל. (ולכך בהללו מן הארץ מסיים הודו על ארץ ושמים כו' כי עי\"ז נשגב שמו לבדו כמו שעבמ\"ת וד\"ל) ואמנם כ\"ז עלה בעצמותו כא' ולא שקדמה ארץ ג\"כ לפי שמהו\"ע נשגב לבדו (רק הודו לבד על ארץ כו' ובשמים שנקרא משפיע וכל צבא השמים אמר צוה ונבראו רק כדי שיהיה לו דירה כו' ולא בשביל עצמם כו') וז\"ש לע\"ל והיה אור הלבנה<sup data-n=\"801\">15</sup> כאור החמה כו' וכתיב לא יבא עוד שמשך<sup data-n=\"802\">16</sup> וירחך לא יאסף כו' אך כ\"ז בחי' משפיע ומקבל רק שיהיו שניהם שוין כמו שהיו שני המאורות הגדולים<sup data-n=\"803\">17</sup> כו' אבל ה' יהיה לך לאור עולם היינו למעלה מאור השמש והירח (שזהו כמו ענין שמים וארץ כו') דכתיב ביה השמים ושה\"ש לא יכלכלוך<sup data-n=\"804\">18</sup> כו' ואמנם ענין שניהם שוין בקומתן<sup data-n=\"805\">19</sup> היינו כמו שזו\"נ הן כלולים במקור א' שהוא בחי' כתר א' לשניהם והוא בחי' ת\"ת דבינה ולמעלה מעלה הוא בחי' ת\"ת דא\"א עד רום המעלות יש כתר א' לשניהם וע\"ד שהיה בשמש וירח למטה עד שטענה הלבנה<sup data-n=\"806\">20</sup> וכי אפשר לשני מלכים להשתמש בכתר אחד כו' שהוא ת\"ת דאימא בחי' כתר",[["787","1","<b>הללו את ה'</b>: תהלים קמח, א ואילך."],["788","2","<b>ע\"ס דאו\"י. . דאו\"ח</b>: ראה ע\"ח (שער מ\"ן ומ\"ד) של\"ט דרוש טו. תו\"ח וירא קג, ד ובהערה 39. שע\"ת ח\"א כז, א. לקמן סז, ב."],["789","3","<b>קורא הדורות מראש</b>: ישעי' מא, ד."],["790","4","<b>אנת הוא חד</b>: ת\"ז בהקדמה (יז, א)."],["791","5","<b>מבלי שימצא ראש וסוף</b>: ראה קהלת ג, יא."],["792","6","<b>העיגול. . מעלה ומטה</b>: נסמן לעיל יג, ב."],["793","7","<b>אל יתהלל חכם</b>: נסמן לעיל כה, ב."],["794","8","<b>כ\"א בזאת יתהלל</b>: ירמי' ט, כג."],["795","9","<b>חח\"ן. . דחכם גבור ועשי'</b>: ראה גם לעיל כה, ב."],["796","10","<b>בזאת. . המל'</b>: ראה ת\"ז ת\"ו (כא, ב ואילך). שערי אורה לר\"י גיקטלייא ש\"א (יד, ב). פרדס (שער ערכי הכינויים) שכ\"ג מערכת זאת. מאו\"א מערכת זאת ס\"ג."],["797","11","<b>המל'. . דת\"י</b>: נסמן לעיל כד, ב."],["798","12","<b>לעשות חסד ומשפט</b>: נסמן לעיל כה, ב."],["799","13","<b>נאום ה'. . המל'</b>: ראה גם קהלת יעקב בערכו."],["800","14","<b>דג' קווין. . שהעולם עומד</b>: אבות פ\"א מ\"ב."],["801","15","<b>והי' אור הלבנה</b>: ישעי' ל, כו. ראה סה\"מ תקס\"ה ח\"ב ע' תקצג."],["802","16","<b>לא יבא עוד שמשך</b>: ישעי' ס, כ."],["803","17","<b>שני המאורות הגדולים</b>: בראשית א, טז. ראה סה\"מ תקס\"ה שם."],["804","18","<b>השמים ושה\"ש לא יכלכלוך</b>: מלכים-א ח, כז."],["805","19","<b>שניהם שוין בקומתן</b>: נסמן לעיל כד, ב."],["806","20","<b>שטענה הלבנה</b>: ראה חולין ס, ב."]]],[2800530073,"אחד לשניהם כו' ולמעלה מעלה היינו מה שאמר קורא אני אליהם יעמדו יחדו שיצאו מן ההעלם לגילוי יחד כנ\"ל (ע\"ד שנז' בע\"ח בבחי' עיבור דזו\"נ באימא שהיו כלולים כאחד<sup data-n=\"807\">21</sup> ויצאו לגלוי וכן כששניהם שוין ומקבלים כתר אחד מת\"ת דאימא כו'):\n(יט) <b>ובכל</b> זה יובן מ\"ש ה' מלך גאות לבש כו' דהנה עד\"מ העיגול שסובב מלמעלה ומלמטה בשוה שאין בו בחי' מעלה ומטה כלל כנ\"ל כך הוא בחי' מקיף וסובב הכללי שמקיף לאבי\"ע למעלה ולמטה בשוה ממש כמ\"ש בשמים ממעל וכו' ששוה ומשוה שמים ממעל וארץ מתחת הרי יש עכ\"פ עומק רום ועומק תחת כמ\"ש שמים לרום וארץ לעומק<sup data-n=\"808\">22</sup> אלא שמשוה אותם וכוללם יחד בלי חילוק בין עמ\"ר לעמ\"ת כלל דהיינו מבלי שימצא ראש וסוף כנ\"ל והוא ענין הנ\"ל בטעם דמ\"ד שמים וארץ כאחד נבראו (וכמאמר דרבב\"ח שאמר לדידי חזי לי היכא דנשקי שמיא וארעא אהדדי<sup data-n=\"809\">23</sup> שהוא בחי' כח העליון משניהם שכוללם יחד כו') וז\"ש ה' מלך גאות בחי' גאות זה היינו בחי' התנשאות דמקיף זה הכללי שמקיף הכל כאחד מבלי שימצא ראש וסוף שהוא המתנשא מימות עולם לגמרי ע\"כ סובב את הכל כאחד (והוא ג\"כ ענין מח' אחת שצופה ומביט עד סוף כל הדורות בסקירה א'<sup data-n=\"810\">24</sup> דאע\"פ שיש בהן בחי' ראש וסוף בקריאתם מן ההעלם כמ\"ש קורא הדורות מראש זה ראשון בקריאה עד דור האחרון אבל סוקרם בסקירה א' כמו עד\"מ העיגול כדורי כו' והוא עד\"מ הידוע מבשרי אחזה כו' כמו שאדם מרגיש ויודע א\"ע מראשו לרגלו בבת אחת ממש מבלי קדימה לאבר א' על זולתו כלל אלא הכל בבת אחת שנקרא ידיעת עצמו בכללות ומתחלק לפרטות מראש לרגל כו') וע\"כ נקרא בשם לבוש מל' כמו הלבוש שמלביש א\"ע מראשו לרגלו בבת אחת כך מקיף זה הכללי נקרא גאות לבש שמתלבש בגאות והתנשאות זאת הסובב הכל מראש לסוף בבת אחת והוא בחי' מל' דא\"ס שלפני הקו\"ח שנקרא מחשבה אחת שעלה במחשבה פשוטה אנא אמלוך<sup data-n=\"811\">25</sup> טרם שנתפשט בפרטות ההשתלשלות דקו\"ח בבי\"ע כו' כידוע וז\"ש ה' מלך גאות לבש בחי' מלוכה זו נקרא לבוש דהיינו שנתלבש בה להיות מלכותו מכ\"ע ומובן מזה דגם בחי' גאות והתנשאות זאת על כל ההשתלשלות דאבי\"ע שמתנשא מימו\"ע בלי ימצא ראש וסוף כלל כנ\"ל גם זה אינו נקרא רק בחי' לבוש בעלמא לגבי אמיתית הגאות וההתנשאות שמצד עצמותו ומהותו ממש שנקרא המלך המרומם לבדו ממש כנ\"ל והענין הוא דבאמיתית עצמותו ממש לא שייך ל' התנשאות וגאות על ימות עולם כלל כי נשגב שמו לבדו מובדל ומרומם בערך מבחי' גדר שפע אור התפשטות למטה כלל שלא יפול בזה ענין סובב וממלא גם לא בחי' מקיף כללי הנ\"ל דגם בחי' מקיף כללי לא יתכן רק בדבר שבא לכלל השפעה עכ\"פ רק שהוא סובב ומקיף לראש וסוף בבת אחת בשוה והרי נקרא עכ\"פ בשם עמ\"ר ועמ\"ת אלא ששוה ומשוה לעמ\"ר ועמ\"ת דשמים וארץ כא' ממש (וכמשל המחשבה המקפת לכל הדורות בבת אחת",[["807","21","<b>עיבור דזו\"נ. . כאחד</b>: ראה ע\"ח (שער העיבורים) שכ\"ח פ\"א. פ\"ד."],["808","22","<b>שמים לרום וארץ לעומק</b>: משלי כה, ג."],["809","23","<b>לדידי חזי. . אהדדי</b>: ראה ב\"ב עד, א."],["810","24","<b>שצופה ומביט. . בסקירה א'</b>: נסמן לקמן קכא, ב."],["811","25","<b>אנא אמלוך</b>: נסמן לקמן קטו, א."]]],[2800530074,"שמחשבה זו גם כן מוגבלת ומגודרת בהקפה זאת רק לדורות אלא כעיגול המוגבל גם הוא שיש עיגול קטן ועיגול גדול כחומה מקפת לעיר שלפי ערך שטח ישוב העיר יוגבל גדר הקפת החומה אם קטנה או גדולה כידוע וכן עד\"מ הידיעה שיודע א\"ע מראשו לרגלו בבת אחת כנ\"ל שזהו רק גלוי אור וחיות הנפש הבא בכלי אברי הגוף בהתחלקות שונות מראש לרגל הוא שנקרא ידיעה והרגשה כללית שכוללת כל החיות הזה בבת אחת אבל מוגבל הוא לפ\"ע כלי הגוף בלבד הגם שנקרא מקיף כולם כידוע) אבל בחי' התנשאות וגאות שמצד מהו\"ע ממש אין לו שיעור למעלה ולמטה ולא יתכן לקרות שם בשם עמ\"ר ועמ\"ת ולא בשם מקיף כוללם יחד אחר שאין לו שיעור כלל דאא\"ס למעלה עד אין קץ ולמטה<sup data-n=\"812\">1</sup> עד אין תכלית (והגם שאומר בלשון מעלה דאין לו שיעור למעלה כו' הרי הוא רק שם המושאל דמה שנקרא בשם אין סוף ג\"כ שם המושאל דמה שהוא א\"ס להתפשטותו למעלה ולמטה הרי אין זה אמיתית עצמותו שנשגב לבדו בלי יפול בזה לשון התפשטות למעלה או למטה כלל רק ע\"ש הפעולה והמשכת האור מעצמותו הוא שנקרא כן כידוע ומבואר במ\"א בפי' אא\"ס שלשון א\"ס זה קאי על האור<sup data-n=\"813\">2</sup> והזיו ששייך בו לשון א\"ס להתפשטות ולא על עצמות המאור והכוונה באא\"ס שהאור הוא א\"ס ולא שהוא אור של א\"ס דבמהו\"ע לא יפול ל' א\"ס דלמה נקרא א\"ס הלא גם אין לו תחלה וע\"כ יש מהמקובלים אומרים שאא\"ס הוא אור הכתר שנקרא אור וזיו הא\"ס כמ\"ש בפרדס<sup data-n=\"814\">3</sup> ע\"ש) ולפ\"ז יובן דמ\"ש שמים וארץ כא' נבראו הוא רק בבחי' מקיף דגאות לבש הנ\"ל שמשוה עמ\"ר ועמ\"ת כמו העיגול כו' אבל אינו רק בחי' לבוש חיצוני בעלמא לגבי אמיתית הגאות והתנשאות עצמותו שלא יתכן שם ענין מקיף כלל עד שמקיף זה שכולל שמים וארץ כאחד הוא בא בדרך בריאה מאין ליש כמ\"ש כא' נבראו וכמ\"ש קורא אני יעמדו יחדיו כו' וכנ\"ל לפי שמהו\"ע נשגב לבדו (רק הודו על ארץ ושמים משום דאו\"ח חוזר לקדמותו ממש וד\"ל) ובכ\"ז יובן מ\"ש בשירת הים אשירה לה' כי גאה גאה ב\"פ כו' דהנה מבואר למעלה שבקי\"ס היה האור מבחי' העצמות ממש שלמעלה מבחי' העלם וגלוי סובב וממלא כו' וע\"כ ראתה גם שפחה על הים מה שלא ראה יחזקאל כו' אמנם גם בזה יש שני מדריגות זו למעלה מזו הא' בחי' גאות לבש הנ\"ל שזהו בחי' מקיף הכללי דעצמות המאצי' שכולל כל ההשתלשלות דהעלם וגלוי סובב וממלא שנקרא שמים וארץ בכלל כנ\"ל שע\"ז אמר שמים וארץ כא' נבראו כנ\"ל וזהו גאה הב' כמ\"ש ה' מלך גאות לבש בחי' לבוש חיצוני בעלמא לגבי אמיתית הגיאות והתנשאות שבמהו\"ע ממש שאין לו שיעור למעלה ולמטה כלל והיינו בחי' הגיאות אמיתית שבגאה הא' שהכונה גאה גאה גאה על גיאות הרי הגיאות והתנשאות העצמית רם ומתנשא על התנשאות שעל ימות עולם ונקרא מלך מרומם לבדו דכמו שהוא לבדו דוקא הוא מלך מרומם שאינו נקרא לבוש גיאות אלא בחי' התנשאות עצמית שמצד עצמותו ממש (וכמו ענין שעשועי המלך שבעצמותו<sup data-n=\"815\">4</sup> כמ\"ש במ\"א)",[["812","1","<b>דאא\"ס למעלה. . ולמטה</b>: נסמן לעיל ל, א."],["813","2","<b>א\"ס זה קאי על האור</b>: ראה תו\"ח שמות ע' עז. סה\"מ תקס\"ז ע' כב. ד\"ה אתה הראת במאמרי אדה\"א דברים ח\"א ע' שמ. נ\"ך ע' קלט ואילך. וש\"נ."],["814","3","<b>שאא\"ס. . הכתר. . בפרדס</b>: ראה גם שם (שער אם א\"ס הוא הכתר) ש\"ג פ\"א. פ\"ג. וראה ג\"כ פלח הרמון (שער עצמות וכלים) ש\"ד פ\"ג."],["815","4","<b>שעשועי המלך שבעצמותו</b>: ראה מאמרי אדה\"א קונטרסים ע' תקסט ואילך. הנסמן לקמן קכב, א."]]],[2800530075,"וזהו פי' הפשוט דגאה גאה גיאות על גיאות כמו מלך על המלכים שהתנשאותו הוא על התנשאות המלכים כמשל הנזכר במדרש באגוסטוס<sup data-n=\"816\">5</sup> (שהוא קיסר<sup data-n=\"817\">6</sup> ) יושב ומלך עומד שהמלך אע\"פ שהוא מרומם ומתנשא על עמו עומד לפני האגוסטוס שהוא מלך על המלכים כך התנשאות שבעצמות רם ומתנשא על מקיף כללי הנ\"ל עד שבלתי ערך ביניהם כלל כערך הגבול לבלתי בע\"ג כמו שהעיגול המקיף שמוגבל הוא לפ\"ע ישוב העיר שאין לו ערך לבלתי מוגבל כך אין ערך עמ\"ר ועמ\"ת שבמקיף הכללי לעולמות לגבי התנשאות מהו\"ע שהוא בלתי מוגבל לרום ולעומק כלל כי אין לו שיעור למעלה ולמטה כלל כנ\"ל וד\"ל ואמנם בקי\"ס שנעשה ההעלם גלוי זה היה מצד מקיף הכללי דמשפיע ומקבל שוין וכא' נבראו כנ\"ל שזהו ג\"כ למעלה מההשתל' דסובב וממלא כנ\"ל כמו העיגול אבל המדרגה הב' שהוא גיאות והתנשאות העצמות ממש לא היה מאיר רק בהעל' ולא בגלוי רק לע\"ל יאיר בגלוי וכמ\"ש אראנו נפלאות בחי' סדכ\"ס עצמו דלמת\"ב כלל אמנם הי' אור זה דהתנשאו' העצמו' ממש מאיר בגיאו' דלבוש מל' הנ\"ל כדי להפיל סוס ורוכבו בים וכתרגו' גאה גאה אתגאי על גיוותניא<sup data-n=\"818\">7</sup> כו' דהיינו על בחי' המנגד דקליפ' מצרי' שהוא בחי' כתר דקליפ'<sup data-n=\"819\">8</sup> כמ\"ש בזהר שהוא תנין הגדול<sup data-n=\"820\">9</sup> כו' ויש בזלעו\"ז כו' ג\"כ בחי' משפיע ומקבל דכר ונוק' והיינו סוס ורוכבו<sup data-n=\"821\">10</sup> שהרוכב הוא בחינת המקור המשפיע והסוס הוא אותיו' דנוק' כמ\"ש לסוסתי ברכבי פרעה<sup data-n=\"822\">11</sup> כמ\"ש במ\"א וכדי להשפיל גאים צריך להאיר מבחי' גאה גאה דוקא שהוא בחי' התנשאות העצמו' שאין מקום ושרש שם לחשך דקליפה כלל ומתבטלים ממציאותם סוס ורוכבו יחד בים העליון וזהו רמה בים העליון דוקא לפי שגאה גאה כו' (והטעם הוא לפי שבחי' אין האמיתי הרי הוא עצמו בחי' התנשאות העצמות שעי\"ז ישפיל הגאים דוקא שהן בבחי' יש גמור כשר של מצרי' שאמ' לי יאורי<sup data-n=\"823\">12</sup> כו' מפני שבטבע ההתנשאו' אמיתית שלא יוכל לסבול הישות והגיאו' וכמ\"ש רם על כל גוים<sup data-n=\"824\">13</sup> רם על גאים להשפילם כמו שאנו רואים שטבע המלך המרומם בעצם להשפיל את גאי' דוקא וירחם על השפלים דוקא לפי שהוא מנושא ומרומם באמת ע\"כ לא יסבול כל גיא ויש דוקא ולזאת משפיל גיאי' ומגביה שפלים דוקא כך למעלה להיותו ברוממו' האמיתי הוא גיא על גיותניא דוקא להשפיל גיאות דקליפה וכמ\"ש וברוב גאונך<sup data-n=\"825\">14</sup> דוקא כו' ולהגביה שפלי' דוקא כמ\"ש כי רם ה'<sup data-n=\"826\">15</sup> ושפל ירא' וכן מרו' וקדוש אשכון<sup data-n=\"827\">16</sup> ואת דכא ושפל רוח כו' משום שהוא מרום וקדוש דוקא וזה הי' כל עיקר סיבת גאולת ישראל מצד עוצם שפלותם ומצד גאות שר של מצרים וכך הוא בכל גלות וד\"ל):\n(כ) <b>ואחר</b> כל זה יובן מ\"ש ששת ימים תאכל מצות<sup data-n=\"828\">17</sup> וביום הז' עצרת לה' כו' דהנה פי' עצרת לשון מניעה ועיכוב<sup data-n=\"829\">18</sup> כמו ועצר השמים<sup data-n=\"830\">19</sup> כו' וגם לשון אסיפה וכנישה<sup data-n=\"831\">20</sup> כידוע ויובן זה עפ\"י כל הנ\"ל בהיות מבואר למעלה שבקי\"ס היו האור מבחי' העצמו' ממש ששם העל' וגלוי שוין ולזה אמ' ואתם תחרישון לא תתערו מידי<sup data-n=\"832\">21</sup> באתדל\"ת שבדיבור אלא בשתיקה לגמרי והוא להיות דלגבי העצמות ממש לא יגיע העלא' מ\"ן דתפלה כלל כ\"א בשפלות היותר",[["816","5","<b>במדרש באגוסטוס</b>: נסמן לעיל לג, ב."],["817","6","<b>קיסר</b>: ראה גם תוד\"ה כל ע\"ז י, ב."],["818","7","<b>אתגאי על גיוותניא</b>: ת\"א לבשלח טו, א."],["819","8","<b>מצרי'. . כתר דקליפ'</b>: ראה גם מאמרי אדה\"א בראשית ע' רצט. ויקרא ח\"א ע' סה. וש\"נ."],["820","9","<b>בזהר שהוא תנין הגדול</b>: ראה זהר בא לד, א."],["821","10","<b>דכר ונוק'. . סוס ורוכבו</b>: בשלח טו, א. ראה פע\"ח (שער הזמירות) ש\"ו פ\"ו. סידור האריז\"ל במקומו. שערי אורה פו, א."],["822","11","<b>לסוסתי ברכבי פרעה</b>: שה\"ש א, ט. ראה זהר בשלח מז, רע\"א. וראה גם מאמרי אדה\"א דרושי חתונה ח\"א ע' נד ואילך."],["823","12","<b>כשר. . לי יאורי</b>: ראה גם לקמן קמו, ב ובהנסמן במ\"מ לשם."],["824","13","<b>רם על כל גוים</b>: תהלים קיג, ד."],["825","14","<b>וברוב גאונך</b>: בשלח טו, ז. ראה גם מאמרי אדה\"א שמות ח\"ב ע' תקיח."],["826","15","<b>כי רם ה'</b>: תהלים קלח, ו."],["827","16","<b>מרו' וקדוש אשכון</b>: ישעי' נז, טו."],["828","17","<b>ששת ימים תאכל מצות</b>: פ' ראה טז, ח."],["829","18","<b>עצרת לשון מניעה ועיכוב</b>: ראה גם סידור כאן רפו, א. מאמרי אדה\"א דברים ח\"ד ע' א'רעט. וש\"נ."],["830","19","<b>עצרת. . ועצר השמים</b>: בסידור כאן ועצר את השמים ? עקב יא, יז."],["831","20","<b>עצרת. . לשון אסיפה וכנישה</b>: ראה גם סידור כאן. מאמרי אדה\"א דברים ח\"ד ע' א'שפו. וש\"נ."],["832","21","<b>ואתם תחרישון לא תתערו מידי</b>: נסמן לעיל לג, ב."]]],[2800530076,"עצומה והוא בחי' השתיקה לגמרי ולמעלה היינו ג\"כ בחי' עליי' המל' שהוא הדיבור למעלה מעלה מבחי' הדיבור כנ\"ל וזהו עצרת לשון מניעה ועיכוב והוא מ\"ש עצרת לה' אלקיך גם למעלה בה' אלקיך היינו בחי' זו\"נ כו' לפי שכל דיבור הוא בחי' ירידה והמשכה למטה כמו הדיבור למטה שהמחשבה יורדת לדיבור וכמ\"כ השכל והמדות יורדי' למחשבה בשעת הדיבור וכאשר נפסק אור השכל ממילא נפסק המח' מלירד לדיבו' ונפסק הדיבור ממילא לפי שהדיבור שרשו בכח השכל דאבא יסד ברתא<sup data-n=\"833\">1</sup> כידוע מפני שכח השכל הוא מקו' השכל הנגלה ונק' קדמו' השכל ואותיות הדיבור לא יצורפו רק מכח קדמות השכל<sup data-n=\"834\">2</sup> דוקא כמו התינוק גם שיודע ומשיג בשכלו להבחין בין טו\"ר וכה\"ג לא יצרף אותיות הדיבור עד שיש בו אור כח השכל דוקא והו' משיטעום טעם דגן שיודע לקרות או\"א כנ\"ל שמז' יש ראיה שבחי' גדלות השכל דוקא הוא המקור לצירופי אותיות הדיבו' וכמ\"ש לנפש חי' לרוח ממללא<sup data-n=\"835\">3</sup> וכמ\"ש במ\"א ולפ\"ז גם בגדול כאשר יופסק כח השכל והוא שיעלה לעצם הנפש שמשם נובע ממילא יופס' הדיבור מפני שגם הוא יעלה עמו לעצם הנפש כענין השתיקה דרב כשמקשה לו התלמי' כמו שאמ' שתק רב<sup data-n=\"836\">4</sup> כו' מפני שמתעל' כח שכלו בעצמותו כו' ונמצא הדיבו' שהוא סוף גלוי השכל עם כח השכל עולין יחד בעצמו' לפי שממקור א' באו וד\"ל. והנמשל מזה יובן למעלה בדיבור העליון דחכמה כח מ\"ה העליון הוא כמו הכח של השכל באדם למטה וסופו בא בצרופי דיבור העליון כידוע דפתח בחכמה<sup data-n=\"837\">5</sup> דהיינו בחי' פתיחה וגלוי דמקור החכמה בדיבור כמו פיה פתחה בחכמה<sup data-n=\"838\">6</sup> וכמאמרות דבראשית שנקרא מאמר פתוח<sup data-n=\"839\">7</sup> אך בעלות כח החכמה למעלה בעצמות ממילא נפסק אור הדיבור העליון ועולה גם הוא עם מקור החכמה בעצמות כמו השתיקה ממש שבאה מסיבת העלא' כח השכל כנ\"ל וד\"ל. וזהו הטע' שאמ' ואתם תחרישון בשתיקה לגמרי כי אור החכמה למעלה שנק' אור אבא עלה למעלה בעצמות דא\"ס ששם עולה דוקא בחי' פנימי' אור אבא שהוא פנימי' ע\"י<sup data-n=\"840\">8</sup> כידוע וזהו שאמ' מה תצעק אלי<sup data-n=\"841\">9</sup> שהוא שם הוי\"ה שהם מוחין דאו\"א שבז\"א שכולל לשם הוי\"ה דאצי' כידוע ואם כן אין העלאת מ\"ן דדיבור עולה שם להמשיך חסדי' דאב' מאחר שעל' למעל' כו' ואין הדב' תלוי רק בפנימי' ע\"י והוא פנימי' התענוג והרצון שלמעל' מן השכל והחכ' דאב' לגמרי וז\"ש בזוה' מה תצעק אלי בעתיקא תליא<sup data-n=\"842\">10</sup> שהוא למעלה ממזל ונוצר ונקה שרשי המוחין דאו\"א אמנם גם הוא עלה בעצמו' אא\"ס לפי שבקי\"ס היה גלוי האור דעצמות שלמעלה גם מן התענוג ורצון שעלה במחשבה דמל' דא\"ס שנק' גיאות לבש כנ\"ל וא\"כ אין טוב אלא השתיקה לגמרי שלא תתערו מידי רק ה' עצמו ילחם לכם<sup data-n=\"843\">11</sup> דהיינו מבחי' גאה גאה הנ\"ל שלמעלה מגיאות לבש שהוא ילחם לכם להשפיל גאים מטעם הנ\"ל כי רם ה' ושפל יראה ואין שפלות יותר מן השתיקה בביטול כל העצמות גם לא להעלות מ\"ן בתפלה שנק' קרבא<sup data-n=\"844\">12</sup> (וכחזקי' המלך<sup data-n=\"845\">13</sup> שלא היה חפץ להלחם כלל כו') וזהו עצרת לה' אלקיך למעלה עצרת זה הוא בחי' מניעה ועיכוב דהיינו בהעדר התפשטות אור בחכמ' ומדות ודיבור העליון שנק' הוי' אלקיך לפי שעלו למעלה במהו\"ע ממש ומשם היה נמשך להיות ה' איש מלחמה<sup data-n=\"846\">14</sup>",[["833","1","<b>דאבא יסד ברתא</b>: נסמן לקמן קי, ב."],["834","2","<b>ואותיות הדיבור. . קדמות השכל</b>: ראה לקמן קמד, א ובנסמן במ\"מ לשם."],["835","3","<b>לנפש חי' לרוח ממללא</b>: בראשית ב, ז ובת\"א שם."],["836","4","<b>שתק רב</b>: ביצה ו, א. ראה גם לקמן קא, א."],["837","5","<b>דפתח בחכמה</b>: ראה ע\"ח (שער השמות) שער מ\"ד פ\"א. הנסמן במאמרי אדה\"א דברים ח\"ג ע' א'מב."],["838","6","<b>פי' פתחה בחכמה</b>: משלי לא, כו."],["839","7","<b>מאמר פתוח</b>: ראה לעיל לב, סע\"ב ובהנסמן לשם."],["840","8","<b>פנימי' אור אבא. . ע\"י</b>: נסמן לקמן קכח, א."],["841","9","<b>מה תצעק אלי</b>: בשלח יד, טו."],["842","10","<b>בעתיקא תליא</b>: זהר בשלח מח, א. נב, ב. ראה גם לקמן קב, ב."],["843","11","<b>ה'. . ילחם לכם</b>: בשלח יד, יד."],["844","12","<b>בתפלה שנק' קרבא</b>: ראה סידור שער התפלה כג, ב. הנסמן במאמרי אדה\"א ויקרא ח\"א ע' תכח? דברים ח\"ג ע' א'עב."],["845","13","<b>וכחזקי' המלך</b>: איכ\"ר פ\"ד, טו."],["846","14","<b>ה' איש מלחמה</b>: בשלח טו, ג."]]]]});
